window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cirurgia-cir-4"]={"block":"medcurso:medcurso-cirurgia-cir-4","label":"Medcurso · CIR 4","count":420,"questions":[{"id":"medcurso-cirurgia-cir-4-343815","number":"343815","sourceNumber":"343815","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, 54 anos de idade, refere sangramento vermelho vivo durante as evacuações.\nOs sintomas iniciaram há 12 semanas, após\nepisódio de dificuldade para evacuar devido a fezes\nmuito endurecidas. Há 3 semanas notou saída de protuberância pelo ânus durante o esforço\nevacuatório que regredia espontaneamente. De acordo com o caso clínico, assinale a alternativa\ncorreta:","options":{"A":"Hemorroida externa.","B":"Hemorroida interna grau I.","C":"Hemorroida interna grau II.","D":"Hemorroida interna grau III."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-345503","number":"345503","sourceNumber":"345503","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 7 anos de idade, com quadro de desnutrição marasmático. Em\natendimento clínico na emergência, seu pai\nrelata que o garoto não come bem e tem constipação\nintestinal há 2 anos. Só consegue evacuar com supositório. Ao exame: estado geral decaído, pálido\n(++/4+). Pulmões e cardiovascular normais. Abdome bem distendido, com timpanismo aumentado e\ncom fecaloma palpável em abdome inferior. Qual conduta CORRETA para esse paciente em\nrelação ao fecaloma?","options":{"A":"No momento deve ser orientado só dieta laxante para idade e uso de lactulona oral.","B":"Iniciar desimpactação do fecaloma com uso da lactulona oral.","C":"No momento não realizar a desimpactação e iniciar o uso de leite de magnésio.","D":"Realizar desimpactação do fecaloma com solução de sorbitol ou polietilenoglicol dose\n1,0-1,5grs."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343824","number":"343824","sourceNumber":"343824","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Parotidectomia parcial por adenoma pleomórfico é cirurgia meticulosa que compreende\na dissecção do n. Facial em seu tronco e ramos e\npode apresentar desfechos negativos. Qual dos\nlistados abaixo seria o inesperado após este procedimento?","options":{"A":"Fístula salivar.","B":"Síndrome de Frey.","C":"Síndrome de Horner.","D":"Recidiva tumoral."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343826","number":"343826","sourceNumber":"343826","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quais dos seguintes cuidados NÃO são necessários em um recém-nascido com\ngastrosquise?","options":{"A":"Manipulação com luvas estéreis.","B":"Antibioticoterapia precoce.","C":"Cirurgia de urgência.","D":"Pesquisa de malformações associadas."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343828","number":"343828","sourceNumber":"343828","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A apresentação clássica de um Aneurisma de Aorta Abdominal (AAA) roto é o início\nsúbito de dor no flanco ou na região média\ndo abdômen, choque e presença de massa abdominal\npulsátil. Assinale a alternativa que oferece aumento do risco para rotura de um AAA?","options":{"A":"Sexo masculino.","B":"Diâmetro > 6,5cm.","C":"Expansão 0,3-0,6 cm/ano.","D":"Hipertensão controlada por mais de um medicamento."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343829","number":"343829","sourceNumber":"343829","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação à insuficiência venosa crônica, analise as afirmativas a seguir. I. O\ndiagnóstico da insuficiência venosa crônica\né eminentemente clínico. II. A avaliação da Insuficiência\nVenosa Crônica requer maior número de manobras semióticas e apresenta um grau de dificuldade\nmaior que a avaliação da doença arterial. III. O doppler de ondas contínuas é um método\nfrequentemente utilizado para avaliação após o exame clínico. IV. O ecocolordoppler venoso\ndetermina a localização e a morfologia das alterações, principalmente quando se objetiva o\ntratamento cirúrgico. Estão corretas as afirmativas:","options":{"A":"I, II, III e IV","B":"I e IV, apenas","C":"I, II e III, apenas.","D":"I, II e IV, apenas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343831","number":"343831","sourceNumber":"343831","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Pacientes submetidos a gastroplastia redutora em y de roux há 18 meses, evoluindo\ncom palpitações, cefaleia, diaforese, náuseas e\nempachamento 20 minutos após se alimentar. É\ncorreto afirmar:","options":{"A":"São sintomas mais comuns em gastrectomias a Bilroth I.","B":"O tratamento com modificações da dieta tem efeito limitado e raramente é suficiente para o\ncontrole dos sintomas.","C":"Os sintomas são decorrentes da ação de serotoninas, enteroglucagon e neurotensina.","D":"Trata-se de dumping tardio decorrente de calibração inadequada do pouch."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343834","number":"343834","sourceNumber":"343834","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 12 anos, relata que apresentou quadro de dor súbita em testículo\ndireito há 6 horas associado a náuseas e\nvômitos. Foi avaliado em serviço de urgência com\nsuspeita de escroto agudo. Em relação à torção testicular, qual das alternativas está correta?","options":{"A":"O Sinal de Prehn é patognomônico para torção testicular.","B":"A torção testicular intravaginal é a mais comum durante infância e adolescência.","C":"O Sinal de Angel está associado a posição mais verticalizada do testículo.","D":"A cintilografia testicular é o exame de escolha nos pacientes com escroto agudo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283314","number":"283314","sourceNumber":"283314","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Nas hemorroidectomias abertas a preservação de pontes cutâneos-mucoso visam\nprincipalmente:","options":{"A":"Uma melhor drenagem.","B":"Evitar incontinência anal.","C":"Evitar hemorragia pós operatória.","D":"Evitar estenose anoretal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283315","number":"283315","sourceNumber":"283315","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual a queixa principal de um paciente portador de fissura anal:","options":{"A":"Sangramento retal frequente.","B":"Dor intensa às evacuações.","C":"Secreção sero-sanguinolenta.","D":"Prurido anal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283317","number":"283317","sourceNumber":"283317","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Parotidectomia parcial por adenoma pleomórfico é cirurgia meticulosa que compreende\na dissecção do nervo Facial em seu tronco e ramos\ne pode apresentar desfechos negativos. Qual\ndos listados abaixo seria o menos esperado após este procedimento?","options":{"A":"Fístula salivar.","B":"Síndrome de Frey.","C":"Síndrome de Horner.","D":"Recidiva tumoral."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283320","number":"283320","sourceNumber":"283320","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente com histórico de hipertensão mal controlada e dislipidemia é levado a um\nserviço de urgência com dor lombar de\ninício súbito e hipotensão associada. Após manobras de\nressuscitação habituais, o paciente foi submetido a tomografia de abdome com contraste, onde a\nseguinte imagem foi obtida. Considerando os dados acima apresentados, marque a alternativa que\napresenta melhor correlação entre diagnóstico e terapêutica:","options":{"A":"Fratura patológica de vertebra lombar. Tratamento cirúrgico para fixação da lesão.","B":"Abcesso intracavitário. Punção ecoguiada para esvaziamento e drenagem da lesão.","C":"Aneurisma de aorta abdominal em expansão. Tratamento cirúrgico em caráter de emergência.","D":"Megacólon tóxico. Antibioticoterapia parental de largo espectro."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/283320.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283321","number":"283321","sourceNumber":"283321","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido inicia quadro de vômitos biliosos com 6 horas de vida, apresenta\ndistensão em andar superior do abdome. Na\nhistória pré-natal apresentava polidrâmnia. Qual o\nachado esperado no exame de imagem mais indicado para esclarecimento do quadro?","options":{"A":"Sinal da dupla bolha na radiografia simples de abdome.","B":"Distensão difusa de alças intestinais e ausência de gás no reto na radiografia simples.","C":"Sinal em alvo na USG.","D":"Imagem de massa na tomografia computadorizada."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283322","number":"283322","sourceNumber":"283322","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual exame permite confirmar o diagnóstico da doença de Hirschsprung?","options":{"A":"Manometria retal com ausência de reflexo de relaxamento do esfíncter interno.","B":"Anatomia patológica com espessamento das fibras musculares e imunohistoquimica com\naumento da atividade da desmolase.","C":"Anatomia patológica do reto com ausência de células ganglionares e imunohistoquímica com\naumento da atividade da acetilcolinesterase.","D":"Tomografia computadorizada do abdome com distensão de alças intestinais até a altura do reto."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283323","number":"283323","sourceNumber":"283323","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido com 3 semanas de vida inicia com vômitos alimentares pos prandiais,\napresentando piora progressiva ao longo dos dias. Voltou ao peso de nascimento. Chega para seu\natendimento com 10 dias de início dos sintomas. Qual dos seguintes achados não é esperado em\nseu exame físico?","options":{"A":"Ondas de Kussmaul abdominais.","B":"Oliva palpável em hipocôndrio direito.","C":"Desidratação.","D":"Distensão abdominal tão exuberante que exibe circulação colateral."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-281163","number":"281163","sourceNumber":"281163","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"São técnicas utilizadas no tratamento cirúrgico da doença hemorroidária, EXCETO:","options":{"A":"esfincterotomia posterior.","B":"hemorroidectomia fechada (Ferguson).","C":"hemorroidectomia aberta (Milligan-Morgan).","D":"anopexia anorretal (hemorroidectomia por grampeamento).","E":"desarterialização transanal das hemorroidas (THD)."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-251922","number":"251922","sourceNumber":"251922","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido, do sexo masculino, na terceira semana de vida, começou apresentar\nvômitos não-biliosos em jato e irritabilidade,\nmas sem recusa ao seio materno. Mãe nega febre e\nnão apresenta outras queixas. Ao exame físico, constatou-se perda ponderal (300g do peso do\nnascimento) e visualização de ondas de Kussmaul, orientadas do quadrante superior esquerdo\npara o direito, além de pequena tumoração próxima ao umbigo. Baseado nas informações, qual a\nhipótese diagnóstica?","options":{"A":"Refluxo gastro-esofágico.","B":"Intussuscepção intestinal.","C":"Estenose hipertrófica de piloro.","D":"Hérnia umbilical."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-251936","number":"251936","sourceNumber":"251936","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual dos abaixo NÃO é sinal de alerta para reconhecer a possibilidade de câncer na\ninfância?","options":{"A":"Reflexo branco na pupila.","B":"Manchas roxas no corpo.","C":"Fraturas ósseas sem trauma.","D":"Cefaléia esporádica."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-251949","number":"251949","sourceNumber":"251949","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Após realização de By Pass gástrico para tratamento de obesidade mórbida, qual das\nvitaminas abaixo deve ser suplementada e qual a repercussão disso?","options":{"A":"Vitamina B12 - anemia megalobástrica.","B":"Vitamina K - diatese hemorrágica.","C":"Vitamina C - anemia microcitica.","D":"Vitamina D - osteoporose."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-251955","number":"251955","sourceNumber":"251955","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente sexo masculino, 65 anos, diabético, tabagista com diagnóstico de DAOP\n(doença arterial obstrutiva periférica)\napresenta quadro clinico compatível com classificação de\nFontaine III. Diante de quadro qual a melhor conduta a ser realizada no tratamento:","options":{"A":"Tratamento clínico com controle dos fatores de risco.","B":"Tratamento clínico com vasodilatadores e anticoagulantes.","C":"Tratamento clínico com exercícios sob supervisão e farmacoterapia. A cirurgia pode ser\nconsiderada em caso de falha do tratamento clínico e/ou lesões arteriais focais.","D":"Quadro de isquemia crítica (risco de perda iminente do membro), intervenção cirúrgica essencial\ne imediata."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-217662","number":"217662","sourceNumber":"217662","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente de 5 meses de idade, em aleitamento materno exclusivo, inicia quadro súbito\nde dor abdominal, tipo cólica, que recorre\nem intervalos frequentes, acompanhado de esforço para\nevacuar. Inicialmente as fezes eram normais e posteriormente com presença de sangue e muco,\naspecto de geleia de morango. O menor evoluiu com irritabilidade e vômitos biliosos. Ao exame do\nabdome palpa-se uma massa mal definida e levemente dolorosa. Qual a hipótese diagnóstica MAIS\nPROVÁVEL?","options":{"A":"Apendicite aguda.","B":"Intussuscepção intestinal.","C":"Obstipação intestinal.","D":"Enterocolite necrotizante."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-217716","number":"217716","sourceNumber":"217716","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A constipação intestinal é um sintoma gastrointestinal bastante frequente nas consultas\npediátricas. Assinale a alternativa CORRETA com relação ao tema:","options":{"A":"As crianças menores de 1 ano devem ser tratadas com orientações dietéticas e óleo mineral.","B":"A origem da constipação intestinal é de causa orgânica em mais de 50% dos casos.","C":"O tratamento de manutenção consiste em realizar a desimpactação fecal com uso de enemas ou\nlaxantes orais.","D":"São causas secundárias de constipação intestinal: fibrose cística, doença celíaca, espinha bífida\ne uso de sais de ferro."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-217687","number":"217687","sourceNumber":"217687","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente 52 anos, masculino, vaqueiro, procedente de Xapuri-AC procura ambulatório\ndo Hospital das Clínicas com queixa de dor em\nMID associada a presença de úlcera em face\nmedial da perna. Ao exame físico observado varizes volumosas nesse membro, pigmentação de\npele, úlcera infectada em atividade, dermatofibrose, presença de frêmito. Relato de acidente de\ntrabalho com ferimento em coxa há 22 anos. Refere dor e edema com piora do quadro no fim do\ndia. Qual a provável causa dos sintomas?","options":{"A":"Aneurisma em MID.","B":"Pseaudoaneurisma.","C":"Fístula arteriovenosa.","D":"Insuficiência venosa CEAP Vl."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-217688","number":"217688","sourceNumber":"217688","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na síndrome compartimental em MIE, na reperfusão sanguínea pós-oclusão arterial\naguda, em uma vítima de trauma, deve ser primeiramente tratado com:","options":{"A":"Analgesia e antibióticos.","B":"Analgesia e heparinização sistêmica.","C":"Analgesia e alcalinização da urina.","D":"Fasciotomias amplas."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-217689","number":"217689","sourceNumber":"217689","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A síndrome de May-Thurner se caracteriza pela compressão da veia:","options":{"A":"Ilíaca comum direita.","B":"Ilíaca comum esquerda.","C":"Subclávia direita.","D":"Subclávia esquerda."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183187","number":"183187","sourceNumber":"183187","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sinal de dupla bolha:","options":{"A":"Aparece no Raio X contrastado de estômago e duodeno e faz parte do diagnóstico de Estenose\nHipertrófica do Piloro.","B":"Aparece na cintilografia renal e traduz a doença cística renal.","C":"Aparece na ultrassonografia hepática no caso de cistomatose hepática congênita.","D":"Aparece no Raio X simples de abdome nos casos de atresia de duodeno e pâncreas anular.","E":"Aparece no raio X simples de abdome, quando há pneumatose intestinal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183195","number":"183195","sourceNumber":"183195","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido de 20 dias de vida chega ao hospital com história de vômitos em jato,\nde conteúdo branco, há 3 dias. No exame físico, apresentava peristaltismo visível no epigastro e\npalpava-se tumoração em hipocôndrio direto, logo abaixo do lobo direto do fígado. A criança\napresentava-se emagrecida, mas em bom estado geral. Quanto à história pregressa, esse RN\nnasceu de termo, parto normal, sem intercorrências, com apgar de 8 e 10 no primeiro e quinto\nminutos, respectivamente. Qual o provável diagnóstico e qual exame complementar pode auxiliar\nno diagnóstico?","options":{"A":"Refluxo Gasto-esofágico, RX contrastado (SEED).","B":"Atresia de Duodeno, Raio X contrastado.","C":"Estenose Hipertrófica do Piloro, ultrassonografia.","D":"Atresia de Duodeno, Raio X simples.","E":"Estenose Hipertrófica do Piloro, RX contrastado."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183138","number":"183138","sourceNumber":"183138","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 62 anos, tabagista, com antecedentes de claudicação intermitente em\npanturrilha direita para 100 metros, procura\no pronto-socorro com quadro clínico típico de obstrução\narterial aguda no membro inferior direito. Não é cardiopata e, no exame arterial do membro inferior\nesquerdo, notou-se ausência de pulsos tibiais com fluxo monofásico ao Doppler. A provável causa\nda oclusão arterial é:","options":{"A":"Trombose.","B":"Embolia.","C":"Ateroembolismo.","D":"Aneurisma de aorta abdominal.","E":"Aneurisma de poplítea."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182637","number":"182637","sourceNumber":"182637","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 62 anos, com queixas de dor anal ao evacuar, adinamia e\nemagrecimento de 7 Kg nos últimos 2 meses. Qual o próximo passo para elucidação diagnóstica?","options":{"A":"Colonoscopia.","B":"Ressonância magnética da pelve.","C":"Retossigmoidoscopia.","D":"Toque retal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182648","number":"182648","sourceNumber":"182648","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente feminino, negra, 65 anos, hipertensa, diabética e dislipidêmica apresenta\núlcera em membro inferior esquerdo, região de\nmaléolo lateral, bastante dolorosa apesar de\napresentar tecido da granulação. Esta ulcera mais provavelmente deve ser classificada como:","options":{"A":"Hipertensiva.","B":"Neurológica.","C":"Venosa,","D":"Isquêmica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182651","number":"182651","sourceNumber":"182651","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A presença de \"sopro em maquinaria\" à ausculta de trajeto vascular é característica de:","options":{"A":"Estenose de artéria carotídea.","B":"Aneurisma dissecante de aorta torácica.","C":"Pseudoaneurisma.","D":"Fistula arteriovenosa."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159041","number":"159041","sourceNumber":"159041","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na Atenção Primária à Saúde, o médico deve realizar o manejo das indicações\ncirúrgicas nas diferentes fases do ciclo de\nvida. Assinale a afirmativa CORRETA sobre situações\ncirúrgicas na infância.","options":{"A":"Criança com hérnia inguinal deve ser encaminhada para cirurgia o mais breve possível.","B":"A idade ideal para cirurgia de testículos fora da bolsa é, atualmente, ao redor de 2 anos.","C":"Fimose deve ser operada até os 6 anos de idade, caso não haja regressão espontânea.","D":"Hidrocele vicariante não necessita de cirurgia e regride espontaneamente na grande maioria dos\ncasos."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159042","number":"159042","sourceNumber":"159042","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança de 3 anos, masculino, trazida ao ambulatório de cirurgia por apresentar saída\nde secreção mucóide por orifício de 2 mm na\nborda anterior do músculo esternocleidomastoídeo\n(na junção dos 2/3 superiores com o 1/3 inferior do músculo). Qual a hipótese diagnóstica?","options":{"A":"Fístula de cisto tireoglosso.","B":"Higroma cístico.","C":"Fístula de cisto branquial.","D":"Fístula salivar."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159064","number":"159064","sourceNumber":"159064","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 24 anos, deu entrada na UPA com queixas de dor em região anal\nintensa há 2 dias. Ao exame físico apresenta TA 38°C. À inspeção da região anal apresenta\ndiscreto abaulamento em quadrante inferior direito. Qual o próximo passo e qual a hipótese\ndiagnóstica?","options":{"A":"Realizar Ressonância nuclear magnética da pelve / tumor de reto.","B":"Realizar tomografia computadorizada da pelve / abscesso anal.","C":"Toque retal / abscesso anal.","D":"Realizar colonoscopia / tumor de reto."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159080","number":"159080","sourceNumber":"159080","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança de 4 anos de idade, internada na enfermaria do pronto-socorro por apresentar\ndesidratação severa, resultado de um quadro diarreico agudo. Evoluiu queixando-se de dor\nabdominal intensa e parada de eliminação de flatos e fezes. Ao exame físico, apresentava massa\ntubular em mesogástrio e o toque retal com muco e raias de sangue na luva. O diagnóstico mais\nprovável é:","options":{"A":"Obstrução intestinal por Ascaris lumbricoides.","B":"Intussuscepção intestinal.","C":"Íleo metabólico.","D":"Abscesso apendicular."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159083","number":"159083","sourceNumber":"159083","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quando um vaso sanguíneo apresenta dilatação designamos de Aneurisma. Esta\nafirmativa é verdadeira quando esta dilatação atinge qual percentual em relação ao tamanho\noriginal do vaso?","options":{"A":"25%.","B":"50%.","C":"75%.","D":"100%."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159086","number":"159086","sourceNumber":"159086","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente sexo masculino, 72 anos, tabagista e hipertenso apresenta quadro de Doença\nArterial Obstrutiva Periférica (DAOP) grave com dor de repouso com Classificação de Fontaine III.\nAo realizar o ITB (Índice Tornozelo - Braço) deveremos achar como resultado provavelmente o\níndice que mais representa o quadro acima:","options":{"A":"> 1,0.","B":"< 0,9.","C":"< 0,4.","D":"> 0,4."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-108660","number":"108660","sourceNumber":"108660","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quanto à classificação CEAP (Classificação Etiológica, Anatômica e Patológica)\npodemos afirmar que o tipo VI se refere a que tipo de úlcera?","options":{"A":"Isquêmica;","B":"Neurológica;","C":"Venosa;","D":"Hipertensiva."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-108679","number":"108679","sourceNumber":"108679","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação às alterações anatômicas da carótida, o chamado arco bovino, onde a\nartéria carótida Esquerda se origina do tronco branquio-cefálico, estão presentes em qual\nporcentagem da população?","options":{"A":"4%;","B":"8%;","C":"18%;","D":"27%;"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-108651","number":"108651","sourceNumber":"108651","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 65 anos, tabagista, durante check-up foi evidenciado ao raio-X de\ntórax massa arredondada de 5 cm e calcificação periférica em mediastino anterior. Seu exame\nfísico era normal. Qual a hipótese mais provável?","options":{"A":"Ganglioneuroma;","B":"Hemangioma;","C":"Timoma;","D":"Cisto broncogênico."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-108699","number":"108699","sourceNumber":"108699","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação à incidência de aneurisma de aorta abdominal podemos afirmar que em\nindivíduos masculinos, acima de 65 anos; nos indivíduos hipertensos e nos parentes de 1º grau o\nrisco deste serem portadores de aneurisma da Aorta Abdominal é de respectivamente:","options":{"A":"2%; 5% e 10%;","B":"5%; 12% e 25%;","C":"8%; 15% e 20%;","D":"10%, 15% e 12%."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-84465","number":"84465","sourceNumber":"84465","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente sexo feminino, negra, 55 anos, hipertensa, diabética e dislipidêmica apresenta\núlcera em MID, região de maléolo lateral,\nbastante dolorosa apesar de apresentar tecido da\ngranulação. Esta úlcera mais provavelmente deve ser classificada como:","options":{"A":"Isquêmica.","B":"Neurológica.","C":"Venosa.","D":"Hipertensiva.","E":"Mista."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-84481","number":"84481","sourceNumber":"84481","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente 58 anos, hipertenso, diabético, tabagista, fibrilação arterial crônica\ndislipidêmico. Relata claudicação para 450 m em\nMID. Relata que apresentou há cerca de 2h,\nquadro de dor aguda em membro contralateral de forte intensidade progressiva com diminuição de\nforça muscular, parestesia e frialdade. Faz uso de Ancorom e Digoxina. Baseado nos dados acima\nqual a hipótese diagnóstica mais provável para o quadro clínico acima?","options":{"A":"Trombose venosa profunda.","B":"Oclusão arterial aguda MID.","C":"Oclusão arterial aguda em MIE.","D":"Acidente vascular cerebral.","E":"Ataque isquêmico transitório."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66992","number":"66992","sourceNumber":"66992","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual dos seguintes achados na história e exame físico da criança portadora de\nconstipação intestinal NÃO é sugestivo de doença de Hirschsprung?","options":{"A":"Toque retal com fezes explosivas.","B":"Distensão abdominal importante.","C":"Presença de fecaloma volumoso.","D":"Desnutrição."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66924","number":"66924","sourceNumber":"66924","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na correção Endovascular de aneurisma de aorta abdominal infrarrenal de 06 cm de\ndiâmetro em um paciente de 64 anos do sexo masculino, hipertenso e diabético, observamos no\nintra-operatório a presença fluxo retrógrado por vias colaterais como artérias lombares, mesentérica\ninferior ou hipogástricas para dentro do saco aneurismático. Classificamos este vazamento como:","options":{"A":"Tipo I;","B":"Tipo II;","C":"Tipo III;","D":"Tipo IV;"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66939","number":"66939","sourceNumber":"66939","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente 35 anos, sexo masculino, durante um caçada no Seringal Oco do Mundo\nsofreu um tiro de espingarda calibre 12 em\nabdomên. Levado ao HUERB ( Hospital de Urgência e\nEmergência de Rio Branco) cerca de 03h após o ocorrido. Realizado Laparotomia exploradora com\nachado de explosão de Colón sigmoide com contaminação da cavidade abdominal com fezes\nconjuntamente com lesão de artéria ilíaca E com perda de substância. Diante do quadro qual a\nmelhor conduta a ser adotada em relação ao tratamento da lesão vascular:","options":{"A":"Ligadura;","B":"Enxerto ilíaco-femoral com veia safena reversa;","C":"Enxerto áxilo-femoral com prótese de politetrafluoretileno (PTFE);","D":"Enxerto femoral-femoral cruzado D-E com prótese de PTFE;"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66951","number":"66951","sourceNumber":"66951","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O sinal de Pratt é observado frequentemente nos quadro de:","options":{"A":"Trombose venosa profunda;","B":"Linfedema;","C":"Oclusão arterial aguda;","D":"Aneurisma de aorta abdominal roto;"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66936","number":"66936","sourceNumber":"66936","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma das melhores descobertas físicas que indicam a torção do cordão espermático é:","options":{"A":"Ausência do reflexo cremastérico;","B":"Posição transversa do testículo;","C":"Sons de doppler ausentes;","D":"Hidrocele reacional;"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-66977","number":"66977","sourceNumber":"66977","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A sequencia correta para o tratamento do tumor de reto baixo T3 e T4 sem metástase\ndistância é:","options":{"A":"Cirurgia;","B":"QT e RT;","C":"QT, cirurgia e RT;","D":"QT e RT, cirurgia, QT;"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-50108","number":"50108","sourceNumber":"50108","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente feminino, 47 anos, refere sangramento retal e dor intensa após as evacuações\ncom evolução de 2 meses. A paciente não tolera o\ntoque retal pela dor intensa desencadeada. Qual\na conduta mais adequada?","options":{"A":"Realizar o toque retal sob anestesia;","B":"Realizar colonoscopia;","C":"Realizar tomografia computadorizada da pelve;","D":"Realizar ultrassonografia transretal;"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-50097","number":"50097","sourceNumber":"50097","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 22 anos, sofreu ferimento de arma de fogo no terço médio da coxa direita,\nhá cerca de 20 dias. Apresenta na evolução\nclínica massa tumoral pulsátil em face interna da coxa\ndireita, com presença de frêmito e sopro contínuo. Baseados nestes dados pode-se afirmar que\nexiste qual tipo de lesão vascular?","options":{"A":"Lesão de artéria femural isolada;","B":"Fístula artério-venosa;","C":"Aneurisma de artéria femural;","D":"Pseudoaneurisma de artéria femural;"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-37146","number":"37146","sourceNumber":"37146","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Todas as abaixo são características das fissuras anais crônicas, exceto:","options":{"A":"plicoma sentinela.","B":"preferência pela localização lateral.","C":"papilite hipertrófica.","D":"exposição das fibras do músculo esfíncter interno.","E":"fibrose do esfíncter interno."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-37096","number":"37096","sourceNumber":"37096","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente com edema de MMII, pigmentação e eczema, além de uma úlcera cicatrizada\nhá quatro meses, apresenta Classificação\nEtiológica Anatômica e Patológica (CEAP):","options":{"A":"2","B":"3","C":"4","D":"5","E":"6"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-29352","number":"29352","sourceNumber":"29352","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A terapia física complexa, compressão elástica e inelástica, deve ser mais bem utilizada\nno tratamento:","options":{"A":"na doença oclusiva arterial crônica","B":"na oclusão arterial aguda","C":"na insuficiência venosa crônica","D":"no tratamento do linfedema","E":"no tratamento da trombose venosa conjuntamente com anticoagulantes orais"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343194","number":"343194","sourceNumber":"343194","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. A principal hipótese diagnóstica é:","options":{"A":"Displasia neuronal do tipo B.","B":"Constipação funcional.","C":"Doença de Hirschsprung.","D":"Enterocolite necrotizante."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343195","number":"343195","sourceNumber":"343195","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. Das alternativas abaixo, a conduta mais adequada é:","options":{"A":"Cirurgia de urgência.","B":"Tratamento clínico com ajuste dietéticos e laxativos, apenas.","C":"Dieta zero, sonda gástrica em drenagem e antibioticoterapia.","D":"Colostomia e abaixamento de cólon posteriormente ou manejo de cólon e tratamento cirúrgico\nendoanal sem colostomia."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343197","number":"343197","sourceNumber":"343197","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre as oclusões arteriais agudas, assinale a incorreta.","options":{"A":"Muitos êmbolos têm origem no coração e, em particular, no coração esquerdo, a partir da\nfragmentação de trombos intracavitários.","B":"A causa mais frequente da formação dos trombos é a fibrilação atrial que acompanha as lesões\nda valva mitral de origem reumática, o\nhipertireoidismo, o infarto agudo do miocárdio (IAM) e a\nmiocardiosclerose.","C":"Dentre as valvopatias, a mais frequente como causa de embolia é a doença valvar mitral, em\nparticular a estenose mitral de origem reumática.","D":"A endocardite bacteriana aguda ou subaguda é causa rara de embolia arterial, pois acomete\nmais as câmaras direitas do coração, e não\npropiciam a formação de trombos murais nos átrios e\nnos ventrículos."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343198","number":"343198","sourceNumber":"343198","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a doença arterial obstrutiva periférica dos membros inferiores, assinale a\nincorreta.","options":{"A":"A obstrução da artéria femoral superficial é encontrada em cerca da metade dos casos de\ndistúrbios isquêmicos dos membros pélvicos. Embora a obstrução geralmente seja inicialmente\nunilateral, ao final de 4 anos, 75% dos pacientes desenvolvem oclusões bilaterais.","B":"Dos exames que permitem visibilizar a árvore circulatória, o EcoDoppler colorido é\n\ncontra-indicado pois tem restrição na avaliação da circulação arterial dos membros inferiores, e não\nfaz análise qualitativa as dimensões do processo obstrutivo assim o grau de instabilidade do vaso.","C":"Embora a aterotrombose seja a patologia responsável pelos sintomas isquêmicos em mais de\n90% dos casos, outras doenças devem ser\nlembradas, como a tromboangiite obliterante, outras\narterites, doença cística da adventícia, síndrome de aprisionamento da poplítea e as sequelas de\ntraumatismos.","D":"A classificação empregada para o estadiamento da doença em questão é a clássica de\nFontaine. Estágio I: assintomático, II:\nclaudicação intermitente, III: dor isquêmica em repouso, IV:\nlesões tróficas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-315181","number":"315181","sourceNumber":"315181","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Menino, 2 anos, é trazido ao pronto-socorro com história de palidez, choro e vômitos.\nExame físico: regular estado geral, FC: 144\nbpm, FR: 30 irpm, PA: 78 x 38 mmHg, descorado ++/4,\ndor leve à palpação abdominal. Toque retal: presença de coágulos e sangue, tipo geleia de\n\n?morango?. Qual a hipótese diagnóstica?","options":{"A":"Doença de Crohn","B":"Colite pseudomembranosa","C":"Divertículo de Meckel","D":"Invaginação intestinal","E":"Polipo intestinal"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313446","number":"313446","sourceNumber":"313446","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente masculino previamente hígido, sem nenhuma comorbidade antenatal, hoje\ncom 6 semanas de vida, é levado ao\natendimento de urgência pela mãe com queixa de vômitos de\ninício há 7 dias. A mãe descreve vômitos de conteúdo alimentar, mais intensos após as mamadas,\nem jato, sem exteriorização de conteúdo bilioso. Associa a este período uma piora no estado geral,\nbem como perda ponderal. Nega febre. Nega diarreia. Nega trauma. Ao exame físico encontra-se\ndescorado, desidratado, taquipneico, normocárdico, anictérico, acianótico, afebril. Aparelho\ncardiopulmonar sem alterações importantes. Ausência de sinais de irritação meníngea, com\nfontanela anterior discretamente deprimida. Abdome com ruídos, flácido, distendido em andar\nsuperior, indolor, sem sinais de irritação peritoneal. Ausência de massas palpáveis. Foi realizado\nexames séricos que evidenciaram discreta leucocitose e alcalose metabólica. Foi submetido a\nradiografia de abdome abaixo. O tratamento definitivo mais adequado para este caso é:","options":{"A":"Tratamento clínico com inibidor de bomba de prótons e orientação dietética.","B":"Piloromiotomia.","C":"Ligadura da fístula traqueoesofágica e anastomose esôfago-esofágica término-terminal se\nhouver distância entre os cotos menor que 3 vértebras.","D":"Gastrostomia e anastomose esôfago-esofágica tardia."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313447","number":"313447","sourceNumber":"313447","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente masculino previamente hígido, sem nenhuma comorbidade antenatal, hoje\ncom 6 semanas de vida, é levado ao\natendimento de urgência pela mãe com queixa de vômitos de\ninício há 7 dias. A mãe descreve vômitos de conteúdo alimentar, mais intensos após as mamadas,\nem jato, sem exteriorização de conteúdo bilioso. Associa a este período uma piora no estado geral,\nbem como perda ponderal. Nega febre. Nega diarreia. Nega trauma. Ao exame físico encontra-se\ndescorado, desidratado, taquipneico, normocárdico, anictérico, acianótico, afebril. Aparelho\ncardiopulmonar sem alterações importantes. Ausência de sinais de irritação meníngea, com\nfontanela anterior discretamente deprimida. Abdome com ruídos, flácido, distendido em andar\nsuperior, indolor, sem sinais de irritação peritoneal. Ausência de massas palpáveis. Foi realizado\nexames séricos que evidenciaram discreta leucocitose e alcalose metabólica. Foi submetido a\nradiografia de abdome abaixo. O distúrbio ácido-base encontrado é mais bem justificado na\nseguinte alternativa.","options":{"A":"A alcalose metabólica é a alteração mais comum encontrada nestes pacientes devido a grande\nperda de ácidos pelos vômitos incoercíveis\ne repetidos.","B":"A alcalose metabólica é a alteração menos encontrada nestes pacientes devido a grande perda\nde bicarbonato, devido ao aumento da excreção\nrenal de bicarbonato.","C":"A alcalose respiratória é a alteração mais comum encontrada nestes pacientes devido a grande\nperda de ácidos pelos vômitos incoercíveis\ne repetidos.","D":"A alcalose metabólica não é o distúrbio mais comum encontrado nestes pacientes. Tratando-se\nda patologia acima a acidose metabólica é o\nachado mais comum em pacientes com este\ndiagnóstico devido a grande perda volêmica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313448","number":"313448","sourceNumber":"313448","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente com 2 dias de vida, em exame de rotina no alojamento conjunto que precede\na alta, foi evidenciado que o meato uretral\nse apresentava em região distópica, conforme ilustrado\nna figura abaixo. Manteve-se com diurese espontânea durante a internação. Ao exame: gônadas\ntópicas em escroto, falo formado com fenótipo masculino, glande com placa uretral aberta, e meato\nuretral disposto em região ventral peniana. O principal diagnóstico é:","options":{"A":"Fimose.","B":"Epispádia.","C":"Hipospádia.","D":"Criptorquidia."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/313448.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313449","number":"313449","sourceNumber":"313449","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente com 2 dias de vida, em exame de rotina no alojamento conjunto que precede\na alta, foi evidenciado que o meato uretral\nse apresentava em região distópica, conforme ilustrado\nna figura abaixo. Manteve-se com diurese espontânea durante a internação. Ao exame: gônadas\ntópicas em escroto, falo formado com fenótipo masculino, glande com placa uretral aberta, e meato\nuretral disposto em região ventral peniana. A principal conduta no momento é:","options":{"A":"Tratamento tópico com corticosteroide.","B":"Cirurgia de urgência.","C":"Aguardar até os 12 meses, e caso não haja resolução do quadro, indicar orquidopexia.","D":"Cirurgia eletiva após os 6 meses de vida."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/313449.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313450","number":"313450","sourceNumber":"313450","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre o procedimento clássico de MAGPI (avanço meatal com glanduloplastia),\nilustrado abaixo, assinale a correta.","options":{"A":"É preconizado no tratamento dos pacientes portadores do complexo extrofia vesical-epispádia.","B":"É preconizado para tratamento de hipospádias proximais.","C":"É preconizado para tratamento de hipospádias distais.","D":"É preconizado para tratamento de pênis torto congênito com meato glandar tópico."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/313450.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313452","number":"313452","sourceNumber":"313452","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A apendicite aguda em neonatos e lactentes, faixa etária incomum para a apresentação\ndesta patologia, tem forte associação com:","options":{"A":"Estenose hipertrófica de piloro.","B":"Atresia duodenal.","C":"Atresia esofágica.","D":"Doença de Hirschsprung."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313453","number":"313453","sourceNumber":"313453","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Abaixo estão representadas as duas formas mais comuns de defeitos congênitos da\nparede anterior do abdome. Sobre tais defeitos, assinale a correta.","options":{"A":"A figura 1 é classificada como onfalocele, defeito da parede anterior em que não há contato do\nconteúdo mesentérico com o líquido amniótico, considerada situação menos urgente do ponto de\nvista cirúrgico.","B":"A figura 2 é classificada como onfalocele, um defeito na parede abdominal, na inserção do\ncordão umbilical, com herniação de órgãos\nabdominais para fora da cavidade abdominal, recoberta\npor uma membrana.","C":"A figura 1 é classificada como gastrosquise, defeito da parede anterior em que não há contato\ndo conteúdo mesentérico com o líquido amniótico,\nconsiderada situação menos urgente ponto de\nvista cirúrgico.","D":"A figura 2 é classificada como onfalocele, um defeito na parede abdominal, situado a direita do\ncordão umbilical, com herniação de órgãos\nabdominais para fora da cavidade abdominal, recoberta\npor uma membrana."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313454","number":"313454","sourceNumber":"313454","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido a termo, de 38 semanas, parto cesáreo indicado por sofrimento fetal,\napresenta desconforto respiratório alguns minutos após o nascimento e é, então, necessário\nintubação orotraqueal e cateterização umbilical devido a condição patológica já diagnosticada em\nexames pré-natais. É transferido a unidade de terapia intensiva neonatal e realizado a radiografia\nde tórax abaixo. A principal hipótese diagnóstica é:","options":{"A":"Malformação adenomatosa cística.","B":"Atresia de esôfago.","C":"Atresia duodenal.","D":"Hérnia diafragmática congênita."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/313454.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-313455","number":"313455","sourceNumber":"313455","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido a termo, de 38 semanas, parto cesáreo indicado por sofrimento fetal,\napresenta desconforto respiratório alguns minutos após o nascimento e é, então, necessário\nintubação orotraqueal e cateterização umbilical devido a condição patológica já diagnosticada em\nexames pré-natais. É transferido a unidade de terapia intensiva neonatal e realizado a radiografia\nde tórax abaixo. Sobre a principal hipótese acima, assinale a correta.","options":{"A":"Trata-se de uma emergência cirúrgica e deve ser reparada de imediato.","B":"Trata-se de uma condição clínica grave, que geralmente é associada a hipertensão pulmonar e\nhipoplasia do pulmão ipsilateral a lesão.","C":"É tratada com ventilação de alta frequência prolongada e de rotina para se reduzir a\nmortalidade.","D":"É tratada com drenagem torácica de imediato."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/313455.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-315208","number":"315208","sourceNumber":"315208","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O que significa intussuscepção intestinal","options":{"A":"Torção do intestino.","B":"Isquemia mesentérica.","C":"Formação se bridas.","D":"Telescopagem do intestino em segmento adjacente.","E":"O mesmo que volvo intestinal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-279048","number":"279048","sourceNumber":"279048","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dentre as anomalias abaixo, qual a que não esta associada a atresia de duodeno?","options":{"A":"Síndrome de Down.","B":"Síndrome de Turner (disgenesia gonadal XO).","C":"Pâncreas anular.","D":"Atresia de esôfago."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-279052","number":"279052","sourceNumber":"279052","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual é a complicação mais temida e potencialmente fatal da doença de Hirschsprung\nnão diagnosticada?","options":{"A":"Perfuração intestinal.","B":"Volvo.","C":"Enterocolite.","D":"Neoplasia."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-278641","number":"278641","sourceNumber":"278641","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre torção de testículo, assinale a incorreta.","options":{"A":"É a emergência mais comum do trato geniturinário na infância.","B":"A distorção cirúrgica imediata com a fixação do testículo é o esteio da terapia.","C":"A torção do testículo ocorre com maior frequência no final da infância e início da adolescência.","D":"Torção intravaginal é mais comum em recém-nascidos."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-278642","number":"278642","sourceNumber":"278642","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido a termo, 38 semanas, apresentando dificuldade na amamentação,\nvômitos logo após as tentativas do aleitamento\ncom impossibilidade de progressão de sonda\nesofagogástrica. Foi submetido ao exame radiológico contrastado abaixo. A principal hipótese\ndiagnóstica é:","options":{"A":"Estenose hipertrófica de piloro.","B":"Atresia Duodenal.","C":"Atresia de esôfago sem fístula distal.","D":"Atresia de esôfago com fístula distal."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/278642.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-280439","number":"280439","sourceNumber":"280439","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Nos pacientes com insuficiência cardíaca e disfunção miocárdica, em tratamento\nambulatorial de doença arterial periférica é contra indicado o uso de:","options":{"A":"Antiagregantes plaquetários.","B":"Estatinas.","C":"Beta-bloqueadores não seletivos.","D":"Cilostazol."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-278650","number":"278650","sourceNumber":"278650","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"É o tumor sólido extracraniano mais comum em lactentes e crianças, representando 8%\n\n- 10% de todos os tumores da infância e 15% de todas as mortes por câncer na população\npediátrica.","options":{"A":"Tumor de Wilms","B":"Tumor de células germinativas","C":"Hepatoblastoma","D":"Neuroblastoma"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-231350","number":"231350","sourceNumber":"231350","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente, 23 meses, sexo feminino, é levada ao hospital pelos pais, com história de\naumento de volume abdominal, dor óssea,\nemagrecimento, palidez, febre, apatia e irritabilidade há\ndois meses. Exame físico: regular estado geral, hipertensão arterial, protusão de globo ocular\nesquerdo, associado à equimose periorbitária e extensa tumoração palpável em loja renal direita de\nlimites imprecisos, atravessando a linha média do abdômen. A hipótese diagnóstica mais provável\né:","options":{"A":"Neuroblastoma.","B":"Tumor de Wilms.","C":"Linfoma não Hodgkin.","D":"Tumor do córtex suprarrenal.","E":"Linfoma Hodgkin"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249394","number":"249394","sourceNumber":"249394","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale quais as alterações estão apresentadas na figura abaixo:","options":{"A":"Epispádia","B":"Sinéquia","C":"Fimose","D":"Hipospádia"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/249394.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249301","number":"249301","sourceNumber":"249301","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A etiologia mais comum dos aneurismas de aorta é:","options":{"A":"Degenerativa.","B":"Inflamatória.","C":"Infecciosa.","D":"Congênita."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249406","number":"249406","sourceNumber":"249406","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a alternativa correta em relação à fimose:","options":{"A":"Fimose é a incapacidade de retrair o prepúcio e exteriorizar a glande por completo.","B":"Fimose é a presença de prepúcio longo (excesso de pele) com presença de secreção fétida se\nnão realizada a higiene correta.","C":"Fimose é a presença de prepúcio incompleto, redundante na região dorsal do pênis e ausente\nou hipotrófico ventralmente.","D":"Fimose é a alteração em que o pênis está parcial ou completamente escondido sob o coxim\ngorduroso da região pré-púbica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249407","number":"249407","sourceNumber":"249407","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a alternativa correta sobre a definição de criptorquidia:","options":{"A":"Criptorquidia é definida como a presença de ereção não fisiológica, prolongada e dolorosa.","B":"Criptorquidia é definida como a presença de testículos, que podem ser atróficos, em locais\nanatômicos distintos do normal.","C":"Criptorquidia é a presença de testículos na bolsa escrotal, porém com um movimento\nascendente.","D":"Criptorquidia é a condição em que a pele peniana não tem formato cilíndrico, mas sim\naproximadamente cônico."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249417","number":"249417","sourceNumber":"249417","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Neonato com 2 horas de vida, a termo, apresenta desconforto respiratório agudo, é\nsubmetido à radiografia de tórax sob suspeita de hérnia diafragmática. A lesão congênita localizada\nântero-medial que caracteriza um defeito da junção esternocondral é mais comum na hérnia:","options":{"A":"Diafragmática traumática.","B":"Petit.","C":"Bochdalek.","D":"Morgagni."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-212207","number":"212207","sourceNumber":"212207","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dadas as afirmativas sobre cirurgia bariátrica e metabólica, I. Paciente obesa, 27 anos,\nsem patologias prévias, com desejo de ser submetida à cirurgia bariátrica, apresentando peso de\n126 kg e altura de 1,80 metros, possui indicação de cirurgia bariátrica. II. De acordo com o\nMinistério da Saúde, hipertensão portal, com varizes esofagogástricas, doenças imunológicas ou\ninflamatórias do trato digestivo superior que venham a predispor o indivíduo a sangramento\ndigestivo ou outras condições de risco são consideradas contraindicações para cirurgia bariátrica.\n\nIII. A gastrectomia vertical vem ganhando espaço entre as técnicas de cirurgia bariátrica por ser de\nfácil execução, baixos índices de complicações e com bons resultados em relação à perda\nponderal. A grelina, hormônio que induz à fome, está aumentada no pós-operatório dessa cirurgia\ncontribuindo ainda mais para perda de peso. verifica-se que está(ão) correta(s)","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e II, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-219900","number":"219900","sourceNumber":"219900","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente do sexo masculino, na quinta semana de vida, previamente hígido, apresenta\nvômitos não biliosos há 1 semana, em jato.\nAo exame físico nota-se perda de peso e sinais de\ndesidratação leve. Considerando tratar-se de patologia com indicação cirúrgica, o diagnóstico MAIS\nPROVÁVEL é:","options":{"A":"Atresia jejunal","B":"Estenose hipertrófica de piloro","C":"Hérnia inguinal estrangulada.","D":"Volvo intestinal agudo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215472","number":"215472","sourceNumber":"215472","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à Síndrome de Prune Belly.","options":{"A":"É uma afecção congênita caracterizada por flacidez abdominal, hipospádia e dilatação variável\ndo trato urinário.","B":"As características clínicas são bastante evidentes, o que permite um diagnóstico fácil e precoce\nao nascimento.","C":"O abdome tem aspecto flácido e saliente, frequentemente assimétrico, com áreas de maior\nflacidez, particularmente nos segmentos médio e\ninferior, causado por uma deficiência importante\nda musculatura da parede abdominal.","D":"Os testículos são intra-abdominais, localizados na altura dos vasos ilíacos."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215486","number":"215486","sourceNumber":"215486","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A atresia de esôfago é a malformação mais frequente e conhecida do aparelho\ndigestivo do recém-nascido. Assinale a alternativa INCORRETA:","options":{"A":"O diagnóstico antenatal é suspeitado na presença do poli-hidrâmnio materno e pode até ser\nvisualizada ao ultrassom.","B":"Deve ser idealmente diagnosticada na sala de parto, durante a reanimação, pela parada de\nprogressão da sonda nasogástrica, prescindindo de exames contrastados.","C":"Em casos duvidosos, deve-se realizar uma radiografia com mínima quantidade de contraste\nhidrossolúvel.","D":"A atresia de esôfago é uma emergência cirúrgica, devendo ser operada logo após o nascimento."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-216307","number":"216307","sourceNumber":"216307","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre os Cistos Branquiais, marque a opção INCORRETA.","options":{"A":"Trata-se de tumor lateral no terço médio da borda anterior do músculo esternocleidomastoideo.","B":"É bilateral na maior parte dos casos.","C":"O diagnóstico é clínico.","D":"São congênitos e resultantes de defeitos do desenvolvimento embrionário."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-219857","number":"219857","sourceNumber":"219857","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente de 3 meses que, segundo a mãe, apresenta evacuações espontâneas com\nfezes explosivas, mas de consistência habitual\npara um lactente, a cada 15 dias. Está fazendo uso\nde supositório a cada 3 dias para que ocorra a evacuação. Há relato de distensão abdominal e\ncólicas frequentes. Ao exame físico, o abdome é tenso e difusamente doloroso. O lactente está em\naleitamento materno exclusivo. Considerando os possíveis diagnósticos para o quadro, a conduta e\ndiagnóstico MAIS ADEQUADOS são:","options":{"A":"Iniciar dieta laxativa com suco de frutas e considerar como hábito intestinal do lactente em\naleitamento.","B":"Prescrever laxativo por via oral e considerar como constipação crônica funcional","C":"Solicitar colonoscopia com biópsia e considerar como doença inflamatória intestinal.","D":"Solicitar enema baritado por via baixa e considerar como aganglionose colônica."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215203","number":"215203","sourceNumber":"215203","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual das alternativas abaixo NÃO é uma complicação frequente da dissecção venosa\nperiférica?","options":{"A":"Flebite.","B":"Trombose venosa.","C":"Celulite.","D":"Enfisema."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215207","number":"215207","sourceNumber":"215207","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O enfisema lobar congênito é definido como a hiperinsuflação de um lobo pulmonar que\nse manifesta no período neonatal. Assinale a\nalternativa INCORRETA.","options":{"A":"O enfisema lobar acomete, principalmente, os lobos superiores (predominando o esquerdo) e, às\nvezes, o lobo médio.","B":"O quadro clínico é caracterizado por graus diferentes de insuficiência respiratória advinda da\nhipoventilação do parênquima pulmonar normal comprimido pelo lobo insuflado.","C":"O diagnóstico pós-natal é feito, na maioria das vezes, pela radiografia simples de tórax.","D":"O tratamento do enfisema lobar congênito sem causa aparente ou por broncomalácia consiste\nna drenagem da área hiperinsuflada do parênquima\npulmonar."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215496","number":"215496","sourceNumber":"215496","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A moléstia de Hirschsprung é a suboclusão intestinal baixa decorrente da ausência de\ngânglios nervosos entéricos. Assinale a alternativa INCORRETA.","options":{"A":"O quadro clínico é de retardo de eliminação do mecônio, distensão abdominal acentuada e\nevacuação explosiva ao toque.","B":"A doença praticamente inexiste em prematuros e os sintomas, quase sempre, se iniciam após o\nsegundo mês de vida, predominando no sexo\nfeminino.","C":"O diagnóstico é feito pelo enema opaco que mostra o cólon proximal dilatado e o terminal\nestreitado, formando o clássico cone de transição.","D":"O tratamento é cirúrgico e consiste na ressecção do segmento ganglionar e reconstrução do\ntrânsito anal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-212233","number":"212233","sourceNumber":"212233","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"José Vinícius, 1 mês e 5 dias de vida, há uma semana começou a apresentar episódios\nde vômitos, em jato, com restos alimentares, 30\nminutos após a alimentação, porém com fome\ninsaciável, perda de peso e desidratação. À palpação do abdome, notou-se distensão da região\nepigástrica e ondas de Kussmaul após a alimentação. Nesse contexto, qual é a principal hipótese\ndiagnóstica e como essa hipótese pode ser confirmada?","options":{"A":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do duplo trilho\ne sinal do cordão, obtidos quando pequenas\nquantidades de líquido podem ser vistas aprisionadas entre as dobras de mucosa ecogênica\nredundante.","B":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do mamilo\nmucoso, que corresponde ao anel hiperecoico do\nmúsculo pilórico hipertrofiado em torno da mucosa ecogênica centralmente localizada.","C":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do alvo,\nobtido quando pequenas quantidades de líquido podem\nser vistas aprisionadas entre as dobras de mucosa ecogênica redundante.","D":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal da cérvice,\nque corresponde à protrusão de mucosa pilórica\nredundante em direção ao antro gástrico.","E":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do ombro,\nque corresponde à endentação da camada muscular\nno antro cheio de líquido."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-181429","number":"181429","sourceNumber":"181429","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os gânglios linfáticos cervicais são frequentemente envolvidos po rmetástases de\ntumores malignos de cabeça e pescoço. Uma\nabordagem sistemática da dissecção do pescoço foi\npublicada por George Washington Crile e, a partir de então, houve modificação das técnicas de\nacordo com o sítio primário da lesão e seu estadiamento. Quanto aos esvaziamentos cervicais, é\ncorreto afirmar:","options":{"A":"a radioterapia pré-operatória não altera os índices de isquemia e necrose de retalhos de pele,\nprincipalmente em pacientes que receberam doses acima de 50 Gy.","B":"o nervo frênico, cujo trajeto percorre a superfície no músculo trapézio, não pode ser\nvisibilizado e\npreservado, principalmente nos esvaziamentos completos.","C":"a embolia gasosa pode ocorrer em lesões das veias linguais, que colabam com dificuldade por\npercorrerem trajetos entre duas camadas de fáscia cervical.","D":"a lesão de vasos linfáticos, particularmente o ducto torácico, pode resultar numa complicação\nrelativamente grave.","E":"as principais complicações decorrentes de lesões ou ligaduras arteriais são relativas à veia\nsubclávia."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-181435","number":"181435","sourceNumber":"181435","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dadas as afirmativas relacionadas às anomalias dos arcos branquiais: I. São tumores\ncongênitos laterais, resultantes de defeitos de desenvolvimento embrionário que afetam os arcos\nbranquiais; II. Sua apresentação clínica ocorre sob forma de fístulas, que se manifestam na idade\nadulta; III. As anomalias do primeiro arco branquial são posteriores ao trajeto do nervo facial e\ntêm\nrelação com o conduto auditivo externo; IV. As anomalias do terceiro arco branquial são raras e\ngeralmente representadas por fístulas. Verifica-se que estão corretas apenas:","options":{"A":"I e II.","B":"I e IV.","C":"II e IV.","D":"III e IV.","E":"I, II e III."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182762","number":"182762","sourceNumber":"182762","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a Obstrução Intestinal Congênita que está associada à epidermólise bolhosa:","options":{"A":"Atresia de piloro.","B":"Atresia de duodeno.","C":"Atresia jejuno ileal.","D":"Atresia de cólon."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183098","number":"183098","sourceNumber":"183098","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"São causas de constipação intestinal na criança, EXCETO:","options":{"A":"Desidratação.","B":"Uso de drogas antidepressivas.","C":"Abscesso / Fissura anal.","D":"Doença Celíaca."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182768","number":"182768","sourceNumber":"182768","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A incidência de ânus imperfurado é de 1: 5000 nascidos vivos, com leve predominância\ndo sexo masculino (58%) sobre o feminino\n(42%). As manifestações clínicas mais comuns são a\nnão evacuação de mecônio e a ausência de abertura do ânus no exame clínico. Embora a maioria\ndos neonatos não apresente outra má formação associada, alguns apresentam\nconcomitantemente, EXCETO:","options":{"A":"Defeitos sacrais e vertebrais.","B":"Anormalidades dos membros.","C":"Agenesia renal.","D":"Defeitos cardíacos."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-180125","number":"180125","sourceNumber":"180125","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Menino, 2 anos, é trazido ao pronto-socorro com história de palidez, choro e vômitos.\nExame físico: regular estado geral, FC: 144\nbpm, FR: 30 irpm, PA: 78 x 38 mmHg, descorado ++/4,\ndor leve à palpação abdominal. Toque retal: presença de coágulos e sangue, tipo geleia de\n\n?morango?. Qual a hipótese diagnóstica?","options":{"A":"Doença de Crohn","B":"Colite pseudomembranosa","C":"Divertículo de Meckel","D":"Invaginação intestinal","E":"Polipo intestinal"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183584","number":"183584","sourceNumber":"183584","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O nervo frênico está situado em qual localização na região cervical?","options":{"A":"Sobre o músculo escaleno anterior.","B":"Sobre o músculo escaleno médio.","C":"Sobre o músculo escaleno posterior.","D":"Entre o músculo escaleno anterior e o músculo escaleno médio."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182748","number":"182748","sourceNumber":"182748","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre o Tumor de Wilms, é INCORRETO que,","options":{"A":"é uma neoplasia renal embrionária consistindo em blastema metanéfrico em 85% dos casos.","B":"75% dos casos são diagnosticados em crianças com menos de 5 anos de idade.","C":"13% pode apresentar-se com tumor bilateral.","D":"o pricipal tratamento para o Tumor de Wilms é a quimio e radioterapia."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-183573","number":"183573","sourceNumber":"183573","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual é o nervo mais comumente lesado durante uma ressecção de bócio mergulhante?","options":{"A":"Hipoglosso.","B":"Frênico.","C":"Laríngeo recorrente.","D":"Vago."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182820","number":"182820","sourceNumber":"182820","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A doença de Hirschsprung ocorre em um a cada 5.000 nascidos vivos. É INCORRETO\nafirmar que","options":{"A":"está associada a espasmo muscular do cólon distal e esfincter anal interno, resultando em\nobstrução funcional.","B":"a aglangliose se incia na transição anoretal.","C":"o retossigmoide é afetado em aproximadamente 80% dos casos.","D":"o enema contrastado é o padrão ouro para o diagnóstico."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-181392","number":"181392","sourceNumber":"181392","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mãe chega à Emergência com seu filho de 10 meses com crises de choro alternadas\ncom letargia. Suas fezes se encontram com muco\ne sangue. Pensando em invaginação intestinal, o\nResidente de plantão pediria como exame complementar de imagem","options":{"A":"uma ultrassonografia abdominal.","B":"um RX simples de abdômen.","C":"uma tomografia de abdômen.","D":"uma retossigmoidoscopia.","E":"um enema opaco."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-182797","number":"182797","sourceNumber":"182797","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A Doença Arterial Obstrutiva Periférica (DAOP) caracteriza-se pela obstrução\naterosclerótica progressiva das artérias dos membros\ninferiores, afetando gradualmente de forma\nadversa a qualidade de vida desses pacientes. Sendo assim, podemos considerar como\nINADEQUADO o item:","options":{"A":"Cerca de metade dos pacientes diabéticos com lesões nos pés tem DAOP.","B":"Entretanto, a prevalência real dessa associação é muito fácil de ser avaliada.","C":"A dificuldade na Doença Arterial Obstrutiva Periférica ser avaliada se deve à ausência de\nsintomas, mascarados pela neuropatia periférica em boa parte dos pacientes, e aos diferentes\nindicadores utilizados nas pesquisas epidemiológicas.","D":"O Diabetes Mellitus (DM) dobra a possibilidade de desenvolver DAOP, e 1% de aumento na\nHbA1c está associado a um aumento de 26% no\nrisco de desenvolver DAOP."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161123","number":"161123","sourceNumber":"161123","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Com relação ao tratamento da doença hemorroidária, aponte a alternativa CORRETA:","options":{"A":"Hemorroida trombosada externa pode ser ressecada no consultório com anestesia local.","B":"A hemorroidectomia fechada proporciona uma ressecção apenas de hemorroidas externas.","C":"As complicações pós-operatórias incluem: impactação fecal, retenção urinária, infecção,\nsangramento e retocele.","D":"Hemorroidas de terceiro grau são aquelas com prolapso hemorroidário, com sangramento ou\nnão, que não tem redução digital."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-158783","number":"158783","sourceNumber":"158783","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"São ramos da artéria carótida externa:","options":{"A":"Artéria temporal inferior, artéria facial, artéria nasal.","B":"Artéria tireoidea superior, artéria facial, artéria lingual.","C":"Artéria lingual, artéria tireoidea inferior, artéria occipital.","D":"Artéria faríngea descendente, artéria temporal inferior, artéria facial.","E":"Artéria vertebral, artéria tireoidea inferior, artéria temporal superior."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161178","number":"161178","sourceNumber":"161178","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Para o atendimento da criança traumatizada é fundamental o conhecimento das\nparticularidades da anatomia da criança. Sobre isso, é INCORRETO afirmar que:","options":{"A":"A laringe posterior tem propensão a se anteriorizar em decorrência da flexão passiva da cabeça.","B":"Os tecidos moles da orofaringe de um lactente são proporcionalmente maiores quando\ncomprado aos tecidos da cavidade oral, o que\ndificulta a visualização da laringe.","C":"A traqueia do lactente mede em torno de 5 cm de comprimento.","D":"A laringe da criança é semelhante à do adulto."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-158749","number":"158749","sourceNumber":"158749","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual o sinal mais precoce de uma complicação de cirurgia bariátrica?","options":{"A":"Taquidispneia.","B":"Febre intermitente.","C":"Dor abdominal intensa.","D":"Sinal de Joubert positivo.","E":"Sinal de Blumberg positivo."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161183","number":"161183","sourceNumber":"161183","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os defeitos da parede abdominal anterior são uma condição neonatal relativamente\nfrequente em cirurgia pediátrica. Sobre este\nassunto, indique a alternativa CORRETA.","options":{"A":"Gastrosquise é geralmente à esquerda do cordão umbilical, o defeito fascial tem mais de 4 cm\nde diâmetro.","B":"Onfalocele é reconhecida como um defeito central da parede abdominal. Apresenta baixa\nincidência de anomalias associadas.","C":"O tratamento neonatal da onfalocele de pequeno e médio porte é preferencialmente a colocação\nde silo para redução sequencial.","D":"Um dos grandes desafios do tratamento da gastrosquise é lidar com intestino disfuncional e/ou\nsíndrome do intestino curto."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161187","number":"161187","sourceNumber":"161187","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O Tumor de Wilms é uma neoplasia renal embrionária consistindo em blastema\nmetanefrético na maioria dos casos. Sobre este assunto, marque a opção INCORRETA.","options":{"A":"Os principais tratamentos para o Tumor de Wilms são radioterapia e quimioterapia.","B":"Pico de incidência ocorre aos 2-3 anos de idade.","C":"13% pode apresentar tumor bilateral, que é sincrônico em 60% dos casos.","D":"É classificada como favorável e desfavorável. Sendo a favorável mais comum, caracterizada\npela presença de três elementos: células blastemais,\nestromais e epiteliais."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161388","number":"161388","sourceNumber":"161388","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os tumores neuroblásticos, incluindo o neuroblastoma, o ganglioneuroblastoma e o\nganglioneuroma são tumores originados das células da placa neural primitiva, que produzirá as\ncélulas da medula adrenal e dos gânglios simpáticos por todo corpo. Sobre o Neuroblastoma,\naponte a alternativa INCORRETA.","options":{"A":"Quanto menor a criança, maior a chance de cura.","B":"Doença metastática que está presente em aproximadamente 70% dos casos ao diagnóstico.","C":"O achado clínico mais comum é a presença de massa dura, indolor e com superfície irregular.","D":"Pode estar associado a algumas anomalias, como aniridia, malformações genitourinárias,\nneurofibromatose, hemi-hipertrofia, síndrome de Beckwith-Wiedmann e Denys-Drash."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161137","number":"161137","sourceNumber":"161137","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Observe a imagem a seguir. (Conforme imagem do caderno de questões). Assinale a\nalternativa que corresponde, RESPECTIVAMENTE, aos locais adequados para obtenção de via\naérea através de cricotiroidostomia e traqueostomia, e a estrutura apontada pelo número 1.","options":{"A":"5 / 8 / Cartilagem cricoide.","B":"8 / 10 / Osso hióideo.","C":"10 / 8 / Osso hióideo.","D":"5 / 8 / Osso hióideo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/161137.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161189","number":"161189","sourceNumber":"161189","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a invaginação intestinal, assinale a alternativa INCORRETA.","options":{"A":"O exame de escolha para diagnóstico é a ecografia abdominal.","B":"A grande maioria tem como etiologia uma alteração anatômica, como divertículo de Meckel,\npólipos ou tumores intestinais.","C":"O melhor tratamento e o mais frequentemente utilizado, quando não há peritonite, perfuração,\nsepticemia ou choque, é a redução pneumática/hidrostática.","D":"A imagem tipo em alvo é comumente observada na ecografia de crianças com invaginação\nintestinal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-161292","number":"161292","sourceNumber":"161292","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O aspecto do vômito pode sugerir o tipo de comprometimento abdominal. Das\nalternativas apresentadas a seguir, indique aquela em que o aspecto do vômito esteja\nCORRETAMENTE associado à sua respectiva hipótese diagnóstica.","options":{"A":"Vômito borráceo ? obstrução.","B":"Vômito bilioso ? intussuscepção.","C":"Vômito fecaloide ? gastrite.","D":"Vômitos em jato - megacólon"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-134811","number":"134811","sourceNumber":"134811","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Idosa de 62 anos de idade, com hipertensão e diabetes mal controladas, dá entrada ao\nHospital com queixa de intensa dor torácica e mal-estar. Seu eletrocardiograma mostra-se normal,\nbem como sua dosagem inicial de marcadores de necrose miocárdica. A seguir, foi solicitado\nRadiografia de Tórax que demonstrou normalidade, e Tomografia Torácica que demonstrou\nhematoma na parede da aorta torácica. O diagnóstico firmado foi o de dissecção de aorta. Diante\ndo caso clínico, assinale a alternativa que apresenta um possível risco","options":{"A":"De tamponamento cardíaco.","B":"De hemotórax.","C":"De choque hipovolêmico.","D":"Contido em todas as alternativas anteriores."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-134049","number":"134049","sourceNumber":"134049","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança de 4 anos, previamente hígida, apresenta sangramento retal importante, com\nqueda significativa de hematócrito/hemoglobina.\nEndoscopia alta e colonoscopia normais. Para\nesse caso, o diagnóstico MAIS provável é","options":{"A":"Linfoma do intestino delgado.","B":"Hiperplasia nodular linfoide.","C":"Divertículo de Meckel.","D":"úlcera duodenal."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-134070","number":"134070","sourceNumber":"134070","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente acamado apresentando úlcera de pressão em região sacral. A ferida se\napresenta com necrose de toda espessura da pele. Segundo classificação de SHEA, responda:","options":{"A":"Tipo 1.","B":"Tipo 2.","C":"Tipo 3.","D":"Tipo 4."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-131361","number":"131361","sourceNumber":"131361","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"À respeito da fotocoagulação, (infrared coagulation), no tratamento da doença\nhemorroidária , podemos afirmar que:","options":{"A":"Acompanha-se de alto índice de estenose e sepse.","B":"Sua melhor indicação são os mamilos que requerem redução manual do prolapso.","C":"São idealmente utilizadas para o componente hemorroidário externo.","D":"A obrigatoriedade de anestesia mais importante, com bloqueio ou sedação, faz com que perca a\nindicação frente a outros métodos de tratamento.","E":"Sua melhor indicação são as hemorroidas internas sintomáticas, que sejam muito pequenas\npara\n\numa ligadura elástica."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-131382","number":"131382","sourceNumber":"131382","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Trauma vascular de artéria poplítea com lesão total com evolução para edema de\nperna, pé equino e perda da sensibilidade, qual o seu diagnóstico provável?","options":{"A":"Síndrome de compartimento.","B":"Fratura.","C":"Edema traumático.","D":"Rotura muscular.","E":"Trombose venosa."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-109796","number":"109796","sourceNumber":"109796","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A regra de Goodsall está relacionada:","options":{"A":"à fístula perianal.","B":"às fístulas pancreáticas.","C":"às fístulas esofagianas.","D":"à pancreatite aguda."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-109799","number":"109799","sourceNumber":"109799","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente pós-operatório de hemorroidectomia pode ter complicações precoces,\nEXCETO:","options":{"A":"Dor.","B":"Retenção urinária.","C":"Sangramento.","D":"Estenose."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-110059","number":"110059","sourceNumber":"110059","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual artéria deve ser preservada na reconstrução mamária, utilizando retalho do\nmúsculo reto abdominal?","options":{"A":"Torácica lateral.","B":"Toracodorsal.","C":"Epigástrica superior profunda.","D":"Circunflexa superior profunda."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-86830","number":"86830","sourceNumber":"86830","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O transplante de órgãos entre indivíduos da mesma espécie é chamado de:","options":{"A":"Autotransplante;","B":"Isotransplante;","C":"Alotransplante;","D":"Xenotransplante;","E":"Nenhuma das anteriores."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-86685","number":"86685","sourceNumber":"86685","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"São ramos diretos da artéria aorta:","options":{"A":"Hepática comum, mesentérica superior e mesentérica inferior.","B":"Esplênica, tronco celíaco e renal direita.","C":"Mesentérica superior, tronco celíaco e renal esquerda.","D":"Renal direita, renal esquerda e hepática própria.","E":"Mesentérica inferior, torácica interna e esplênica."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-86831","number":"86831","sourceNumber":"86831","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a fimose em crianças, é correto afirmar que:","options":{"A":"A maioria das circuncisões é realizada por indicação médica;","B":"A retração prepucial forçada é uma técnica a ser considerada durante o tratamento;","C":"Até o 5º ano de vida o prepúcio apresenta-se retrátil em 90% dos meninos;","D":"A circuncisão está indicada com a finalidade de reduzir a ocorrência de infecções urinárias;","E":"A fimose patológica pode ser tratada com corticoide e hialuronidase tópicas."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-13133","number":"13133","sourceNumber":"13133","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A penioscopia tem maior valor quando a parceira é portadora de:","options":{"A":"NIC 1 ou condilomas.","B":"NIC 2.","C":"NIC 3.","D":"Adenocarcinoma.","E":"NDA."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-362492","number":"362492","sourceNumber":"362492","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, vem ao pronto socorro queixando dor anal de\ninício súbito há 24 horas, após episódio de\ndefecação dificultada por fezes endurecidas. A dor era\ninicialmente moderada e evoluiu com piora progressiva e aparecimento de nodulação local. A\npaciente foi orientada a assumir posição de Sims para o exame físico e durante a inspeção anal,\nobservou-se nódulo arroxeado, em borda anal, não endurecido, bastante doloroso à palpação.\n\nDevido à dor, o exame físico foi interrompido e o toque retal não foi realizado. Sobre o caso\ndescrito, assinale a alternativa CORRETA:","options":{"A":"Já que a paciente procurou avaliação médica precoce, é seguro afirmar que ela se beneficiará\ncom tratamento cirúrgico de urgência, sob anestesia\nlocal.","B":"Já que o toque retal não pôde ser realizado, há indicação precisa de avaliação tomográfica para\na investigação de processo neoplásico retal.","C":"O uso tópico de pomadas de nifedipina são preferenciais neste estágio por diminuir a\nnecessidade de tratamento cirúrgico eletivo posterior.","D":"A decisão terapêutica, se clínica ou cirúrgica, deverá ser baseada no resultado do leucograma e\nnos níveis de proteína C reativa."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-362516","number":"362516","sourceNumber":"362516","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 58 anos, diabética e obesa, apresenta quadro de dor\nintensa em membro inferior esquerdo. Refere\nque há 2 dias iniciou quadro de edema e eritema em\nperna esquerda, acompanhado de bolhas e áreas de parestesia. Procurou atendimento médico na\nUnidade Básica de Saúde, sendo prescrita cefalexina e orientações para tratamento domiciliar.\n\nEvoluiu hoje com aumento importante da intensidade da dor e piora do aspecto do membro. Nega\nfebre. Ao exame físico, a paciente\napresenta-se em REG, pálida, com fascies de dor, taquicárdica,\nlevemente dispneica, afebril e normotensa. Apresenta perna e pé esquerdo com edema com cacifo,\neritema, áreas enegrecidas na pele, bolhas hemorrágicas, algumas estouradas drenando conteúdo\nturvo e fétido. Leucograma: 15.000, Hemoglobina: 9g/dl, Proteína C reativa: 120mg/dl, glicemia\ncapilar: 350mg/dl, creatinina: 2,5mg/dl. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Os dados fornecidos são insuficientes para indicar tratamento cirúrgico, estando indicada a\ninvestigação de coleções profundas no membro através de ultrassonografia.","B":"O desbridamento precoce com ressecção agressiva e extensa de tecido infectado e\ndesvitalizado tem impacto direto no sucesso do tratamento e na melhora da sobrevida.","C":"A associação de Penicilina Cristalina com aminoglicosídeos compõe a escolha antibiótica\nempírica de escolha para o caso.","D":"Quando realizada nas primeiras 72 horas após a admissão, geralmente um desbridamento é\nsuficiente para o controle do foco infeccioso."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327246","number":"327246","sourceNumber":"327246","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 29 anos, vem ao consultório de Cirurgia queixando história\nde episódios de dor perianal que melhora com a\ndrenagem espontânea de secreção purulenta\nsempre pelo mesmo local, há cerca de um ano de evolução. Refere que o quadro iniciou alguns\nmeses após internação hospitalar para drenagem cirúrgica de abscesso perianal. Ao exame físico,\nobserva-se lesão semelhante a pequeno granuloma, localizado às 11 horas, há cerca de 2cm do\nrebordo anal, com saída de pequena quantidade de secreção à sua expressão. Palpa-se cordão\nfibroso subcutâneo que se origina na lesão descrita e se direciona ao rebordo anal. De acordo com\nos dados descritos acima, assinale a alternativa CORRETA:","options":{"A":"Podemos afirmar que, de acordo com a regra de Goodsall-Salmon que a trajetória do cordão\nfibroso palpável é curvilínea, desembocando às 6 horas na linha pectínea.","B":"Doença de Crohn e Tuberculose intestinal fazem parte do diagnóstico diferencial da patologia\ndescrita.","C":"Os dados acima não nos permitem confirmar a relação casual do abscesso perianal prévio com\no quadro atual.","D":"Já que a patologia descrita acima não envolve o esfíncter anal, tanto a abertura do canal fibroso\nquanto sua ressecção não evoluem com incontinência fecal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327254","number":"327254","sourceNumber":"327254","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 10 anos, é trazida pela mãe para consulta com o Cirurgião a\nrespeito de massa cervical de cerca de 3 a 4 cm, localizada na linha média a nível do osso hióide,\nmóvel à deglutição. Mãe refere episódios de processo inflamatório local com drenagem de secreção\npurulenta e posterior recidiva da nodulação. Não havia linfonodomegalia à palpação cervical. Traz\nconsigo USG que define a massa como estrutura cística. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"A exame da cavidade oral provavelmente evidenciará contiguidade do cisto com a base da\nlíngua e seu conteúdo será de saliva.","B":"Trata-se de provável anomalia congênita do seio cervical a nível do segundo arco branquial,\nestando indicada sua ressecção cirúrgica.","C":"O tratamento cirúrgico desta paciente provavelmente envolverá ressecção parcial do osso\nhióide.","D":"O próximo passo na investigação desta paciente é a Ressonância Magnética que provavelmente\nevidenciará extensão da massa até a laringe."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327255","number":"327255","sourceNumber":"327255","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 4 anos, é trazido pela mãe ao pronto atendimento após\nesta observar \"sangue na urina\". O paciente não\napresenta história de dor, febre ou trauma\nabdominal recente. Ao exame físico, o paciente se encontra em BEG, normocorado, eupneico e\nafebril, mas chama a atenção uma P.A.: 140x100mmHg. Seu exame cardiorrespiratório é normal. À\npalpação abdominal, observa-se massa palpável, de consistência firme, não móvel, de cerca de\n15cm, em flanco esquerdo. Hemograma e ionograma sem alteração. O EAS evidencia de 15\nhemácias por campo de microscopia. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Já que não há sinais de choque, comprometimento agudo e significativo do estado geral e\nausência de história de trauma, a investigação deste paciente pode ser ambulatorial.","B":"Imagem de massa sólida ou mista, em loja renal, com distorção pielocalicial à TC de abdome é\ncompatível com o caso clínico descrito.","C":"Após estadiamento tumoral, na ausência de metástases a distância e envolvimento vascular, a\nressecção da massa tumoral seguida de quimioterapia adjuvante pode corresponder proposta\nterapêutica adequada.","D":"Caso sejam observadas elevadas titulações de alfa-feto proteína, haverá indicação de\nquimioterapia neoadjuvante."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327294","number":"327294","sourceNumber":"327294","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente 11 meses apresenta 3 dias significativo sangramento retal (aspecto geleia de\ngroselha): RX: simples de abdômen normal. Para confirmação diagnostica é necessário a\nrealização de qual exame complementar?","options":{"A":"Cintilografia com tecnécio - 99m","B":"Clister opaco","C":"Trânsito de delgado","D":"Endoscopia digestiva alta"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327298","number":"327298","sourceNumber":"327298","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Pré-escolar 2 anos, sexo feminino com história de febre, irritabilidade, atraso no\ncrescimento, dor ósseo, proptose orbital, equimose periorbitarias. Exame físico: Hipocorado,\nhematócrito: 29%, Velocidade Hemossedimentação: 85mm, Rx de tórax, massa volumosa no\nmediastino posterior de contornos irregulares com calcificações. Esse quadro é sugestivo de:","options":{"A":"Tuberculose ganglionar","B":"Pneumonia","C":"Neuroblastoma","D":"Cisto broncogênico"},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-327299","number":"327299","sourceNumber":"327299","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Escolar 10 anos sexo masculino, procura setor de emergência de sua cidade por\napresentar há 8 horas dor aguda vomito e\nedema escrotal. Ao exame: Bom estado geral, afebril,\nhidratado, fáceis de dor, escroto com edema e o testículo extremamente sensível para examinar.\nAssinale a alternativa CORRETA.","options":{"A":"Prescrever antibiótico oral e retornar com 72 horas.","B":"Aplicar calor local, e elevar o testículo e observar por 24 horas.","C":"Prescrever anti-inflamatório não hormonal, calor local e retorno com 72 horas.","D":"Internar para exploração cirúrgica imediata."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-298215","number":"298215","sourceNumber":"298215","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, obesa, com história de constipação crônica (refere\neliminação de fezes bastante ressecadas, em cíbalos, a cada 7 dias) queixa quadro de\naparecimento de nodulação anal bastante dolorosa há 3 dias, após defecação. Ao exame físico,\nobserva-se nodulação violácea bastante edemaciada e dolorosa à palpação localizada em borda\nanal às 9 horas. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Apesar do tratamento com anti-inflamatórios, mucilagens orais e banhos de assento\napresentarem bons resultados, este pode ser\ndemorado, prolongando o incômodo do paciente e\nsua impossibilidade de exercer as atividades diárias, frequentemente sendo indicado o tratamento\ncirúrgico de urgência.","B":"A drenagem cirúrgica e antibioticoterapia é o tratamento de escolha para a patologia descrita,\nporém a evolução para fístula perianal é\nbastante incidente nesses casos.","C":"A esfincterotomia parcial é passo essencial no tratamento cirúrgico desta patologia.","D":"Devemos fazer diagnóstico diferencial com Doença de Crohn e Infecções Sexualmente\nTransmissíveis (ISTs) através de biópsia da lesão antes da instituição do tratamento desta\npaciente."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-298218","number":"298218","sourceNumber":"298218","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 12 anos de idade, dá entrada no pronto socorro queixando\ndor escrotal aguda, intensa, de início súbito,\nhá cerca de 4 horas. Nega trauma, sintomas urinários\ne febre. Ao exame físico, observa-se testículo esquerdo elevado, bastante doloroso à palpação e a\ndor não melhora após elevação manual do mesmo. Sobre o caso acima, assinale a alternativa\nINCORRETA:","options":{"A":"A demora na instituição do tratamento definitivo adequado geralmente implica na perda do\ntestículo acometido.","B":"O próximo passo na investigação deste paciente é a ultrassonografia com doppler.","C":"O sinal de Prehn identificado no exame físico fecha o diagnóstico de orquiepididimite, indicando\ntratamento clínico com antibioticoterapia e aintiinflamatórios não hormonais.","D":"O testículo contralateral deve ser explorado cirurgicamente para evitar acometimento futuro do\nmesmo."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-298225","number":"298225","sourceNumber":"298225","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 16 anos, procura o ambulatório de Cirurgia queixando\nmassa cervical que observou há cerca de 1 ano.\nNega dor local ou sinais de inflamação. Ao exame\nfísico, observamos massa de cerca de 7cm de diâmetro, de consistência aparentemente cística,\nmóvel, de localização latera à direita, na borda anterior do músculo esternocleidomastoideo, indolor\nà palpação. Não foram observados orifícios fistulosos ou sinais flogísticos locais. Sobre o caso\nacima, assinale a alternativa CORRETA:","options":{"A":"A hipótese mais provável seria de cisto tireoglosso devido a consistência cística e sua\nmobilidade à palpação.","B":"Caso a tomografia confirme a natureza cística da lesão, podemos inferir que a doença é\nprovavelmente congênita por anomalia no 2o. arco branquial.","C":"A ultrassonografia deve confirmar o diagnóstico de tuberculose ganglionar, indicando ressecção\ncirúrgica da lesão e antibioticoterapia.","D":"A ressonância magnética é o exame de imagem de escolha para o caso por fechar o diagnóstico\nde laringocele."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-298261","number":"298261","sourceNumber":"298261","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um pai traz sua filha de 3 anos à consulta por adinamia, perda de apetite e aumento\nprogressivo de abdômen há algumas semanas.\nApresenta vômitos há 1 dia. Exame físico com\npalidez, proptose, descoloração periorbital e massa abdominal grande e irregular ao longo do flanco\nesquerdo, cruzando a linha média. Sinais vitais e restante do exame físico normal. Qual o\ndiagnóstico mais provável?","options":{"A":"Osteossarcoma","B":"Neuroblastoma","C":"Rabdomiossarcoma","D":"Linfoma"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-286730","number":"286730","sourceNumber":"286730","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 5 anos de idade, apresenta quadro de dor em abdome\nsuperior de leve intensidade há 6 meses,\nquando a mãe palpou um ?caroço na barriga? em\nHipocôndrio Direito(HD) . Nega vômitos, febre e demais queixas. Ao exame físico o paciente se\nencontrava em Bom Estado Geral, discretamente emagrecido, hipocorado +/4, anictérico, afebril,\nhemodinamicamente estável. Seu abdome é atípico, plano, flácido, discretamente doloroso em HD,\ncom hepatomegalia palpável a 5cm do rebordo costal. Baço não palpável. À USG, observamos\nfígado com ecogenicidade usual apresentando volumosa massa sólida em lobo direito. Sobre a\ncondução do caso, assinale a alternativa INCORRETA:","options":{"A":"O próximo passo na investigação desse paciente é a tomografia computadorizada de abdome e\ntórax.","B":"A ressecção da neoplasia se torna mais factível por tratar-se de fígado não-cirrótico.","C":"Frequentemente indica-se quimioterapia neoadjuvante para o caso acima.","D":"Esperamos observar baixos níveis de alfa-fetoproteína no perfil laboratorial deste paciente."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-286735","number":"286735","sourceNumber":"286735","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 2 anos, é trazido pela mãe para avaliação de aumento do\nvolume da bolsa escrotal. Ela observou o problema há alguns meses e refere piora gradativa. Não\nsabe referir adequadamente sobre história de trauma local. Nega febre. Ao exame físico,\nobservamos aumento do volume da hemibolsa escrotal direita, irredutível, indolor à palpação. Não\nhá sinais flogísticos. Testículos tópicos, indolores à palpação. Teste da transiluminação positivo.\n\nAssinale a alternativa que contém diagnóstico adequado, sua justificativa e terapia adequada:","options":{"A":"Hidrocele, devido ao aumento do volume escrotal transiluminescente e indolor; tratamento\ncirúrgico.","B":"Hérnia inguino-escrotal encarcerada, devido a evolução crônica e irredutibilidade, tratamento:\nherniorrafia inguinal eletiva.","C":"Varicocele, por ser o diagnóstico mais comum de aumento indolor do volume escrotal nesta\nidade; tratamento expectante.","D":"Orquite viral, por cursar com aumento da bolsa escrotal sem sinais flogísticos e ser bastante\nincidente nesta faixa etária; tratamento: antibioticoterapia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-286737","number":"286737","sourceNumber":"286737","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, multípara, obesa, vem ao consultório queixando\ndor nas pernas principalmente após ficar de\npé por longos períodos de tempo. Refere que o quadro\niniciou durante sua primeira gravidez e piorou com o passar do tempo. Ao exame físico,\nobservamos veias superficiais de calibre aumentado, túrgidas e tortuosas, com pigmentação\nescurecida em tornozelos e cicatriz radial em terço distal da perna direita (paciente refere\ntratar-se\nde ?ferimento que demorou meses para cicatrizar?). Sobre a conduta deste paciente, assinale a\nalternativa CORRETA:","options":{"A":"A tomografia contrastada de membros inferiores tem maior sensibilidade e especificidade para\navaliação do caso e suas complicações que o Duplex Scan.","B":"Já que não há evidência de trombose venosa profunda nem úlcera venosa ativa, o tratamento de\nescolha para o caso é o uso contínuo de meias de média compressão.","C":"A perda de peso e atividade física leve a moderada são essenciais na proposta terapêutica\ndesta paciente.","D":"Os dados acima nos permitem afirmar que o tratamento endovascular (ablação por\nradiofrequência e laser) e a ressecção cirúrgica da veia safena estão contraindicados."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-256584","number":"256584","sourceNumber":"256584","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"É característica comum que chama a atenção para a presença de abscesso anal\nsubmucoso:","options":{"A":"Dor, aumento de volume, calor, rubor na região do espaço isquioanal","B":"Febre e dor anal externa","C":"Diarreia","D":"Dor intra-anal com febre."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-252228","number":"252228","sourceNumber":"252228","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Das indicações de realização de arteriografia de extremidades podemos citar,\nEXCETO:","options":{"A":"Controle após procedimentos cirúrgicos.","B":"Investigação de estenoses arteriais.","C":"Diagnóstico diferencial de vasculites e malformações vasculares.","D":"Ausência de pulsos palpáveis em paciente hígido."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-252229","number":"252229","sourceNumber":"252229","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em caso de trauma vasculares, são indicativos de intervenção cirúrgica precoce os\nseguintes achados, EXCETO:","options":{"A":"Sangramento pulsátil","B":"Hematoma expansivo","C":"Pulsos diminuídos","D":"Parestesia"},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-252236","number":"252236","sourceNumber":"252236","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os tumores de glândulas salivares são incomuns e representam 2% de todas as\nneoplasias de cabeça e pescoço. Qual o tipo histológico e qual a glândula mais comprometida?","options":{"A":"Adenoma pleomórfico e parótida.","B":"Adenoma pleomórfico e sublingual.","C":"CEC e parótida.","D":"CEC e sublingual."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-252283","number":"252283","sourceNumber":"252283","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente 11 meses é trazida ao posto de saúde porque sua mãe observou nos últimos\ndias, a presença de sangue em pequena quantidade na fralda, relata que as fezes eram\nendurecidas, não relatou outras alterações. O provável diagnostico é:","options":{"A":"Diverticulite de Meckel","B":"Retocolite ulcerativa","C":"Doença de Crohn","D":"Fissura anal"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-208428","number":"208428","sourceNumber":"208428","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 4 anos sua mãe refere que sua urina estava avermelhada\ne suspeita de sangue na urina, levando-a à\nconsulta médica. Nega história recente de trauma\nabdominal. O paciente está em bom estado geral, eupneico, afebril, normocorado e normotenso. Ao\nexame físico, observou-se massa sólida, imóvel e indolor, de cerca de 15 cm, localizada em flanco\ndireito. Nega alterações do hábito intestinal, demais sintomas urinários e icterícia. Seu hemograma\ne ionograma são normais. O EAS revelou 50 hemácias por campo. Assinale a alternativa\nCORRETA:","options":{"A":"A presença de calcificações à radiografia simples de abdome já indica tratamento cirúrgico sem\na necessidade de outros exames de imagem.","B":"Apesar da ultrassonografia ser o primeiro exame de imagem indicado, a tomografia de abdome e\ntórax poderá fechar o diagnóstico e estadiar o caso.","C":"A ureterolitotomia endoscópica deve ser realizada em caráter urgente para esse paciente,\nindicada pela iminente perda da função do rim direito.","D":"A nefrectomia é o tratamento curativo (caso aplicável) de escolha para este paciente já que nem\na quimioterapia nem a radioterapia são\ntratamentos coadjuvantes com resposta satisfatória."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-176108","number":"176108","sourceNumber":"176108","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 15 anos, é trazido pelo pai com queixa de dor em bolsa\nescrotal aguda, intensa, com início há cerca\nde 4 horas. Refere vida sexual ativa sem uso de\npreservativos, há 2 anos. Nega febre, disúria e trauma local. Ao exame físico, observamos edema e\nrubor de hemibolsa escrotal esquerda, com testículo esquerdo elevado e ligeiramente\nhorizontalizado. Sinal de Prehn e reflexo cremastérico ausentes. Assinale a alternativa CORRETA:","options":{"A":"Caso a avaliação ultrassonográfica não seja possível em curto espaço de tempo, a exploração\ncirúrgica da bolsa escrotal está indicada.","B":"O edema e hiperemia sugerem escroto agudo de etiologia inflamatória, de provável origem\nsexualmente transmissível, estando indicado antibioticoterapia e alta para o domicílio.","C":"O exame físico fecha o diagnóstico de hérnia inguinoescrotal complicada, estando indicada a\ninguinotomia de urgência.","D":"O EAS provavelmente fechará o diagnóstico, indicando orquidopexia eletiva."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-176111","number":"176111","sourceNumber":"176111","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança do sexo masculino, 1 ano de idade, é trazida ao atendimento médico com\nhistória de constipação crônica desde o\nnascimento, inicialmente leve, com piora progressiva.\nRefere que mesmo com suplementação de fibras e hidratação adequada, passa vários dias sem\ndefecar, com episódios de ida ao pronto-socorro para alívio das fezes com toque retal e enema\nglicerinado. Apresenta-se chorosa, com abdome distendido, doloroso à palpação, sem irritação\nperitoneal. Ao toque retal, palpou-se fecaloma, provocando eliminação explosiva de fezes. Sobre a\ncondução do caso, assinale a alternativa INCORRETA:","options":{"A":"O achado de dilatação proximal de cólon seguido de cone de transição e cólon distal de calibre\nnormal no enema opaco é compatível com o caso.","B":"O tratamento inicial com corticoides é opção para postergar o tratamento cirúrgico.","C":"O diagnóstico definitivo se dá com biópsia seriadas da parede dos segmentos acometidos do\ncólon, que evidenciaria aganglianose.","D":"O tratamento definitivo consiste na ressecção do segmento acometido, geralmente reto e\nsigmoide, com anastomose coloanal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-176093","number":"176093","sourceNumber":"176093","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Nas patologias abaixo, a que apresenta protusão da parede abdominal, paraumbilical,\ncongênita, que resulta na extrusão das\nvísceras, sem revestimento ou bolsa peritoneal é:","options":{"A":"Hérnia Epigástrica.","B":"Hérnia de Spiegel.","C":"Onfalocele.","D":"Gastrosquise."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-151961","number":"151961","sourceNumber":"151961","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente obesa, 28 anos, vem ao ambulatório interessada em \"cirurgia para\nredução de estômago\" para adjuvância no\ntratamento de sua obesidade. Ela é hipertensa e\ndiabética, tem 1,60 m e pesa 95 kg. Qual das orientações a seguir é correta na orientação desta\npaciente nesta primeira consulta?","options":{"A":"\"Não há indicação para tratamento cirúrgico no seu caso porque seu IMC é inferior a 40 kg/m²,\ndesta forma seu tratamento de escolha seria\ndieta e exercício físico\".","B":"\"O by-pass gástrico laparoscópico é uma técnica adequada para o seu caso porque promove\nperda de peso por restrição da quantidade de\nalimento ingerido e por diminuição na absorção deste\nalimento no intestino\".","C":"\"Apesar de seu IMC ser indicativo de tratamento cirúrgico, tal procedimento é contraindicado\ndevido a suas comorbidades, desta forma a\nmodalidade de tratamento mais adequada para o seu\ncaso seria o balão intragástrico\".","D":"\"A técnica laparoscópica não seria uma boa escolha para o seu caso já que a obesidade a torna\ntecnicamente difícil, portanto com maior índice de complicações quando comparada à técnica\naberta convencional\"."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-151922","number":"151922","sourceNumber":"151922","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 6 meses de vida, dá entrada no pronto socorro\napresentando dor e distensão abdominal\nassociada a vômitos há 1 dia. Mãe refere que o paciente\nalimentava-se normalmente (leite integral em pó e \"massa de macaxeira\") até o início dos sintomas.\nNega febre. Ao exame físico, a paciente se encontra chorosa (choro paroxístico), desidratada e\nlevemente dispneica. Seu abdome é distendido, de difícil palpação devido a dor. Palpa-se com\ndificuldade estrutura semelhante a massa alongada em flanco e hipocôndrio direito. Ruídos\nhidroaéreos aumentados em volume e frequência. Após o toque retal, a paciente apresentou\nepisódio de diarreia com sangue, em \"geleia de framboesa\". Assinale a alternativa INCORRETA:","options":{"A":"Neoplasias como o linfoma, linfossarcoma e divertículo de Meckel são as causas mais\nfrequentes do caso clínico descrito acima.","B":"Apesar do diagnóstico clínico neste caso ser bastante sugestivo, o exame de imagem de\nescolha para o diagnóstico é a USG abdominal.","C":"A radiografia simples de abdome sugeriria abdome agudo obstrutivo, porém não é um bom\nmétodo para avaliação do diagnóstico específico.","D":"Caso o paciente não seja tratado adequadamente, o quadro pode evoluir para necrose intestinal\ncom necessidade de enterectomia e anastomose."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-151946","number":"151946","sourceNumber":"151946","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 34 anos, com história de constipação crônica, vem ao\nconsultório de cirurgia queixando-se de dor anal intensa à evacuação há cerca de 2 semanas.\nRefere ainda raios de sangue no papel higiênico. Demonstra receio para evacuar devido ao quadro\nde dor, retendo voluntariamente as fezes. Ao exame físico, observamos úlcera longitudinal em\ncanal anal às 6h, friável, superficial e sangrante. Não foram observadas outras lesões à ectoscopia.\nSobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Por se tratar de patologia crônica, a esfincterotomia deverá fazer parte do seu tratamento\ncirúrgico.","B":"O tratamento deste paciente pode incluir a dieta rica em fibras, aumento da ingesta hídrica\ndiária, melhor higiene local com abolição do papel higiênico e uso de pomadas tópicas à base\nisossorbida.","C":"Caso o tratamento clínico seja ineficaz, o tratamento indicado seria cirúrgico, pela técnica de\nMilligan-Morgan.","D":"Por se tratar de patologia infecciosa, o tratamento deve incluir antibióticos por 2 semanas."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-151965","number":"151965","sourceNumber":"151965","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 64 anos, tabagista inveterado e consumidor social de\nbebida alcoólica (SIC), vem ao consultório\nqueixando quadro de disfonia e rouquidão há cerca de 4\nmeses, sem melhora com tratamentos com antibióticos e anti-inflamatórios. Foi submetido a\nlaringoscopia que evidenciou lesão vegetante acometendo prega vocal direita. Sobre a abordagem\ndeste paciente, assinale a alternativa INCORRETA:","options":{"A":"O exame histopatológico provavelmente evidenciará carcinoma escamocelular.","B":"Caso o estadiamento da paciente evidencie lesão T1 ou T2, o tratamento cirúrgico seria a\nprimeira escolha terapêutica.","C":"A principal etiologia para o caso são alterações genéticas ocasionadas pela associação do\ntabagismo com o alcoolismo.","D":"O próximo passo para a abordagem deste caso, é a avaliação tomográfica (com contraste) ou\ncom ressonância magnética, para determinar a\nextensão da lesão e sua invasão a estruturas\nadjacentes."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-151863","number":"151863","sourceNumber":"151863","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na Estenose Hipertrófica do Piloro (EHP) ocorre:","options":{"A":"Ocorre acidose metabólica.","B":"Tem início na 6ª semana de vida.","C":"Vômito não bilioso é o sintoma inicial.","D":"Icterícia com predomínio de bilirrubina direta."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-129773","number":"129773","sourceNumber":"129773","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em se tratando de doença hemorroidária, as classificadas como internas, projetando-se\npelo canal anal e se exteriorizando ao esforço\nevacuatório e que são reduzidas com ajuda manual,\nsão:","options":{"A":"Prolapso mucoso.","B":"Hemorroidas grau I.","C":"Hemorroidas grau II.","D":"Hemorroidas grau III."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-129757","number":"129757","sourceNumber":"129757","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente de 6 semanas de vida com vômitos em jato após alimentação. No exame\nabdominal, verifica-se uma massa abdominal em\nforma de azeitona. Qual das afirmativas a seguir é\nverdadeira?","options":{"A":"É provável que ele apresente acidose metabólica.","B":"Essa condição é mais comum em bebês do sexo feminino.","C":"Ele deverá reiniciar alimentação após cessação de vômitos.","D":"É provável que ele apresente alcalose metabólica hipoclorêmica."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-103792","number":"103792","sourceNumber":"103792","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na clínica duvidosa em crianças, a escala de ALVARADO é utilizada, na prática para\nqual patologia abaixo:","options":{"A":"colecistite aguda enfisematosa","B":"pancreatite","C":"apendicite aguda","D":"abscesso hepático"},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-107908","number":"107908","sourceNumber":"107908","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 13 anos, dá entrada no pronto atendimento queixando de\ndor escrotal intensa, de início súbito, há cerca de 4 horas. Ao exame físico, apresentava hemibolsa\nescrotal direita aumentada de volume, com sinais flogísticos discretos, com testículo doloroso à\npalpação, elevado (próximo à raiz da bolsa escrotal) e horizontalizado. Sobre o caso, assinale a\nalternativa INCORRETA:","options":{"A":"A pesquisa do reflexo cremastérico pode ser importante para o diagnóstico final do paciente.","B":"O EAS normal não exclui tratamento cirúrgico para o paciente acima.","C":"Os dados acima nos permitem afirmar que não há necessidade de nenhum exame\ncomplementar para indicação de orquiectomia direita urgente.","D":"Podemos afirmar que a ultrassonografia com Doppler tem maior acurácia diagnóstica que a\nressonância magnética no caso acima."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-107909","number":"107909","sourceNumber":"107909","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A oclusão arterial crônica dos membros inferiores é patologia vascular progressiva,\ndebilitante e com incidência crescente com a\nidade. Analise as afirmativas abaixo e assinale a\nalternativa INCORRETA: I. A principal expressão clínica é a claudicação intermitente, podendo ser\nassociada a alteração de fâneros, atrofia muscular e diminuição da amplitude dos pulsos\nperiféricos. II. O tabagismo acentuado é causa frequente, principalmente quando associado a\ndiabetes e dislipidemias, sendo essencial a sua interrupção para o tratamento adequado. III.\nPodemos observar a associação de claudicação inicialmente em musculatura da coxa e glúteos e\nimpotência sexual em homens. IV. A gangrena é complicação grave e pode evoluir para\namputação. V. Endarterectomias, enxertos arteriais e angioplastia transluminal são opções de\ntratamento cirúrgico.","options":{"A":"Há apenas uma afirmativa falsa.","B":"Apenas as afirmativas II e III são corretas.","C":"A afirmativa V é correta.","D":"Apenas as afirmativas I e II são corretas."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-107900","number":"107900","sourceNumber":"107900","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 3 anos de idade, procedente do Interior do Estado, é\ntrazido ao consultório do pediatra devido a\ncoloração azulada de suas extremidades e crises de\ndispneia e piora desta cianose durante esforços físicos, com melhora na posição de \"cócoras\". Ao\nexame físico, o paciente apresentava-se discretamente cianótico, com baixo peso e com sopro\nsistólico paraesternal esquerdo importante à ausculta cardíaca. Trouxe consigo uma radiografia de\ntórax que realizou em uma das crises de cianose que demonstrava imagem de \"tamanco holandês\"\nno mediastino. Assinale a alternativa INCORRETA:","options":{"A":"Comunicação interventricular, estenose pulmonar valvar ou infundibular e dextroposição da aorta\nsão alterações esperadas ao ecocardiograma\ndeste paciente.","B":"Sobrecarga do ventrículo direito é alteração esperada no eletrocardiograma.","C":"O tratamento cirúrgico inicial (paliativo) é bandagem do tronco da artéria pulmonar para melhora\ndo estado geral do paciente para a correção\ndefinitiva das outras mal formações em um segundo\ntempo.","D":"A policitemia e episódios de síncope durante esforço físico podem ocorrer."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-107836","number":"107836","sourceNumber":"107836","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, queixa constipação crônica e hematoquezia\n(sangue vivo no vaso sanitário) há 1 ano, vem\nao ambulatório para investigação. Nega dor à\ndefecação e perda de peso. Não há alterações dignas de nota ao exame físico. A inspeção anal e o\ntoque retal são normais. Assinale a alternativa que contém um diagnóstico compatível com o\nquadro clínico, exame diagnóstico e opção terapêutica adequada:","options":{"A":"Hemorróidas externa trombosada, retossigmoidoscopia e ligadura elástica.","B":"Fissura anal crônica, colonoscopia e diltiazem tópico.","C":"Pólipo retal pediculado, anuscopia e retossigmoidectomia.","D":"Hemorróida interna, retossigmoidoscopia e ligadura elástica sem anestesia."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-87422","number":"87422","sourceNumber":"87422","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mãe leva criança de 8 meses de idade ao pronto atendimento queixando que a mesma\nchora muito e seu abdome começou a \"inchar\"\nhá 24 horas. Nega febre. Refere parada de\neliminação de gases e fezes e vários episódios de vômitos. Durante a entrevista da mãe, a criança\napresentava momentos de choro forte e momentos de acalmia. Ao exame físico, o paciente\napresentava-se bastante desidratado, com distensão abdominal importante, com dor difusa à\npalpação, porém flácido. Descompressão brusca e difícil avaliação, aparentemente indolor. Os\nRHAs estão aumentados em frequência e intensidade. Toque retal com presença de sangue\nmisturado a muco e fezes. Marque a alternativa correta:","options":{"A":"Trata-se de provável abdome agudo inflamatório de tratamento clínico estando indicada a\ninternação hospitalar e antibioticoterapia.","B":"A radiografia simples do abdome é dispensável na avaliação do caso acima.","C":"A ausência de sinais de irritação peritoneal não exclui tratamento cirúrgico para o paciente\nacima.","D":"Evolução com insuficiência renal aguda é incomum no caso acima.","E":"A radiografia de tórax fecha o diagnóstico de perfuração de víscera oca indicando a laparotomia\nde urgência."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-87463","number":"87463","sourceNumber":"87463","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre o hepatoblastoma é correto afimar, EXCETO:","options":{"A":"Neoplasia hepática maligna mais frequente na infância.","B":"Mais comum em pacientes do sexo masculino por volta dos 5 anos de vida.","C":"Sensível à quimioterapia.","D":"Níveis de alfafetoproteína normais.","E":"Hepatectomia como parte do tratamento, com chance de cura."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-87475","number":"87475","sourceNumber":"87475","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A tríade clássica da fissura crônica anal é:","options":{"A":"Fissura propriamente dita + plicoma sentinela + papila hipertrófica.","B":"Fissura propriamente dita + hemorroida interna grau II + diarreia sanguinolenta.","C":"Fissura propriamente dita + dor à defecação + hipotonia esfincteriana.","D":"Úlcera longitudinal + hipertrofia esfincteriana + papila hipertrófica.","E":"Úlcera longitudinal + tenesmo + plicoma sentinela."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-81055","number":"81055","sourceNumber":"81055","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia laparoscópica é considerada a maior revolução em técnica cirúrgica nos\núltimos decênios. Sobre essa nova abordagem cirúrgica dos pacientes, assinale a alternativa\nincorreta:","options":{"A":"Apesar das indicações cada vez mais abrangentes da laparoscopia no tratamento de patologias\nabdominais, esta é limitada nos casos de urgência pela frequente instabilidade hemodinâmica\ndestes pacientes.","B":"A laparoscopia pode ser realizada durante a gravidez com mínima morbidade para o feto e para\na mãe.","C":"Há maior incidência de hérnia incisional quando comparada à laparotomia (cirurgia aberta),\ndevido ao aumento da pressão intra-abdominal pelo pneumoperitôneo.","D":"Dentre suas vantagens, podemos destacar o menor trauma cirúrgico, menor dor no\npós-operatório e menor incidência de aderências intra-abdominais.","E":"O pneumoperitônio realizado na laparoscopia pode reduzir o retorno venoso por aumento da\npressão intra-abdominal, além de arritmias e bradicardia, limitando seu uso em pacientes\ncardiopatas."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-81919","number":"81919","sourceNumber":"81919","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactentes cujas manifestações clínicas e biópsia hepática sugerem obstrução biliar,\ndevem realizar:","options":{"A":"Transplante hepático;","B":"Laparotomia exploradora e colangiografia direta para determinar a presença e o local da\nobstrução;","C":"Reposição de vitaminas e lipossolúveis;","D":"Ultrassonografia abdominal;","E":"Cintilografia hepatobiliar."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-60854","number":"60854","sourceNumber":"60854","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"As fístulas anorretais se classificam em quantos tipos?","options":{"A":"1","B":"2","C":"3","D":"4","E":"5"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-61545","number":"61545","sourceNumber":"61545","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 53 anos, masculino, branco, comerciante, casado, portador de hipertensão\narterial há 16 anos sem tratamento, foi\nadmitido na emergência com dor torácica de início súbito há\ncerca de 3 horas, de forte intensidade irradiada para o abdome e membro inferior esquerdo (MIE),\nacompanhada de sudorese, palpitações, elevação pressórica acentuada. Era etilista. Negava\ntabagismo, diabetes, dislipidemia, e outro evento cardiovascular anterior. Estava em regular estado\ngeral, hidratado, corado, cianótico (2+/4+), eupneico, afebril, consciente e orientado. A ausculta\nrespiratória encontrava-se normal. A ausculta cardíaca era rítmica e regular, sem a presença de\nsopros. A pressão arterial 170 x 110 mmHg e a FC 86 bpm. O MIE encontrava-se cianótico e com\ndiscreta perda da sensibilidade. Pulsos não eram palpáveis em artéria femoral e dorsal do pé\nesquerdo. Exames laboratoriais; CPK 12.859 U/l,TGO 440 U/l, TGP 149 U/I, ácido láctico 4,3\nmmol/l, PCRJ 6,33 mg/dl, glicemia 133 mg/dl e a creatinina 1,4 mg/dl. A angiografia mostra essa\nimagem. (VER IMAGEM). Baseado na história clínica e imagem, qual é a principal hipótese\ndiagnóstica?","options":{"A":"IAM.","B":"Aneurisma de aorta.","C":"Dissecção aórtica DeBakey tipo 2.","D":"Dissecção aórtica tipo B de Stanford.","E":"Ruptura de aneurisma do selo de Valsalva."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/61545.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-61559","number":"61559","sourceNumber":"61559","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Com relação às neoplasias epiteliais benignas das glândulas salivares, é correto afirmar\nque:","options":{"A":"Tumor misto é a neoplasia mais frequente com predomínio no sexo feminino.","B":"Mioepitelioma é mais frequente no sexo feminino, em pacientes com menos de 60 anos.","C":"Oncocitoma se apresenta clinicamente como uma massa dolorosa de crescimento rápido.","D":"Adenoma de células basais acomete predominantemente, a glândula parótida de crianças.","E":"Tumor de Warthin, pode acometer qualquer glândula salivar, sendo mais frequente na\nsubmandibular."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-61508","number":"61508","sourceNumber":"61508","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quanto à cirurgia bariátrica podemos afirmar que:","options":{"A":"Gastrectomia vertical não está indicada na polipose gástrica.","B":"Está contraindicada em pacientes com doenças psiquiátricas graves, sem controle.","C":"As técnicas mistas, como a de Scopinaro, são as mais utilizadas.","D":"Não ocorre controle pós-operatório das comorbidades, com diabetes, hipertensão arterial, sendo\numa cirurgia essencialmente estética.","E":"O acompanhamento multidisciplinar somente é necessário durante o pré-operátorio."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-46641","number":"46641","sourceNumber":"46641","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em um paciente com isquemia crônica de membros inferiores, a realização da\narteriografia tem como principal objetivo:","options":{"A":"Decidir sobre o tipo de tratamento (clínico ou cirurgico).","B":"Programar a cirurgia.","C":"Diagnosticar a sede da oclusão.","D":"Faz parte do protocolo para todos os doentes com isquemia crônica dos membros inferiores.","E":"Complementar a documentação do caso."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-46651","number":"46651","sourceNumber":"46651","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente com quadro de obstrução arterial aguda é visto numa localidade onde não\nexistem condições para cirurgia arterial, devendo ser removido para outra cidade. Qual seria a\nmedicação de escolha a ser utilizada para tentar impedir o agravamento do quadro isquêmico?","options":{"A":"Aspirina","B":"Pentoxifilina","C":"Vasodilatador","D":"Heparina","E":"Somente analgésicos"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-46680","number":"46680","sourceNumber":"46680","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual dos fatores abaixo não é indicação formal de cirurgia bariátrica?","options":{"A":"Hipertensão de difícil controle com IMC acima de 35.","B":"Doente com quadro de hipotireoidismo de difícil controle e IMC acima de 35.","C":"Diabético em uso de hipoglicemiante com IMC 36.","D":"Paciente super obeso que colocou balão e perdeu 20 kg em seis meses de tratamento.","E":"IMC acima de 50."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-9995","number":"9995","sourceNumber":"9995","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual a patologia cirúrgica que em geral apresenta de início: vômitos não-biliosos se\niniciados após 3 semanas de vida, podendo surgir na 1ª semana de vida ou somente no 5º mês de\nvida?","options":{"A":"Estenose hipertrófica do piloro.","B":"Doença do refluxo gastro-esofágico.","C":"Hérnia de hiato.","D":"Estenose duodenal.","E":"Erros inatos do metabolismo."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-10040","number":"10040","sourceNumber":"10040","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sr. Nilson tem 66 anos, é diabético, hipertenso e tem insuficiência arterial periférica.\nUsa regularmente diurético e sulfanilureía. Há 3\ndias, apresenta uma ferida no 5° pododáctilo direito\ncom secreção purulenta e febre. Hoje, sua pressão arterial esta 200 x 110mmHg e sua glicemia\ncapilar 330. Você o examina e:","options":{"A":"encaminha-o para internação hospitalar solicitando avaliação pelo cirurgião vascular de plantão\nno pronto-socorro. Inicia insulinoterapia.","B":"Acrescenta beta-bloqueador ao esquema anti-hipertensivo e pede urgente avaliação cirúrgica no\npronto-socorro.","C":"aumenta as doses do diurético e da sulfanilureia e inicia antibioticoterapia oral.","D":"encaminha-o para internação hospitalar e inicia antibioticoterapia oral e biguanida.","E":"inicia insulinoterapia e antibioticoterapia oral domiciliar."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-324677","number":"324677","sourceNumber":"324677","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, procura o médico da família com queixa\nde ferida em mucosa oral há um mês. Relata,\ntambém, o surgimento de nódulo em região cervical\ndireita, neste mesmo período. O paciente é etilista e tabagista de 20 cigarros por dia, há 40 anos.\nAo exame físico, bom estado geral, presença de ferida ulcerada em mucosa sublingual, medindo\ncerca de 2cm; palpado nódulo em região cervical posterior à direita, medindo cerca de 1,5cm;\nausculta cardíaca e respiratória sem alterações; abdome plano, flácido e indolor à palpação. Diante\ndesse caso clínico, indique a principal suspeita etiológica para a ferida em mucosa oral.","options":{"A":"Carcinoma espinocelular.","B":"Lesão de mucosa oral durante a mastigação.","C":"Úlcera oral por herpes simples.","D":"Carcinoma basocelular."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-324678","number":"324678","sourceNumber":"324678","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, procura o médico da família com queixa\nde ferida em mucosa oral há um mês. Relata,\ntambém, o surgimento de nódulo em região cervical\ndireita, neste mesmo período. O paciente é etilista e tabagista de 20 cigarros por dia, há 40 anos.\nAo exame físico, bom estado geral, presença de ferida ulcerada em mucosa sublingual, medindo\ncerca de 2cm; palpado nódulo em região cervical posterior à direita, medindo cerca de 1,5cm;\nausculta cardíaca e respiratória sem alterações; abdome plano, flácido e indolor à palpação. Com\nbase nas informações, indique a conduta mais adequada, nesse momento, para a ferida em\nmucosa oral.","options":{"A":"Biópsia excisional.","B":"Ressecção da lesão com margem de 5mm.","C":"Biópsia incisional.","D":"Tratamento tópico com pomada de triancinolona."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-324679","number":"324679","sourceNumber":"324679","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, procura o médico da família com queixa\nde ferida em mucosa oral há um mês. Relata,\ntambém, o surgimento de nódulo em região cervical\ndireita, neste mesmo período. O paciente é etilista e tabagista de 20 cigarros por dia, há 40 anos.\nAo exame físico, bom estado geral, presença de ferida ulcerada em mucosa sublingual, medindo\ncerca de 2cm; palpado nódulo em região cervical posterior à direita, medindo cerca de 1,5cm;\nausculta cardíaca e respiratória sem alterações; abdome plano, flácido e indolor à palpação.\n\nIndique a conduta mais apropriada para a investigação do nódulo cervical da paciente.","options":{"A":"Punção aspirativa por agulha fina.","B":"Exérese do nódulo.","C":"Observação do nódulo por 14 dias.","D":"Tomografia computadorizada cervical."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-62874","number":"62874","sourceNumber":"62874","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Pacientes submetidos à cirurgia bariátrica apresentam maior risco de complicação\nquando:","options":{"A":"Tiverem idade < 40 anos.","B":"IMC > 60 kg/m².","C":"Cursarem com dislipidemia.","D":"Forem portadores de refluxo gastroesofágico.","E":"O teste ergométrico for negativo para isquemia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-62847","number":"62847","sourceNumber":"62847","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 26 anos de idade, sem outras comorbidades, no\n\npós-operatório tardio de cirurgia bariátrica, evolui com dor em mesogástrio tipo cólica, sem\nvômitos,\ncom parada na eliminação de flatos e fezes. A\nconduta mais indicada deve ser:","options":{"A":"Iniciar hidratação, realizar RX de abdome, iniciar analgesia e realizar videolaparoscopia\ndiagnóstica.","B":"Realizar USG abdominal e indicar colecistectomia laparoscópica.","C":"Solicitar endoscopia digestiva e tratar impactação alimentar.","D":"Solicitar TC abdominal com pesquisa de ureterolitíase e encaminhar para avaliação com\nurologista.","E":"Iniciar hidratação e analgesia, administrar antiemético e dar alta hospitalar."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-35012","number":"35012","sourceNumber":"35012","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo masculino, 38 anos de idade, submetido à hemorroidectomia pela\ntécnica de Milligan-Morgan, cursa com sangramento copioso anal 6 horas após a cirurgia. A\nconduta CORRETA a ser tomada é:","options":{"A":"realizar tamponamento anal com adrenalina.","B":"expectar.","C":"fazer revisão cirúrgica e hemostasia.","D":"indicar hemotransfusão, apenas.","E":"esclerose com perianal com Ethamolin®."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-11212","number":"11212","sourceNumber":"11212","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo feminino, 60 anos de idade, queixa-se de sangramento ao evacuar,\nalém de nódulo na região anal. Ao exame\nfísico, foram notados mamilos hemorroidários,\nprolapsados que não retornam ao interior do ânus. A melhor conduta para essa paciente é:","options":{"A":"Solicitar colonoscopia e, após descartadas outras causas de sangramento intestinal, programar\nhemorroidectomia.","B":"Solicitar colonoscopia e, após descartadas outras causas de sangramento intestinal, programar\nligaduras elásticas.","C":"Solicitar retossigmoidoscopia e, após descartadas outras causas de sangramento intestinal,\nprogramar ligaduras elásticas.","D":"Solicitar enema opaco e, se normal, programar ligaduras elásticas.","E":"Realizar hemorroidectomia e solicitar exames complementares apenas se a paciente apresentar\nperda ponderal ou dor abdominal."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343356","number":"343356","sourceNumber":"343356","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. A principal hipótese diagnóstica é:","options":{"A":"Displasia neuronal do tipo B.","B":"Constipação funcional.","C":"Doença de Hirschsprung.","D":"Enterocolite necrotizante."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343357","number":"343357","sourceNumber":"343357","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. Das alternativas abaixo, a conduta mais adequada é:","options":{"A":"Cirurgia de urgência.","B":"Tratamento clínico com ajuste dietéticos e laxativos, apenas.","C":"Dieta zero, sonda gástrica em drenagem e antibioticoterapia.","D":"Colostomia e abaixamento de cólon posteriormente ou manejo de cólon e tratamento cirúrgico\nendoanal sem colostomia."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343359","number":"343359","sourceNumber":"343359","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre as oclusões arteriais agudas, assinale a incorreta.","options":{"A":"Muitos êmbolos têm origem no coração e, em particular, no coração esquerdo, a partir da\nfragmentação de trombos intracavitários.","B":"A causa mais frequente da formação dos trombos é a fibrilação atrial que acompanha as lesões\nda valva mitral de origem reumática, o\nhipertireoidismo, o infarto agudo do miocárdio (IAM) e a\nmiocardiosclerose.","C":"Dentre as valvopatias, a mais frequente como causa de embolia é a doença valvar mitral, em\nparticular a estenose mitral de origem reumática.","D":"A endocardite bacteriana aguda ou subaguda é causa rara de embolia arterial, pois acomete\nmais as câmaras direitas do coração, e não\npropiciam a formação de trombos murais nos átrios e\nnos ventrículos."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343360","number":"343360","sourceNumber":"343360","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a doença arterial obstrutiva periférica dos membros inferiores, assinale a\nincorreta.","options":{"A":"A obstrução da artéria femoral superficial é encontrada em cerca da metade dos casos de\ndistúrbios isquêmicos dos membros pélvicos. Embora a obstrução geralmente seja inicialmente\nunilateral, ao final de 4 anos, 75% dos pacientes desenvolvem oclusões bilaterais.","B":"Dos exames que permitem visibilizar a árvore circulatória, o EcoDoppler colorido é\n\ncontra-indicado pois tem restrição na avaliação da circulação arterial dos membros inferiores, e não\nfaz análise qualitativa as dimensões do processo obstrutivo assim o grau de instabilidade do vaso.","C":"Embora a aterotrombose seja a patologia responsável pelos sintomas isquêmicos em mais de\n90% dos casos, outras doenças devem ser\nlembradas, como a tromboangiite obliterante, outras\narterites, doença cística da adventícia, síndrome de aprisionamento da poplítea e as sequelas de\ntraumatismos.","D":"A classificação empregada para o estadiamento da doença em questão é a clássica de\nFontaine. Estágio I: assintomático, II:\nclaudicação intermitente, III: dor isquêmica em repouso, IV:\nlesões tróficas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-281869","number":"281869","sourceNumber":"281869","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Todas as alternativas abaixo são indicações clínicas para o uso de CPAP, exceto.","options":{"A":"Manejo da síndrome do desconforto respiratório.","B":"Traqueomalácia.","C":"Paralisia do nervo frênico.","D":"Fistula traqueoesofágica."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-281878","number":"281878","sourceNumber":"281878","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Considerando os aspectos fisiopatológicos da doença arterial obstrutiva periférica, as\nmanifestações mais comuns da isquemia crítica são:","options":{"A":"Dor em repouso persistente e ulceração ou gangrena.","B":"Edema e ulceração ou gangrena.","C":"Dermatolipofibrose e edema.","D":"Dor em repouso persistente e edema."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-281879","number":"281879","sourceNumber":"281879","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Pela classificação de Fontaine para arteriopatias obstrutivas, um paciente no estágio IIA\napresenta:","options":{"A":"Claudicação moderada/grave","B":"Dor em repouso","C":"Úlcera.","D":"Claudicação leve."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-281882","number":"281882","sourceNumber":"281882","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A figura abaixo ilustra uma piloromiotomia pela técnica de Fredet-Ramstedt. Tal\nprocedimento é realizado para o tratamento de:","options":{"A":"Doença do refluxo gastroesofágico.","B":"Atresia duodenal.","C":"Atresia antropilórica.","D":"Estenose hipertrófica de piloro."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-249994","number":"249994","sourceNumber":"249994","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A úlcera linear que envolve a metade inferior do canal anal, em geral localizada na\ncomissura posterior da linha média é definida por:","options":{"A":"Fissura Anal.","B":"Fístula anal.","C":"Hemorroida.","D":"Cisto pilonidal."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-250000","number":"250000","sourceNumber":"250000","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Deve-se evitar a gastrectomia vertical no segmento de cirurgia da obesidade nos\nseguintes casos:","options":{"A":"Doença de refluxo gastro-esofágico e esofagite erosiva.","B":"Pacientes com índice de massa corpórea > 40.","C":"Pacientes hipertensos em uso de bloqueador de canal de cálcio.","D":"Não há contraindicações para gastrectomia vertical."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215597","number":"215597","sourceNumber":"215597","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"De acordo com o estadiamento TNM (UICC 2002), os tumores supraglóticos limitados à\nlaringe com paralisia de prega vocal, que invade área pós-cricoide, tecidos pré-epiglóticos e espaço\nparaglótico ou que apresenta erosão de cartilagem tireoidea são classificados como:","options":{"A":"T1.","B":"T2.","C":"T3.","D":"T4."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-157622","number":"157622","sourceNumber":"157622","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Aponte a alternativa CORRETA.","options":{"A":"A Gastrosquise é caracterizada pelo defeito localizado em região paraumbilical esquerda, cujo\ndefeito é pequeno; o cordão umbilical normalmente fica lateral ao defeito, sendo raro o infarto\nintestinal.","B":"A Gastrosquise frequentemente se associa a infarto intestinal e atresias intestinais; anomalias\nassociadas são frequentes.","C":"A Onfalocele raramente se associa a atresias intestinais; a cavidade abdominal é pequena, e os\ninfartos intestinais são raros.","D":"A Onfalocele é caracterizada pelo defeito no anel umbilical, sendo esse defeito variável de 4 a\n10 cm; o cordão umbilical se inclui no\ndefeito, e as anomalias associadas são raras."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-157664","number":"157664","sourceNumber":"157664","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre os Aneurismas de Aorta, assinale a opção INCORRETA.","options":{"A":"O risco de ruptura e de cirurgia aumenta com o diâmetro.","B":"Os aneurismas saculares apresentam maior probabilidade de ruptura que os fusiformes.","C":"Nas cirurgias de urgência para aneurismas sintomáticos, a mortalidade chega a 20%, e quando\nhá ruptura podem alcançar 60%.","D":"Os aneurismas micóticos podem se instalar através de êmbolos sépticos ou por continuidade. O\ngerme mais comum do aneurisma infecioso relacionado com endocardite é a cândida albicans."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-157730","number":"157730","sourceNumber":"157730","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a alternativa ERRADA.","options":{"A":"Hérnia inguinal é a afecção mais frequente da criança. Podendo acometer 30% dos prematuros,\nsendo o lado D mais acometido.","B":"O diagnóstico é clínico, realizado pela simples observação e eventualmente palpação.","C":"O tratamento cirúrgico deve ser indicado após 2 anos de idade.","D":"A hérnia inguinal da criança é na grande maioria das vezes do tipo indireta ou oblíqua externa."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-157727","number":"157727","sourceNumber":"157727","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quais alterações a criança com estenose hipertrófica do piloro apresenta?","options":{"A":"Alcalose metabólica e hipocloremia.","B":"Vômitos biliosos e letargia.","C":"Vômitos biliosos e acidose metabólica.","D":"Letargia e hipercloremia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-350871","number":"350871","sourceNumber":"350871","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma mãe traz uma criança de 6 anos com queixa de um nódulo arredondado de cerca\nde 3cm, em região cervical central superior,\nmais aparente ao estender o pescoço posteriormente.\nAo exame, percebe-se que a lesão se eleva ao pedir para a criança colocar a língua para fora. A\nlesão tem consistência firme porém não apresenta dor a palpação. Imagem anexa. Trata-se de um\nremanescente embrionário de qual das seguintes estruturas?","options":{"A":"Osso hioide.","B":"Anéis traqueais.","C":"Glândula tireoide.","D":"Cartilagem tireoide."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-350862","number":"350862","sourceNumber":"350862","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 23 anos sedentário, IMC 34, queixa-se de dor em região perianal. Essa dor\nteve início bem leve há cerca de 5 dias, porém vem aumentando a sua intensidade de forma\nprogressiva, chegando ao ponto de ficar insuportável, impedindo o paciente de realizar seu hobby,\nque é passar cerca de 8 horas por dia sentado, usando o computador para prática de \"games\",\nmídia social e assistir séries. Ao exame, apresenta a lesão da imagem anexa. Qual deve ser a\nconduta nesse momento?","options":{"A":"Expectante, com anti-inflamatório e antibiótico.","B":"Drenagem, associado a anti-inflamatório e antibiótico.","C":"Ressecção ampla com retalho para cobrir a área aberta.","D":"Laserterapia para remoção definitiva de pelos e antibiótico."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-350858","number":"350858","sourceNumber":"350858","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 44 anos com IMC de 41kg/m² diabético, em uso de metformina duas\nvezes ao dia, será submetido a cirurgia\nbariátrica. O cirurgião sugere a técnica Sleeve. Qual das\nseguintes opções melhor descreve o(s) mecanismo(s) de perda de peso dessa cirurgia?","options":{"A":"Restrição gástrica e diminuição da produção de grelina.","B":"Desvio duodenal e pancreático com alça comum de 1,5m.","C":"Restrição gástrica e desvio de cerca de 2,5m de intestino delgado.","D":"Restrição gástrica com reservatório com capacidade menor que 90ml."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-350881","number":"350881","sourceNumber":"350881","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Menina de 9 meses é avaliada na emergência com febre há 3 dias, vômitos incoercíveis\ne dor abdominal difusa em cólicas de forte\nintensidade e eliminação de fezes com sangue. Exame\nfísico de difícil execução pela irritação. Ultrassonografia não havia disponível. Realizados raios X\nsimples de abdome evidenciou-se diminuição de ar no quadrante superior direito do abdome,\nedema e deslocamento das alças intestinais para a região do hipocôndrio esquerdo e ausência de\nar em hipogástrio. Qual é a hipótese diagnóstica mais provável para esse caso?","options":{"A":"Intussuscepção intestinal.","B":"Cetoacidose diabética.","C":"Pneumonia de base.","D":"Pancreatite aguda."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-321278","number":"321278","sourceNumber":"321278","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente de 35 anos foi submetida à cirurgia bariátrica, a Sleeve (gastroplastia\nvertical), há 6 meses, com perda de 35 kg no\nperíodo. IMC inicial era 37, atual de 24. Refere\npraticar atividade física regular 3 vezes por semana e seguir a orientação da nutricionista com uma\ndieta balanceada em legumes variados e ingesta protéica 4 vezes ao dia, com volume médio de\n180ml ou g a cada refeição, intercaladas por líquidos e lanches leves. Nega uso de medicações.\n\nAtualmente, apresenta uma sensação de fraqueza ao executar suas tarefas diárias. Qual das\nseguintes condições clínicas está mais\nassociada a essa modalidade cirúrgica e é compatível com\nas queixas dessa paciente?","options":{"A":"Deficiência de ferro.","B":"Anemia megaloblástica.","C":"Deficiência de vitamina D.","D":"Baixo condicionamento cardiorrespiratório."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-292796","number":"292796","sourceNumber":"292796","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na emergência, um cirurgião atende menino de 10 anos com dor testicular, há cerca de\n4 horas, de início súbito. Ao exame da\nhemibolsa escrotal esquerda, há pouca mobilidade a\npalpação e desaparecimento do reflexo cremastérico. Não há disponível ultrassonografia na região.\nQual o diagnóstico provável?","options":{"A":"Torção testicular.","B":"Hidrocele escrotal.","C":"Hematoma testicular.","D":"Orquiepidimite infecciosa."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-292808","number":"292808","sourceNumber":"292808","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 64 anos, fumante, obeso (grau I), DM de longa data e hipertenso, queixas\nde dor e fadiga nos membros inferiores ao\ndeambular, principalmente à esquerda. Atualmente,\nrefere piora com bastante limitação de caminhada e dor até em repouso no pé e panturrilha\nesquerda, alternando com dormência da região. Qual deve ser o próximo passo para esse\npaciente?","options":{"A":"Prescrever terapia farmacológica com pentoxifilina.","B":"Realizar a amputação da perna esquerda acima do joelho.","C":"Realizar procedimento endovascular para colocação de stent.","D":"Realizar angiorressonância ou angiotomografia de membros inferiores."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-259705","number":"259705","sourceNumber":"259705","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente, sexo masculino, 47 anos, apresenta-se com história de sangramento anal\nvermelho vivo e dor após as evacuações (chegando a pingar no vaso), associado a ardor e prurido\nanal de início há 3 dias. Refere piora recente da alimentação devido quadro de ansiedade, com\nfezes mais ressecadas e maior esforço evacuatório. Nega outros sintomas associados,\ncomorbidades ou cirurgias prévias. Após realização do exame proctológico, qual a melhor conduta\na seguir?","options":{"A":"Solicitação de colonoscopia com biópsia, seguido de tomografia de tórax e abdome com\ncontraste.","B":"Mudança alimentar e ligadura elástica e solicitação de colonoscopia para investigação de outras\npossíveis fontes de sangramento.","C":"Mudança de hábitos alimentares e defecatórios, medicações sintomáticas, seguido de\nsolicitação de retossigmoidoscopia e/ou colonoscopia.","D":"Aumento da ingesta hídrica, mudança alimentar, laxativo e agentes esclerosantes e orientação\nquanto a colonoscopia a partir dos 50 anos."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-259706","number":"259706","sourceNumber":"259706","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente 34 anos no segundo pós-operatório de gastroplastia a Sleeve, peso de 120kg,\nem uso de Clexane 40 mg/dia, deambulando,\niniciou quadro de dor retroesternal contínua, febre de\n38 graus. Realiza dieta líquida restrita 20 ml a cada 20 min e não refere piora à deglutição. Ao\nexame: FC 120 bpm, dor em região epigástrica sem rigidez abdominal evidente. Ausculta cardíaca:\nbatimentos regulares, taquicardia; ausculta pulmonar: murmúrio vesicular diminuído nas bases,\nmais à esquerda. Qual o diagnóstico provável?","options":{"A":"Tromboembolismo pulmonar.","B":"Atelectasia pulmonar.","C":"Infarto do miocárdio.","D":"Fístula gástrica."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-259746","number":"259746","sourceNumber":"259746","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança de 8 anos de idade há 20 dias apresenta adenopatia supraclavicular esquerda\nacompanhada de febre diária. Ao exame\nfísico, observam-se linfonodos endurecidos, pouco\ndolorosos, coalescidos e aderidos a planos profundos, o maior cerca de 4 cm de diâmetro, sem\nsinais flogísticos. Nega uso de antibioticoterapia. Pai em tratamento para tuberculose. Quais os\nachados que definem que o pediatra indique uma biópsia ganglionar dessa criança?","options":{"A":"Localização e a consistência do gânglio.","B":"Tempo de evolução e o tamanho do gânglio.","C":"Contactante de tuberculose e febre persistente.","D":"Idade do paciente e ausência de sinais flogísticos."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-234011","number":"234011","sourceNumber":"234011","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Crianc?a, sexo masculino, 2 anos de idade, estava brincando com um irma?o e levou\numa queda da pro?pria altura. Sua ma?e, ao levanta?-la do cha?o, achou que havia uma \"massa\"\nabdominal e resolveu leva?-la a? uma emerge?ncia. Na admissa?o, na?o havia alterac?o?es\nhemodina?micas ou outros sinais cli?nicos de perda vole?mica. Os pais informam que crianc?a\nnascera a termo, de parto normal, com gestac?a?o sem intercorre?ncias, incluindo ultrassom\nmorfolo?gico em terceiro trimestre normal e negaram quaisquer relatos de febre, alterac?a?o do\nha?bito intestinal ou urina?rio, dor ou perda de peso, nos u?ltimos tre?s meses. Ao exame, a\ncrianc?a apresentava-se com bom estado geral, estava ativa e normocorada, pore?m com\npresenc?a de lesa?o endurecida e indolor em hipoco?ndrio direito. Ausculta pulmonar e cardi?aca\nnormais. Sinais vitais sem alterac?o?es. Foi realizada ultrassonografia na urge?ncia que detectou\nlesa?o expansiva retroperitoneal a? direita, na?o sendo possi?vel caracterizar adequadamente rim\nipsilateral e adrenais. O Rx de to?rax revelou no?dulo de 2cm em lobo superior do pulma?o\nesquerdo compati?vel com prova?vel etiologia neopla?sica. Com base na situac?a?o cli?nica\ndescrita, o diagno?stico mais prova?vel e?:","options":{"A":"Tumor de Wilms.","B":"Feocromocitoma.","C":"Neuroblastoma metasta?tico.","D":"Carcinoma de ce?lulas renais."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-234016","number":"234016","sourceNumber":"234016","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Menino de 8 anos de idade apresenta um \"caroço\" em região cervical anterior, sem\nqualquer sintomatologia. O crescimento desta lesão tem sido lento há mais de um ano e não há\nrelato de infecção ou dor locais. Ao exame físico, observa-se que a massa se encontra em linha\nmédia, possui limites laterais bem definidos e mobilidade à deglutição. Ultrassonografia revela que\na lesão é hipoecóica, com tireoide em posição habitual e sem qualquer anormalidade.\n\nConsiderando o diagnóstico mais provável, a condutadeve incluir:","options":{"A":"Tomografia computadorizada de face e região cervical.","B":"Escleroterapia radioguiada seguida de ressecção cirúrgica.","C":"Exérese de persistência de trajeto fistuloso até a fossa tonsilar.","D":"Ressecção em bloco junto com porção central do osso hioide."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-234021","number":"234021","sourceNumber":"234021","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 78 anos, procurou uma UPA com queixa de dor em todo o\npe? esquerdo, de moderada intensidade, ale?m de\npequeno ferimento que ocorreu ha? cerca de 20\ndias apo?s um pequeno incidente dome?stico (esbarrou na quina de um mo?vel) e ainda na?o\ncicatrizou. Faz uso de medicac?o?es para tratamento cli?nico para dislipidemia e hipertensa?o\narterial siste?mica. E? tabagista ha? 30 anos, com um consumo estimado de 10 cigarros ao dia.\n\nNega tratamento para diabetes. Nega sintomas de claudicac?a?o intermitente. Ao exame,\napresentava-se com taquicardia leve e pulso\nirregular, os pulsos femoral e popli?teo a? esquerda\nna?o eram palpa?veis e havia um ferimento superficial de 0,5 cm em dorso do 4o pododa?ctilo\nesquerdo, sem sinais de gangrena. Com base na situac?a?o cli?nica exposta, qual dos achados\nabaixo e? indicativo de encaminhamento a um servic?o de cirurgia vascular?","options":{"A":"Taquicardia com freque?ncia cardi?aca irregular.","B":"Ause?ncia de pulsos femoral e popli?teo em MIE.","C":"Dor localizada em todo o pe? esquerdo.","D":"Ferimento no dorso do 4° pododa?ctilo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-199713","number":"199713","sourceNumber":"199713","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma mulher de 43 anos foi submetida a by-pass gástrico há 8 meses para tratamento\nde obesidade mórbida. Desde a cirurgia, a\npaciente vem realizando atividades físicas noturnas,\ncomo musculação e corridas matinais 4 vezes por semana e já perdeu 32 kg (peso inicial 90 kg).\nNão está tomando medicações. Há cerca de 3 semanas, ela tem notado episódios de náuseas, dor\nabdominal em cólicas, diarreia, palpitações, tonturas e sudorese profusa pós-alimentares,\nmotivando a necessidade de antecipação de uma consulta de retorno ambulatorial. Qual o\ndiagnóstico provável?","options":{"A":"Deficiência de ferro.","B":"Síndrome de dumping.","C":"Deficiência de tiamina.","D":"Desnutrição calórico-proteica."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-199732","number":"199732","sourceNumber":"199732","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança, 4 anos de idade, sexo masculino, é levado por seus pais a um médico\ncirurgião pediátrico por relato de aumento\nintermitente de volume do testículo esquerdo, há 3\nmeses. Segundo informam, ao acordar, eles não percebem qualquer alteração, mas, ao final do\ndia, particularmente após dia intenso de brincadeiras, notam ?grande aumento do testículo? do\nfilho. A criança não se queixa de qualquer dor e não há histórico de trauma na região. Ao exame\nfísico, observam-se testículos tópicos de tamanho e aspecto normais, com hidrocele significativa à\nesquerda (transiluminação positiva), mas sem qualquer sinal flogístico local. Também, não se\npercebe abaulamento em região inguinal em ambos os lados,mesmo após manobras de Valsalva.\nA melhor conduta para esta criança é:","options":{"A":"Observar clinicamente até 5 anos de idade e aguardar a resolução espontânea.","B":"Solicitar ultrassonografia para avaliar a presença de hérnia inguinal associada.","C":"Estabelecer tratamento cirúrgico: ligadura do conduto peritoneovaginal esquerdo.","D":"Indicar tratamento cirúrgico da hidrocele: acesso escrotal com eversão da túnica vaginal."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-199683","number":"199683","sourceNumber":"199683","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"As linfonodomegalias localizadas ou disseminadas são características de uma enorme\ngama de patologias na infância e são\nqueixas frequentes no ambulatório de pediatria. Qual a\nassertiva correta com relação a indicação de biópsia do linfonodo?","options":{"A":"Biopsiar linfonodos localizados elásticos, móveis, indolores, de tamanho menores que 2 a 3 cm.","B":"Biopsiar linfonodos dolorosos, com sinais flogísticos e pouco aderidos a planos profundos.","C":"Biopsiar linfonodos persistentes e sem redução após 2 semanas de antibioticoterapia.","D":"Biopsiar linfonodos cervicais e epitrocleares de até 2,5 cm na ausência de infecção."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-173022","number":"173022","sourceNumber":"173022","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 44 anos, após uma conversa com um grupo de amigos sobre pessoas\nconhecidas que realizaram cirurgia\nbariátrica e os excelentes resultados alcançados com a perda\nde peso em curto prazo, decide marcar uma consulta com uma equipe de cirurgia bariátrica. Nesta\nconsulta, o cirurgião identifica: peso = 106 kg e altura = 1,73m. O paciente é sedentário, apresenta\nmaus hábitos alimentares e é portador de uma hérnia de disco cervical. Hábitos: uso regular de\nbebida alcoólica nos finais de semana em quantidade pequena a moderada. Histórico: não tem\nregistro de tratamentos para obesidade. Com base na consulta, qual seria a melhor conduta pela\nequipe cirúrgica?","options":{"A":"Indicar a cirurgia bariátrica através da técnica de gastroplastia vertical por\nvideolaparoscopia, por\nser a técnica mais adequada para esses\ncasos.","B":"Orientar que o paciente tenha um ganho de peso e que assim fortaleça a indicação cirúrgica\ndesejada devido a superioridade dos resultados cirúrgicos.","C":"Solicitar exames pré-operatórios e avaliação multiprofissional para realização da cirurgia\nbariátrica através da técnica do by-pass gástrico em y de Roux.","D":"Recomendar terapia nutricional supervisionada para perda de peso, com mudanças dos hábitos\nde vida e, posteriormente, avaliar a\nresposta."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-150829","number":"150829","sourceNumber":"150829","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 14 anos de idade é atendido em setor de emergência em um hospital de\nnível secundário, no período noturno, com queixa\nde dor testicular direita intensa, de início súbito,\nhá 3 horas. Nega febre, queixas urinárias e intestinais. Ao exame físico, observa-se testículo\ndireito\nem posição tópica, mas algo elevado, com dor intensa e difusa à sua palpação e com reflexo\ncremastérico diminuído. Por sua vez, testículo esquerdo encontra-se tópico, sem quaisquer\nalterações. Qual das seguintes condutas deverá estar incluída no tratamento desse paciente?","options":{"A":"Cintilografia inguinal.","B":"Orquidopexia esquerda.","C":"Ultrassonografia abdominal de urgência.","D":"Antiinflamatórios e reavaliação após 6 horas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-126958","number":"126958","sourceNumber":"126958","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A grande maioria das doenças vasculares pode ser diagnosticada com uma anamnese\ne exame físico detalhados. O índice tornozelo\nbraquial é uma importante arma utilizada na\navaliação vascular, sendo mensurado através da relação entre a pressão no membro inferior\nestudado e a pressão no membro superior. Em uma pessoa normal em repouso, qual o intervalo do\níndice que esperaríamos encontrar?","options":{"A":"0,4 a 0,6","B":"0,6 a 0,8","C":"0,8 a 1,0","D":"1,0 a 1,2"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-127012","number":"127012","sourceNumber":"127012","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dona Elisa, 70 anos, é acompanhada na unidade de saúde do seu bairro. Ela possui\ndiabetes mellitus e hipertensão controladas.\nCompareceu hoje ao ambulatório com a queixa de\n\"ferida no pé\" há 7 dias. Relata que não apresentou trauma prévio no local e que há 15 dias vem\napresentando dificuldade para caminhar, que a limita de exercer suas atividades habituais, tais\ncomo ir ao culto e visitar sua filha que mora a dois quarteirões de distância da sua casa. Relata\nque\nprecisa parar pelo menos duas vezes no percurso devido à dor em membros inferiores. Ao exame,\napresenta PA 150x90mmHg, IMC=24kg/m². Ausculta cardíaca com ritmo cardíaco regular,\nhiperfonese de B2, sem sopros. Ausculta pulmonar: murmúrio vesicular universal. Membros\ninferiores: sem edema, ausência de pêlos, pequenas varicosidades. Pé direito apresenta\nlesão ulcerada em dorso, com fundo limpo. Xerodermia e eritema perilesional. (VER IMAGEM)\nQual a conduta a ser tomada a seguir a partir dos achados da anamnese e do exame físico\nexplicitado?","options":{"A":"Solicitar biópsia das bordas da lesão.","B":"Realizar a aferição do Índice Tornozelo Braquial.","C":"Encaminhar ao serviço de cirurgia para desbridamento.","D":"Fazer cobertura local e prescrição de meias de compressão."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/127012.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-102099","number":"102099","sourceNumber":"102099","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente feminina, 48 anos, queixando-se de pequeno nódulo perianal que surgiu há\naproximadamente um ano, precedido por um abscesso, no mesmo local, que drenou\nespontaneamente. Diz ser indolor, porém elimina secreção serosa, às vezes, com fragmentos de\nfezes. Paciente procurou serviço especializado, onde foi submetida à retossigmoidoscopia flexível e\na exame ultrassonográfico endoanal tridimensional. Os exames evidenciaram fístula perianal\ninteresfinctérica, com orifício interno situado no quadrante anterior direito. O trajeto compromete\naproximadamente 80% do complexo esfincteriano. Diante do exposto, qual o tratamento mais\nadequado?","options":{"A":"Fistulotomia, fechamento do orifício interno e avanço de retalho mucoso.","B":"Fistulectomia e síntese da ferida sem o emprego de sedenho.","C":"Fistulectomia em um tempo e marsupialização da ferida.","D":"Fistulectomia e emprego de cola de fibrina."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-102089","number":"102089","sourceNumber":"102089","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 68 anos é atendido na emergência com quadro de dor abdominal súbita e\nintensa periumbilical acompanhada de síncope com sudorese profusa. Ao exame: estado geral\ntorporoso; palidez (+++/4+); PA: 70 x 30 mmHg; pulso filiforme taquicárdico. Abdome dolorido\ndifusamente com massa palpável mesoabdominal, pulsátil. Demais achados: paciente apresenta\naspecto sindrômico, estatura elevada, pectus excavatum, rosto afilado, micrognatia e pés chatos.\nApós infusão de 1 litro de solução cristaloide, PA: 100 x 60 mmHg. Qual exame é melhor indicado\npara diagnóstico e planejamento terapêutico, nessa circunstância?","options":{"A":"Angiografia.","B":"US abdominal.","C":"TC com contraste.","D":"RM com contraste."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-102098","number":"102098","sourceNumber":"102098","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 46 anos, queixando-se de hematoquezia há mais de 6 anos.\nInforma que, no início, os episódios eram\nesporádicos. Porém, com o passar dos anos, foram se\ntornando mais frequentes. Refere ainda que, nos últimos 2 anos, passou a ter prolapso, redutível\nespontaneamente, porém atualmente necessita de auxílio digital. Com esse quadro clínico,\nprocurou serviço especializado. Assinale o diagnóstico mais provável e o tratamento mais\nadequado:","options":{"A":"Hemorroidas grau II; hemorroidectomia a Ferguson.","B":"Hemorroidas grau IV; esclerose com glicose hipertônica.","C":"Hemorroidas grau III; hemorroidectomia a Milligan-Morgan.","D":"Hemorroidas grau IV; hemorroidopexia com grampeador mecânico nº 33."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-102102","number":"102102","sourceNumber":"102102","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 42 anos, sexo masculino, apresenta um tumor cervical que a biópsia revela\num carcinoma mucoepidermoide de lobo superficial da parótida direita sem evidências de\nmetástases a distância. Qual o tratamento recomendado para esse caso?","options":{"A":"Parotidectomia total.","B":"Parotidectomia total com esvaziamento cervical.","C":"Lobectomia lateral com preservação do nervo facial.","D":"Radioterapia neoadjuvante seguida de parotidectomia total."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-102126","number":"102126","sourceNumber":"102126","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 1,8 m de altura, peso de 123 kg, hipertenso e diabético,\ntendo tido falha na terapêutica clínica,\nestável do ponto de vista psiquiátrico e sem dependência de\nálcool e droga ilícita, procura ambulatório de cirurgia em busca de tratamento cirúrgico. Na\navaliação pré-operatória, qual das opções abaixo deve ser considerada uma CONTRAINDICAÇÃO\nabsoluta para esta opção terapêutica?","options":{"A":"Idade superior a 65 anos.","B":"Portador do vírus C da hepatite.","C":"A presença da Síndrome de Prader-Willi.","D":"Índice de massa corpórea acima de 60 Kg/m²."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-81267","number":"81267","sourceNumber":"81267","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente jovem, do sexo feminino, e com relato de dor anal às evacuações há cerca de\ntrês meses. A dor é mais intensa ao evacuar, porém, persiste por cerca de 30 minutos após a\nevacuação. Nega sangue nas fezes e, ocasionalmente, há sangue vivo no papel higiênico, ao se\nassear. Considerando a história clínica descrita, qual das seguintes alternativas corresponde ao\nachado de exame físico esperado?","options":{"A":"Rágades no anoderma.","B":"Fissura mediana posterior.","C":"Mamilos hemorroidários internos grau III.","D":"Mamilo hemorroidário externo com trombose aguda."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-81325","number":"81325","sourceNumber":"81325","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Maria, 60 anos, recém-chegada na comunidade, comparece à unidade de saúde da\nfamília para avaliação de rotina. Ela\nrefere diabetes há 20 anos, faz uso de hipoglicemiantes orais e\nfuma 20 cigarros por dia há 30 anos. Nega hipertensão arterial. Há seis meses apresentava dor em\npanturrilhas quando caminhava aproximadamente 500 metros, que aliviava imediatamente após o\nrepouso. Há três meses refere que, para percorrer o mesmo percurso, precisava parar cinco a seis\nvezes. Atualmente, apresenta dor ao caminhar dentro de sua casa, impossibilitando-a de ir ao\nbanheiro e à cozinha. Trouxe exames realizados há 15 dias, com os seguintes resultados: glicemia\nem jejum 140 mg/dl, hemoglobina glicada 7,5%, colesterol total 240 mg/dl, HDL 30 mg/dl,\ntriglicerídeos: 200 mg/dl. Neste momento, qual a conduta mais adequada a ser adotada pelo\nmédico assistente?","options":{"A":"Solicitar ecodoppler de artérias dos membros inferiores e reavaliar após 7 dias.","B":"Encaminhar com urgência ao cirurgião vascular para avaliação em até 2 dias.","C":"Prescrever cilostazol 100 mg de 12/12 horas e AAS 100 mg por dia e reavaliar em 30 dias.","D":"Orientar um programa de exercício físico, cessação do tabagismo, controle intensivo do diabetes\ne dislipidemia. Reavaliar após 30 dias."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-65764","number":"65764","sourceNumber":"65764","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 45 anos foi diagnosticado com lesão tumoral no lobo profundo da\nparótida esquerda, sendo indicada uma\nparotidectomia total. Para qual das seguintes complicações\no paciente deve ser alertado durante a obtenção do termo de consentimento para a realização da\ncirurgia?","options":{"A":"Paralisia facial.","B":"Neuralgia do trigêmeo.","C":"Desvio unilateral da língua.","D":"Lesão de artéria carótida seguida de AVC.","E":"Perda de sensibilidade gustativa da língua."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-51143","number":"51143","sourceNumber":"51143","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 34 anos é admitido na emergência com dor anal intensa há cerca de 3\ndias. A dor, com caráter latejante e piora progressiva da intensidade, não está relacionada à\nevacuação. Ao exame proctológico, nota-se pequeno plicoma em posição anterior e hipertonia\nintensa com abaulamento doloroso ao toque da parede lateral esquerda do canal anal pouco acima\ndo esfíncter anal. Além de analgesia, que conduta adicional é recomendada para o paciente?","options":{"A":"Antibioticoterapia ambulatorial.","B":"Antibioticoterapia e drenagem cirúrgica imediata.","C":"Drenagem cirúrgica imediata independente de sinais de flutuação na lesão.","D":"Antibioticoterapia e drenagem cirúrgica após surgimento de sinais de flutuação na lesão."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-51272","number":"51272","sourceNumber":"51272","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O parto de uma gestante de 32 anos acaba de ser praticado a termo. Ao proceder à\nsecção do cordão umbilical, o médico observa que o cordão apresenta conteúdos abdominais\nfazendo protusão diretamente através do anel umbilical. Observa também uma espécie de saco\nprotegendo o conteúdo. Após assistência inicial ao recém-nascido, qual conduta deve ser\nestabelecida?","options":{"A":"Acesso venoso, hidratação, antibiótico de amplo espectro, sonda oro ou nasogástrica, proteção\ndo saco com compressa estéril e úmida,\nencaminhamento para centro de referência em cirurgia\npediátrica.","B":"Acesso venoso central, nutrição parenteral, sonda orogástrica, proteção do saco com compressa\nestéril e úmida, encaminhamento para\ncirurgia.","C":"Cateterização de veia umbilical, nutrição enteral, introdução do conteúdo para a cavidade\nabdominal, encaminhamento para cirurgia.","D":"Acesso intraósseo, hidratação, introdução do conteúdo para a cavidade abdominal,\nencaminhamento para avaliação cirúrgica pediátrica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-36963","number":"36963","sourceNumber":"36963","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 17 anos refere dor testicular à direita, de início súbito, há 4 horas, com\nhiperemia discreta e aumento do volume do testículo. Qual etapa propedêutica é mais importante\nnesse momento?","options":{"A":"Ultrassonografia de bolsa escrotal.","B":"Ultrassonografia com doppler testicular.","C":"Dosagem de ß-HCG e a-fetoproteína.","D":"Exame físico com manobra de Valsalva."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-36970","number":"36970","sourceNumber":"36970","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A principal causa de mortalidade pós-operatória, após correção cirúrgica de aneurisma\nde aorta abdominal é:","options":{"A":"Disfunção miocárdica.","B":"Insuficiência renal.","C":"Disfunção pulmonar.","D":"Isquemia cerebral."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-37386","number":"37386","sourceNumber":"37386","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"MFPD, feminino, de 38 anos compareceu ao ambulatório na atenção primária\nqueixando-se de sangramento vermelho-vivo\npresente ao limpar-se com papel higiênico e dor ao\nevacuar. Refere constipação crônica com piora há três meses, coincidente com a presença da\ndisquesia. Com base nessa história, assinale o diagnóstico mais provável.","options":{"A":"Plicoma anal.","B":"Hemorroidas internas.","C":"Hemorroidas externas.","D":"Fissura anal crônica.","E":"Fístula perianal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-37644","number":"37644","sourceNumber":"37644","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dona Vanda procurou Dr. Dênis com queixa de úlcera única em terço distal da perna\nesquerda, muito dolorosa, com bordas irregulares e base pálida. Qual a etiologia mais provável?","options":{"A":"Venosa.","B":"Isquêmica.","C":"Neurotrófica.","D":"Hipertensiva."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-37395","number":"37395","sourceNumber":"37395","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"PJDB, masculino 67 anos, tabagista crônico por 40 anos até 5 anos atrás. Há cerca de\n2 anos tem queixa de que ao andar cerca de\n10 quadras tem dor na panturrilha esquerda que\nlimitava sua caminhada forçando-o a parar por alguns instantes. Nos últimos meses tem\napresentado piora do quadro conseguindo atualmente andar cerca de 20 metros até ter que parar\npara poder andar novamente. Acerca da condição clínica do paciente, assinale a alternativa mais\ncorreta.","options":{"A":"O quadro clínico é compatível com isquemia crítica com risco iminente de perda do membro.","B":"Pacientes com claudicação intermitente devem ser\n\norientados a evitar exercícios físicos para que não haja piora clínica.","C":"A localização anatômica da obstrução provavelmente se situa na artéria femoral profunda.","D":"A condição clínica apresentada constitui indicação de tratamento por meio de procedimento\ncirúrgico.","E":"No caso da necessidade de um procedimento cirúrgico, em decorrência do aumento do risco\ncirúrgico, esse paciente deve ter uma avaliação cardiológica funcional como, por exemplo, o teste\nde esforço."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-25310","number":"25310","sourceNumber":"25310","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a doença hemorroidária, marque a alternativa correta:","options":{"A":"A doença hemorroidária tem incidência aumentada em pacientes com hipertensão portal, em\nrelação à população geral.","B":"É a principal causa de sangramento anorretal em crianças.","C":"Sua fisiopatologia envolve a dilatação venosa dos plexos hemorroidários, sem participação de\nshunts arteriovenosos.","D":"Varicosidades retais são usualmente indistinguíveis da doença hemorroidária, e devem ser\ntratadas da mesma maneira.","E":"A presença de dor no quadro da doença hemorroidária interna geralmente indica presença de\ncomplicações como trombose, gangrena ou estrangulamento."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-13432","number":"13432","sourceNumber":"13432","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mãe refere que sempre que a criança chora ?o testículo??aumenta de volume e quando ele dorme\ndiminui. Qual o diagnóstico mais provável?","options":{"A":"Orquite.","B":"Hérnia inguinal.","C":"Hidrocele comunicante.","D":"Torção testicular.","E":"Cisto de cordão."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-8859","number":"8859","sourceNumber":"8859","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um jovem de 15 anos de idade apresenta um quadro de dor testicular há 4 horas. Ao\nexame apresenta edema, muita dor ao exame sem\nreflexo cremasteriano e sem alívio da dor à\nelevação do testículo. Assinale a melhor conduta.","options":{"A":"Analgesia, compressas, repouso e retorno ambulatoial após ultrassom com Doppler.","B":"Analgesia, compressas, repouso e retorno ambulatorial após cintilografia testicular.","C":"Exploração cirúrgica imediata.","D":"Se houver suspeita de torção testicular intravaginal não se deve tentar rotação externa do\ntestículo.","E":"Analgesia, compressas, repouso e antibiótico profilático."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-322131","number":"322131","sourceNumber":"322131","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente de 24 anos, com IMC de 32 kg/m² e sem comorbidades, procura um\nmédico cirurgião com o desejo de realizar\ncirurgia bariátrica. Refere que já procurou outros\ncirurgiões que não quiseram realizar o procedimento. Qual seria a melhor conduta do médico diante\ndessa situação?","options":{"A":"Indicar a cirurgia bariátrica, já que a paciente possui critérios para realizar o procedimento,\napós\nrealização de pré-operatório completo.","B":"Orientar a paciente que ela não possui critérios para indicação da cirurgia e que deve iniciar\nmedidas clínicas para a perda de peso.","C":"Orientar a paciente que ela deve realizar exames laboratoriais e que, se estes revelarem que ela\né portadora de diabetes, terá indicação de realizar a cirurgia.","D":"Orientar a paciente sobre os riscos da cirurgia e que esta deve ser indicada somente para\npacientes com IMC maior que 45 kg/m².","E":"Orientar a paciente que ela não possui critérios para indicação da cirurgia, porém, caso a\npaciente insista em seu desejo, o médico deve\nrealizar o procedimento, respeitando a vontade dela."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-337510","number":"337510","sourceNumber":"337510","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Uma das principais causas de sangramento anorretal são as\nhemorroidas e as fissuras anais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-322171","number":"322171","sourceNumber":"322171","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 5 anos, assintomático, está em consulta de puericultura. Ao exame\nfísico, é identificado um linfonodo supraclavicular palpável. Nesse caso, está indicada a biópsia\ndesse linfonodo?","options":{"A":"Não, pois o paciente deve ser revisado em duas semanas para avaliar se houve regressão.","B":"Não, pois o paciente é assintomático.","C":"Sim, independentemente das características do linfonodo.","D":"Sim, se o linfonodo for firmemente aderido e maior que 2 cm.","E":"Sim, se o linfonodo for maior que 1 cm."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-305275","number":"305275","sourceNumber":"305275","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente com IMC> 35 kg/m2, hipertenso, diabético e etilista é atendido para\navaliação de indicação de cirurgia bariátrica, já com pré-operatório pronto. Assinale a alternativa\nque apresenta a melhor atitude médica a ser tomada durante a consulta nesse caso.","options":{"A":"Agendar a cirurgia imediatamente, já que o paciente possui comorbidades agravadas pela\nobesidade, incluindo a dependência do álcool.","B":"Orientar o paciente a cessar o etilismo, procurar acompanhamento psicológico e retornar para\nreavaliação sobre a indicação da cirurgia se estiver psicologicamente estável após cessação do\nvício.","C":"Orientar o paciente sobre os riscos e as sequelas da cirurgia, questionar sobre sua motivação,\navaliar se já houve falha da terapia\nnutricional e agendar a cirurgia.","D":"Orientar que o paciente não tem indicação de cirurgia devido ao seu IMC abaixo do critério para\nindicação de cirurgia e devido ao etilismo.","E":"Agendar a cirurgia para uma data após 2 meses, orientando o paciente sobre os riscos e as\ncomplicações da cirurgia e a cessar o etilismo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-305309","number":"305309","sourceNumber":"305309","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação ao nefroblastoma (tumor de Wilms), é CORRETO afirmar que:","options":{"A":"Tem seu pico de incidência em crianças maiores de 5 anos.","B":"É mais agressivo na presença de anaplasia, mesmo quando focal e em tumores localizados\n(estádios I e II).","C":"Manifesta-se mais comumente como massa abdominal muito dolorosa, acompanhada de\nhematúria macroscópica.","D":"Exige, para seu diagnóstico, a realização de biópsia percutânea nos casos suspeitos de idade\ncompatível.","E":"É o tumor sólido mais comum no recém-nascido."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-298893","number":"298893","sourceNumber":"298893","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 2 anos e 3 meses de idade foi levado ao ambulatório de pediatria pela\nmãe, pois ela está preocupada com um \"caroço\" no pescoço do filho, que ela notou há cinco\nmeses. Relatou que o filho é bastante ativo, que se alimenta bem, sempre ganhou peso, mas fala\npouco e palavras difíceis de compreender. Ademais, há muito tempo apareceram alguns\nmachucados no couro cabeludo dele, que o menino coça bastante e tem algumas crostas. Ao\nexame físico, constataram-se altura = 90 cm (escore z 0), peso = 12,300 kg (escore z entre 0 e -2),\nFC = 120 bpm, FR = 26 irpm e SatO2 = 97% em AA. No couro cabeludo, há várias lesões com\ncrostas melicéricas e presença de linfonodo retroauricular medindo 1,5 cm, móvel, fibroelástico,\nindolor à palpação. Observaram-se oroscopia, dentes em bom estado, sem lesões, sem frênulo\nlingual, otoscopia, com membrana timpânica translúcida, sem abaulamentos ou retrações e\nausculta cardíaca, BNF, RR, 2t, sem sopro. Verificaram-se, ainda, ausculta pulmonar, MVUD, sem\nRA, abdome, RHA+, depressível, sem megalias, indolor à palpação e genitália com testículos em\nbolsa escrotal e fimose. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Sempre se deve solicitar USG para descartar malignidade de linfonodos\nmaiores de 1 cm.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-274354","number":"274354","sourceNumber":"274354","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"As hemorroidas são causa de sangramento anal e desconforto para muitos pacientes.\nSobre essa patologia, assinale a alternativa\nCORRETA.","options":{"A":"As hemorroidas internas geralmente causam dor e sangramento anal frequentes.","B":"As hemorroidas normalmente são classificadas em internas, médias e externas.","C":"Hemorroidas com prolapso que precisa ser reduzido digitalmente são classificadas como de\nterceiro grau.","D":"O tratamento clínico mais eficaz das hemorroidas se baseia, principalmente, em vasodilatadores.","E":"Hemorroidas de primeiro grau, em sua maioria, precisam ser tratadas com hemorroidectomia\ncirúrgica."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-274371","number":"274371","sourceNumber":"274371","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 70 anos, hipertenso, diabético e obeso, dá entrada no pronto\natendimento com quadro de dor torácica de\ninício súbito há cerca de 2 horas, de forte intensidade,\ncom irradiação para região dorsal. Na admissão, está com PA: 200/110, FC: 95 bpm, FR: 16 irpm,\nSO2: 95%, com ausculta cardíaca mostrando sopro aórtico sistólico +++/IV, pulsos periféricos\nassimétricos, finos e palidez cutânea com pele fria. Foi realizada tomografia da aorta com contraste\ncom diagnóstico de dissecção aguda de aorta. Sobre esse quadro, assinale a alternativa\nCORRETA.","options":{"A":"O controle da dor do paciente deve ser feito com anti-inflamatório não esteroidal, como\ndipirona.","B":"O uso de nitroprussiato de sódio deve ser iniciado imediatamente para controle pressórico em\nmonoterapia.","C":"Deve-se iniciar anticoagulação do paciente.","D":"Deve-se ter como alvo o betabloqueio efetivo do paciente, com a FC oscilando entre 60 e 75.","E":"O tratamento inicial deve ser com administração de betabloqueadores por via endovenosa,\nvisando diminuir a frequência cardíaca e a\npressão arterial."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-274372","number":"274372","sourceNumber":"274372","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Referente às estatinas, é correto afirmar que","options":{"A":"reduzem a taxa de crescimento de aneurisma de aorta abdominal.","B":"devem ser suspensas em pacientes com insuficiência renal aguda.","C":"a síndrome muscular relacionada à estatina ocorre em até 2% dos pacientes e o diagnóstico é\nclínico, com a elevação da creatinofosfoquinase no máximo em até 7 vezes o limite superior da\nnormalidade.","D":"a terapia com estatina continua como terapia primária para prevenção cardiovascular, apesar de\nnão ter efeito sobre redução de toda linha\nde lipídios, como os triglicerídeos.","E":"a elevação das transaminases após 4 semanas do início da terapia é uma contraindicação ao\nseu uso."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-274380","number":"274380","sourceNumber":"274380","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 6 meses é levado à consulta de puericultura. Apresenta bom ganho de\npeso e desenvolvimento normal, em\naleitamento exclusivo e com vacinação atualizada. Ao\nexaminar o paciente, o pediatra nota que o seu testículo esquerdo não está na bolsa testicular.\nAssinale a alternativa correta em relação ao caso clínico.","options":{"A":"Se ao examinar o pediatra conseguir localizar e levar o testículo até a bolsa testicular, não se\npode dizer que o paciente tem criptorquidia,\nmesmo que o testículo não permaneça ali.","B":"Com o exame físico detalhado, o pediatra pode afirmar que se trata de anorquia.","C":"A criptorquidia não está associada à morbidade para o paciente.","D":"Essa condição é mais comum em prematuros e, na maioria, os testículos se posicionarão de\nmaneira correta no primeiro ano de vida.","E":"A hérnia inguinal está presente na maioria dos casos unilaterais, mas não ocorre nos casos\nbilaterais."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-255684","number":"255684","sourceNumber":"255684","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Determinado paciente de 35 anos de idade com diabetes tipo II incontrolável, com\nvários esquemas de terapia, IMC de 33 Kg/m²,\nproveniente do Japão, foi submetido a uma cirurgia\nbariátrica, pela técnica by-pass gástrico em Y de Roux. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. A técnica em Y de Roux vem sendo\npouco utilizada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-255686","number":"255686","sourceNumber":"255686","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Determinado paciente de 35 anos de idade com diabetes tipo II incontrolável, com\nvários esquemas de terapia, IMC de 33 Kg/m²,\nproveniente do Japão, foi submetido a uma cirurgia\nbariátrica, pela técnica by-pass gástrico em Y de Roux. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Nessa técnica, a presença precoce do\nalimento no delgado leva a uma maior produção de GLP-1.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-255687","number":"255687","sourceNumber":"255687","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Determinado paciente de 35 anos de idade com diabetes tipo II incontrolável, com\nvários esquemas de terapia, IMC de 33 Kg/m²,\nproveniente do Japão, foi submetido a uma cirurgia\nbariátrica, pela técnica by-pass gástrico em Y de Roux. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Não há dados na literatura relatando que\nquaisquer cirurgias para perda de peso possam levar à perda sustentada de peso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-250104","number":"250104","sourceNumber":"250104","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um exame físico completo deve ser realizado na primeira consulta de puericultura.\nConsiderando essa informação, julgue o item a\nseguir. Uma situação comum é a de os testículos\nnão serem palpáveis na bolsa escrotal na primeira consulta do recém-nascido, pois, na maioria das\nvezes, os testículos \"descem\" até os três meses de vida, mas, se, aos seis meses de vida, não\nforem apalpados, deve-se encaminhar o recém-nascido para melhor avaliação e tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-196680","number":"196680","sourceNumber":"196680","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mulher de 35 anos de idade, com diabetes melittus e hipertensão arterial sistêmica, em\ntratamento, apresenta peso corporal de 200 kg e altura de 1,50 m. O médico indicou cirurgia\nbariátrica, tendo como técnica a gastrectomia vertical (sleeve). Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Nessa técnica, há importante perda de\nvitamina B12 e ferro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-214418","number":"214418","sourceNumber":"214418","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente de 32 anos de idade, obesa (IMC 38 Kg/m²), diabética tipo II e em uso de\nhipoglicemiante oral, em tratamento de transtorno depressivo maior (bem controlado), comparece\nao consultório médico demonstrando interesse em realizar cirurgia bariátrica para emagrecer, pois\ngostaria de reduzir o peso por questões estéticas. A respeito desse caso clínico e da cirurgia\nbariátrica, e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\nestabilização dos níveis de glicemia e a redução do apetite nessa paciente, se submetida a bypass\ngástrico com Y de Roux, decorrerão do aumento do glucagon-like peptide-1 (GLP-1).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-211961","number":"211961","sourceNumber":"211961","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 72 anos de idade realizou TC de abdome total para estadiamento de\ncâncer colorretal e teve achado casual de\naneurisma de aorta abdominal de 7 cm de diâmetro, com\n5 cm de colo em relação à emergência das artérias renais e 12 cm de comprimento. Quanto a esse\ncaso clínico e aos conhecimentos médicos correlatos, a respeito dos aneurismas de aorta, assinale\na alternativa correta.","options":{"A":"A reparação cirúrgica do aneurisma de aorta é igual para todos os indivíduos, com relação ao\ntamanho e à extensão da prótese, seja ela endovascular ou não, não necessitando de um plano\nparticular para cada paciente.","B":"O paciente do caso descrito não tem indicação cirúrgica, pois apresenta um aneurisma < 7,5 cm\ne é do sexo masculino.","C":"A síndrome de Marfan não constitui um fator de risco para o desenvolvimento de aneurismas de\naorta torácica.","D":"A progressão natural de um aneurisma aórtico é manter-se estável, mesmo em pacientes com\nhistórico de hipertensão primária mal-controlada.","E":"A dissecção aórtica proximal é um transtorno ameaçador da vida; por isso, necessita de\nreparação cirúrgica imediata."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-196624","number":"196624","sourceNumber":"196624","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente submetido a cirurgia bariátrica para tratamento de obesidade, com técnica de\nderivação gástrica em Y de Roux há seis anos, refere ter ficado sem convênio nos últimos três\nanos, não tendo mantido seguimento clínico ou nutrólógico nesse período. Manteve-se consumindo\nsuplemento alimentar (polivitamínico/mineral) por via oral, prescrito pela equipe médica na ocasião\nda cirurgia. Queixa-se de fraqueza, desequilíbrios e parestesia de extremidades. Apresenta\nhemograma com hemoglobina de 9mg/dL, com VCM e RDW aumentados. Com base nesse caso\nclínico e nos conhecimentos médicos a respeito de cirurgia bariátrica, julgue o item a seguir. O uso\nde acarbose como parte do tratamento do dumping pós-bariátrica pode ser vantajoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-179213","number":"179213","sourceNumber":"179213","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia bariátrica e metabólica, também conhecida como cirurgia da obesidade, ou,\npopularmente, como redução de estômago, reúne técnicas com respaldo científico destinadas ao\ntratamento da obesidade e das doenças associadas ao excesso de gordura corporal ou agravadas\npor ele. Considerando o texto acima, assinale a alternativa que apresenta uma contraindicação\nabsoluta à realização da cirurgia bariátrica.","options":{"A":"Síndrome de Prader-Willi.","B":"Diabetes.","C":"Idade menor que 21 anos.","D":"Idade maior que 65 anos.","E":"Hipertensão arterial sistêmica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-177637","number":"177637","sourceNumber":"177637","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir. O\nnefroblastoma, ao contrário do neuroblastoma, costuma atravessar a linha média do abdômen.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-152059","number":"152059","sourceNumber":"152059","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. Se a dissecção aórtica na\nfase aguda, mencionada no caso clínico, é de diagnóstico inferior a 30 dias, é invariável a conduta\ncirúrgica no tipo B da classificação de Stanford.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-152065","number":"152065","sourceNumber":"152065","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. Para esse paciente, o\ncálculo do ITB é realizado pela relação da maior pressão arterial sistólica da artéria tibial\nposterior e\nda artéria dorsal do pé (com obtenção nos dois membros ou em apenas um, dependendo da\ncasualidade) com a maior pressão sistólica das artérias braquiais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-154345","number":"154345","sourceNumber":"154345","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente, 2 meses de idade, é atendido em um hospital universitário com quadro de\ndesidratação secundária a vômitos volumosos em repetição e perda de peso. A mãe refere que os\nvômitos surgiram há um mês e sempre são de conteúdo alimentar e após alimentação, sem outras\nqueixas. Ao exame físico, observa-se que o paciente está desidratado de hipoativo e apresenta\npequena massa palpável (oliva) no epigástrio. A respeito desse quadro, a hipótese diagnóstica\nmais provável é de:","options":{"A":"Estenose Hipertrófica do Piloro (EHP).","B":"Pâncreas anular.","C":"Refluxo Gastroesofágico (RGE) Fisiológico.","D":"Atresia duodenal.","E":"Gastroenterite infecciosa."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-154341","number":"154341","sourceNumber":"154341","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente T. A. G., 55 anos de idade. tabagista, hipertenso, chega ao pronto-socorro\napresentando dor torácica com irradiação para\no dorso, além de dissociação de pulsos de 30\nmmHg entre membros superiores. O exame físico revela FC = 112 bpm; PA = 176 mmHg x 100\nmmHg; SatO? = 96%. Considerando o quadro apresentado, assinale a alternativa que indica a\nmelhor conduta a ser adotada.","options":{"A":"Tomografia computadorizada e controle pressórico.","B":"Arteriografia com cirurgia imediata.","C":"Eletrocardiograma com protocolo MONAB.","D":"Radiografia de tórax e antibioticoterapia.","E":"Cintilografia e analgesia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-131845","number":"131845","sourceNumber":"131845","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Acerca do prolapso retal, assinale a alternativa correta.","options":{"A":"Essa doença é mais comum em homens.","B":"O prolapso retal é doença de mulheres jovens virgens.","C":"A obstrução intestinal por volvo é uma complicação muito frequente dessa afecção em 90% dos\ncasos.","D":"O tratamento inicial é sempre clínico.","E":"Entre os procedimentos cirúrgicos realizados, podem-se indicar: cirurgia de Delorme, cirurgia de\nAltemeier ou sacropromontofixação por via laparoscópica."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-64713","number":"64713","sourceNumber":"64713","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma mulher de 30 anos procura o pronto-socorro por estar sentindo dor intensa e\nespasmos esfincterianos precipitados por\nevacuações há mais de 2 (dois) meses. Ela, ainda,\nmenciona manchas de sangue no papel higiênico e fezes com raias de sangue, ocasionalmente. Ao\nexame físico, observa-se ulceração em comissura posterior, plicoma anal e papila hipertrofiada.\n\nDeste modo, assinale a alternativa que apresenta o diagnóstico mais provável para o caso descrito\nacima.","options":{"A":"Abscesso Anorretal.","B":"Fissura Anal Crônica.","C":"Doença Hemorroidária de 4º grau.","D":"Fístula Anorretal.","E":"Cisto Pilonidal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-49144","number":"49144","sourceNumber":"49144","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A respeito de afecções que podem acometer a região anorretal, julgue o item seguinte.\nA terapia neoadjuvante que combina radioterapia\npré-operatória com ressecção abdominoperineal\ndo reto e canal anal seguida de quimioterapia com 5-fluorouracil e mitomicina C é o tratamento de\nescolha para a maioria dos pacientes portadores de carcinoma epidermoide do canal anal\nlocalmente avançado.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-52637","number":"52637","sourceNumber":"52637","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Julgue o item a seguir relativo a emergências cardiovasculares. \"Dissecções agudas da\naorta com envolvimento da aorta ascendente são consideradas emergências cirúrgicas devido ao\nelevado risco de ruptura aórtica, de tamponamento cardíaco, de insuficiência aórtica aguda e grave\ne de acidente vascular encefálico.\"","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-32153","number":"32153","sourceNumber":"32153","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma criança de seis semanas de idade foi levada ao pronto-socorro pela mãe,\npreocupada com o seu filho, que, após se\nalimentar, apresentava vômitos severos, não biliosos.\nNos intervalos dos episódios de vômitos, a criança se alimentava avidamente. Ao exame, a criança\nencontrava-se desidratada e subnutrida, com movimentos peristálticos no andar superior do\nabdome. Nesse caso, o diagnóstico é:","options":{"A":"Atresia intestinal.","B":"Estenose hipertrófica do piloro.","C":"Refluxo gastroesofágico exacerbado.","D":"Má rotação intestinal.","E":"Intussuscepção."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-334871","number":"334871","sourceNumber":"334871","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 16 anos de idade compareceu ao pronto-socorro com queixa de dor\nsúbita e intensa em região escrotal à direita, associada a náuseas e a vômitos, que persiste há\nquatro horas. Ao exame físico, o escroto encontra-se edemaciado, endurecido e eritematoso, e o\ntestículo direito está sensível, inchado e ligeiramente elevado. Com base nesse caso clínico,\nassinale a alternativa correta.","options":{"A":"Exames de imagem são essenciais para definir a conduta desse caso.","B":"As causas mais comuns de dor escrotal aguda em adolescentes incluem torção testicular, torção\ndo apêndice testicular e epididimite.","C":"O quadro pode ser compatível com torção testicular intermitente.","D":"O tratamento para um testículo torcido que permanece viável envolve orquiectomia.","E":"Não há necessidade de exploração do hemiescroto contralateral em casos de torção de\ntestículo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-343444","number":"343444","sourceNumber":"343444","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, 68 anos, foi levado por familiares ao serviço de emergência médica,\napresentando mal-estar e dor abdominal difusa, de\ninício súbito há cerca de 30 minutos. PA: 90 x\n60 mmHg, FC: 115 bpm. Ao exame, observa-se massa pulsátil em região de mesogastro. Paciente\ncom histórico de angioplastia com Stent, hipertensão e tabagismo há 35 anos, 40 cigarros/dia. O\ndiagnóstico e conduta, neste caso, são:","options":{"A":"Dissecção de aorta tipo A de Stanford. Iniciar betabloqueador, solicitar raio x de tórax para\nconfirmar alargamento do mediastino.","B":"Isquemia mesentérica. Analgesia com morfina e anticoagulação com heparina.","C":"Aneurisma de aorta abdominal roto. Ultrassom à beira do leito e avaliação urgente do cirurgião.","D":"Aneurisma de aorta abdominal roto. Tomografia computadorizada sem contraste e avaliação\nurgente do cirurgião."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-268885","number":"268885","sourceNumber":"268885","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente de 35 anos de idade, diabético, procura atendimento no ambulatório de\ncirurgia bariátrica. Atualmente, pesa 150 kg e mede 180 cm de altura. É hipertenso e tabagista.\nCom base nesse caso clínico e nos conhecimentos médicos relacionados à cirurgia bariátrica,\nassinale a alternativa correta.","options":{"A":"O paciente deve ser encaminhado para nutricionista e endocrinologista, já que não tem\nindicação para cirurgia bariátrica por causa de seu índice de massa corporal (IMC)","B":"O paciente necessita, para ser elegível para a cirurgia, apresentar falha na terapia dietética,\nestabilidade psiquiátrica, atitude motivada e conhecimento acerca da cirurgia e de suas\nconsequências, além de estar na faixa de IMC adequada.","C":"Um paciente acima de 200 kg não apresenta risco aumentado de mortalidade em comparação\naos demais.","D":"A técnica laparoscópica e a aberta apresentam os mesmos índices de mortalidade.","E":"Apenas pacientes com IMC acima de 35 kg/m2, associado à diabetes mellitus e (ou) à\nhipertensão arterial sistêmica, têm indicação cirúrgica."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-263345","number":"263345","sourceNumber":"263345","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente com 54 anos de idade procurou a Unidade Básica de Saúde para\natendimento. O homem relatou que, há um ano,\napresentou abscesso na região perineal que foi\ndrenado em pronto-socorro. Desde então, apresentou uma ferida próxima ao ânus, que\nocasionalmente inflama e apresenta saída de secreção turva, com odor fecaloide. O paciente\nrealizou colonoscopia há 3 anos, a qual não evidenciou lesões no cólon. O exame da região\nperianal evidenciou orifício cutâneo a 2 cm da borda anal, na região anterior direita do períneo. O\ntoque retal evidenciou próstata com características normais e indução anteriormente à borda anal.\nApós a compressão local, houve saída de secreção pelo orifício cutâneo. Com base na história\nclínica e nos dados do exame físico, o diagnóstico e a conduta adequada são","options":{"A":"abscesso perianal e drenagem cirúrgica.","B":"fissura anal aguda e uso de anti-inflamatórios tópicos.","C":"fístula perianal e encaminhamento para tratamento cirúrgico eletivo.","D":"fissura anal crônica e encaminhamento para tratamento cirúrgico eletivo."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-266416","number":"266416","sourceNumber":"266416","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma unidade básica\nde saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. O diagnóstico de doença hemorroidária é dado\nsomente com exame físico detalhado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-266417","number":"266417","sourceNumber":"266417","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma unidade básica\nde saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. A doença hemorroidária é a etiologia mais\ncomum dos sangramentos retais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291491","number":"291491","sourceNumber":"291491","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma criança de 6 anos que procura atendimento na Unidade Local de Saúde do seu\nbairro por apresentar, há cerca de 30\ndias, tumoração cervical na linha média, móvel à deglutição e\nindolor. A mãe refere que observou um crescimento progressivo da lesão, mas sem nenhum sinal\nflogístico desde o início do quadro. Referenciada para atendimento em um ambulatório de cirurgia\npediátrica, no momento do exame físico, a criança estava hígida sem nenhum outro achado a não\nser a tumoração na linha média do pescoço, acima da cartilagem cricoide, arredondada, móvel e de\nconsistência fibroelástica. Qual diagnóstico e conduta a serem adotados a seguir?","options":{"A":"Higroma cístico cervical ou linfangioma. Deve ser tratado com aspiração e injeção de bleomicina\nou OK 432 na lesão.","B":"Câncer primário de tireoide. Encaminhamento ao oncologista para mapeamento com medicina\nnuclear.","C":"Cisto do conduto tireoglosso. Ressecção cirúrgica englobando parte do osso hióde, que evita a\nrecidiva da doença.","D":"Cisto do 3.º arco branquial. Ressecção cirúrgica incluindo a secção do ramo clavicuar do\nmúsculo esternocleidomastoídeo."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-266448","number":"266448","sourceNumber":"266448","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Com relação aos achados de exames de imagem em paciente pediátrico, julgue o item\na seguir. Na radiografia simples de abdome de\num recém-nascido que vomita a presença do sinal\nda dupla bolha é sugestiva de estenose hipertrófica de piloro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-274645","number":"274645","sourceNumber":"274645","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A(s) causa(s) mais frequente(s) de hemorragia digestiva baixa em adultos menores de\n50 anos é/são:","options":{"A":"Doenças anorretais.","B":"Doença diverticular dos cólons.","C":"Isquemia mesentérica.","D":"Neoplasias."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-263402","number":"263402","sourceNumber":"263402","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um homem com 60 anos de idade comparece à Unidade Básica de Saúde para\natendimento, relatando que, ao realizar caminhadas, sente dor no membro inferior direito que o\nobriga a parar a cada 4 ou 5 quarteirões. Apresenta como fatores de risco à saúde ser tabagista,\ncom consumo de 20 maços-ano, obesidade, hipercolesterolemia, hipertensão arterial e diabete\nmelito, que afirma tratar de forma irregular. Traz um eco-Doppler arterial que evidencia estenose\nmoderada (entre 20 e 49%) do segmento aortoilíaco direito. Nesse caso, a conduta médica\nadequada é","options":{"A":"encaminhar ao pronto-socorro para avaliação urgente com especialista.","B":"orientar e tratar os fatores de risco e encaminhar para avaliação eletiva com especialista.","C":"orientar e tratar os fatores de risco, prescrever aspirina para prevenir doença tromboembólica\narterial.","D":"solicitar angiografia por tomografia ou ressonância magnética para descartar tromboangeíte\nobliterante de Buerger."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291527","number":"291527","sourceNumber":"291527","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um lactente masculino, com 5 semanas de vida, chegou no pronto-socorro com história\nde vômitos em jatos (sem bile) logo após as\nmamadas. A mãe relata que não está entendendo\nporque ele não está engordando. Nasceu com 3 500 g. Apesar dos vômitos, que tiveram início\npouco depois do nascimento, ele demonstrava muita fome e sugava \"com vontade\" o leite materno,\nmas desde ontem está hipoativo, quase não urina e a boca está seca. O exame apresentou os\nseguintes resultados: P = 3 600 g, sinal de prega presente, mucosa oral seca, hipoativo, perfusão\ncapilar em 4 segundos, massa semelhante a uma azeitona, discreta, firme, móvel, de 2 a 3 cm,\npalpável no fundo do lado direito do epigástrico. Sem outras anormalidades. Considerando os\ndiagnósticos do lactente, qual conduta médica deve ser adotada?","options":{"A":"Hidratação venosa e fazer US abdominal para esclarecer a suspeita diagnóstica de base que\nocasionou o quadro.","B":"Hidratar o paciente no domicílio e solicitar acompanhamento ambulatorial com pediatra.","C":"Usar antiemético, fazer hidratação venosa do paciente e encaminhar para acompanhamento\nambulatorial.","D":"Prescrever associação de fórmula para complementar o leite materno e fazer hidratação oral,\nplano B."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-263412","number":"263412","sourceNumber":"263412","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um lactente com 2 meses de idade é atendido na emergência, acompanhado pela mãe,\nque relata vômitos pós-grandiais desde os 15 dias de vida, com piora progressiva em frequência e\nintensidade. Ela conta que, após tais episódios eméticos, o lactente chora e parece ter fome.\n\nInforma, ainda, que seu filho nasceu a termo, com peso de 3 000 g e 49 cm de comprimento e que\nos testes de triagem neonatal foram normais.\nEla nega a ocorrência de doenças gestacionais e\nperinatais. Ao exame físico, o lactente apresenta-se emagrecido (peso = 3 200 g), ativo, acianótico,\nantictérico, desidratado (1+/4+) e corado, com abdome distendido, especialmente na região\nepigástrica, notando-se ausência de hepatoesplenomegalia e presença de ondas de Kussmaul\nobservadas após a alimentação. Os exames laboratoriais iniciais revelam pH = 7,5 (valor de\nreferência: 7,35 a 7,45); HCO? = 27 mEq/L (valor de referência: 23 a 28 mEq/L); Na = 135 mmol/L\n(valor de referência: 136 a 145 mmol/L); Cl = 95 mmol/L (valor de referência : 98 a 106 mmol/L) e K\n\n= 4,5 mmol/L (valor de referência: 3,5 a 5,5 mmol/L). Nesse caso, a conduta médica adequada é","options":{"A":"solicitar endoscopia digestiva alta e elevação da cabeceira do berço.","B":"solicitar ultrassonografia de abdome e piloromiotomia à Fredet-Ramstedt.","C":"investigar doenças metabólicas e administrar dieta hipoproteica e hipercalórica.","D":"prescrever expansão com soro fisiológico 0,9% e infusão de hidrocortisona 50 mg/m²\nsubcutânea/dia."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-263425","number":"263425","sourceNumber":"263425","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma lactente com 1 ano de idade foi levada à Unidade Básica de Saúde para\natendimento. A mãe relatou que a menina\napresentava uma tumoração na região inguinal direita\ndurante o banho, porém que tinha desaparecido no dia seguinte. Durante o exame físico, foi\nconfirmada uma nodulação na região inguinal direita, móvel, indolor, redutível e com\ntransiluminação negativa. Nesse caso, a suspeita diagnóstica e a conduta terapêutica corretas são","options":{"A":"adenomegalia inguinal e manter conduta expectante.","B":"hérnia inguinal e realizar tratamento operatório eletivo.","C":"hérnia inguinal e aguardar a regressão espontânea até os 5 anos de idade.","D":"cisto do canal de Nuck e aguardar a regressão espontânea até os 5 anos de idade."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291547","number":"291547","sourceNumber":"291547","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um lactente masculino, de 2 meses, é levado à emergência com história de vômitos\nnão biliosos que iniciaram com três semanas de\nvida e progressivamente pioraram. Há 2 dias,\npassou a vomitar após as mamadas e hoje o vômito está em jato. Ao exame físico, apresenta-se\nirritado, faminto, muito emagrecido; no epigástrio, foi observado onda peristáltica se deslocando da\nesquerda para direita e, após a criança vomitar, palpada à direita, também no epigástrio, massa\nfirme e móvel com cerca de 2 cm de diâmetro. Com base na principal hipótese diagnóstica, o\ndistúrbio ácido-básico que se espera encontrar nesse lactente é","options":{"A":"alcalose metabólica hipoclorêmica.","B":"acidose metabólica hiperclorêmica.","C":"acidose metabólica hipoclorêmica.","D":"alcalose metabólica hiperclorêmica."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291549","number":"291549","sourceNumber":"291549","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma mulher com 45 anos de idade foi atendida em unidade básica de saúde referindo\nque, há 4 meses, foi realizada drenagem de\nabscesso perianal em pronto-socorro e, desde então,\ntem apresentado saída ocasional de secreção fétida por lesão dérmica no local. O exame físico\nevidenciou orifício cutâneo com saída de secreção amarelada à compressão, localizado\nanteriormente e acerca de 2 cm da borda anal. Com base nos dados apresentados, determine a\nalternativa com a orientação da conduta a ser seguida.","options":{"A":"Encaminhar para nova drenagem em pronto-socorro.","B":"Encaminhar para avaliação eletiva, em ambulatório especializado.","C":"Prescrever antibiótico por via oral e pomada anestésica.","D":"Prescrever anti-inflamatório por via oral e pomada com antibiótico."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-244461","number":"244461","sourceNumber":"244461","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma criança de 5 meses de vida é encaminhada à emergência com quadro de dor\nabdominal em salvas, iniciado há seis horas. Durante o exame físico, a criança mostra-se ativa,\ncom sinais vitais estáveis e abdome depressível, por enquanto sem dor. A mãe mostra fralda com\npresença de sangramento vermelho vivo com grumos. Considerando esse caso clínico, no que se\nrefere ao provável diagnóstico e ao tratamento, assinale a alternativa correta.","options":{"A":"Pólipo juvenil: indica-se a ressecção por colonoscopia em razão do sangramento.","B":"Invaginação intestinal: indica-se cirurgia imediata em razão do sangramento.","C":"Intussuscepção: indicam-se início de antibioticoterapia, reidratação e enema opaco.","D":"Alergia a proteína do leite: indicam-se retirada de fórmula láctea e retirada de derivados de\nleite\nda dieta materna.","E":"Fissura anal: indica-se o uso de óleo mineral."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-230560","number":"230560","sourceNumber":"230560","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a incidência de volvo:","options":{"A":"A maioria dos casos ocorre em crianças com 12 anos de idade.","B":"A maioria dos casos ocorre em crianças com idade entre 5 e 10 anos.","C":"A maioria dos casos ocorre em crianças com idade entre 1 e 2 anos.","D":"A maioria dos casos ocorre no período neonatal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-230577","number":"230577","sourceNumber":"230577","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A idade ideal para a correção cirúrgica da criptorquidia é:","options":{"A":"Aos 3 anos de idade.","B":"Entre 2 anos e 3 anos de idade.","C":"Entre 6 meses e 1 ano de idade.","D":"Antes dos 6 meses de idade."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-230598","number":"230598","sourceNumber":"230598","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente do sexo masculino, 65 anos de idade, comparece ao ambulatório de\ncirurgia vascular encaminhado pelo médico da unidade básica de saúde após realizar uma\nultrassonografia de abdome de rotina sendo encontrado um aneurisma de aorta abdominal. No\nlaudo, o radiologista descreve o aneurisma como: ?fusiforme, abaixo das artérias renais, com\ndiâmetro máximo de 45 mm?. O paciente é assintomático, portador de hipertensão arterial\ncontrolada, em uso de captopril. Sobre o caso, assinale a CORRETA:","options":{"A":"Aneurismas fusiformes sempre devem ser abordados cirurgicamente, independente do diâmetro.","B":"No exame físico desse paciente, encontraremos o sinal de DeBakey positivo.","C":"Esse paciente deverá realizar acompanhamento para monitorização do diâmetro do aneurisma.","D":"O paciente deverá ser abordado cirurgicamente em regime de urgência."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-203035","number":"203035","sourceNumber":"203035","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Acerca dos defeitos no fechamento da parede abdominal, assinale a alternativa correta.","options":{"A":"Onfalocele: defeito lateral ao cordão umbilical, com presença de membrana de revestimento do\nconteúdo abdominal.","B":"Gastrosquise: defeito na linha média da parede abdominal, sem presença de membrana de\nrevestimento do conteúdo abdominal.","C":"Gastroquise: defeito lateral ao cordão umbilical com presença de membrana de revestimento do\nconteúdo abdominal.","D":"Onfalocele: defeito na linha média da parede abdominal, sem presença de membrana de\nrevestimento.","E":"Onfalocele: defeito na linha média da parede abdominal, com presença de membrana de\nrevestimento do conteúdo abdominal."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-206098","number":"206098","sourceNumber":"206098","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Crianças com idade inferior a 2 anos são as mais acometidas pela intussuscepção.\nConsiderando esse diagnóstico escolha a alternativa que contém a tríade clássica:","options":{"A":"Dor abdominal aguda, vômitos e fezes em forma de geleia de morango.","B":"Distensão abdominal, vômitos e diarreia.","C":"Irritabilidade, distensão abdominal e febre.","D":"Febre, dor abdominal aguda e diarreia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-206115","number":"206115","sourceNumber":"206115","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente feminino de onze meses apresenta irritabilidade não consolável de início\nsúbito há poucos minutos, não melhorando\ncom uso de analgésicos. O exame abdominal revela\nmassa palpável em flanco esquerdo e o ultrassom mostra imagem em alvo e pseudo-rim. A conduta\nmais CORRETA é:","options":{"A":"Tomografia de abdome.","B":"Cirurgia.","C":"Colonoscopia.","D":"Redução com enema baritado."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-177255","number":"177255","sourceNumber":"177255","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, com 16 anos de idade, procurou atendimento de urgência\nem função de intensa dor, edema e calor no\nsulco interglúteo. Ao exame físico, evidencia-se área\nde flutuação a 5 cm do ânus. O paciente nega febre e episódios anteriores semelhantes. Com base\nno caso clínico e nos conhecimentos médicos relacionados à doença pilonidal, assinale a\nalternativa correta.","options":{"A":"O cisto pilonidal raramente apresenta o trajeto fistuloso na direção cranial.","B":"A curetagem para remoção de pelos, tecidos de granulação e debris não altera a cicatrização da\nferida.","C":"A referida doença é caracterizada pela presença de uma cavidade subcutânea na região\nsacrococcígea que nunca cursa com drenagem de secreção.","D":"Para o tratamento definitivo da citada patologia, a abordagem mais comum é a excisão total do\ncisto e a ferida deixada aberta para fechamento por segunda intenção, o que pode levar, em média,\n21 semanas para a total cicatrização.","E":"Sudorese, higiene precária e obesidade são fatores que não estão relacionados com a infecção\ndo cisto sacrococcígeo."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-177234","number":"177234","sourceNumber":"177234","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente gestante apresentou oligodrâmnio durante toda a gestação, com\nepisódios mais intensos no terceiro trimestre de gravidez. Após o parto, deve-se investigar, em\nrelação ao recém-nascido, a possibilidade de","options":{"A":"prematuridade.","B":"polidactilia.","C":"anomalias gastrintestinais.","D":"sofrimento fetal.","E":"malformações renais."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-175121","number":"175121","sourceNumber":"175121","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A respeito das Fístulas Anorretais, assinale a alternativa INCORRETA:","options":{"A":"As fístulas interesfincterianas são o tipo mais comum.","B":"A Regra de Goodsall é útil para identificar a anatomia de fístulas complexas.","C":"A fístula transesfincteriana conecta o plano interesfincteriano com a fossa isquioretal por\nperfurar\no esfíncter externo.","D":"A maioria das fístulas deriva de uma infecção que se origina nas glândulas do canal anal, na\nlinha denteada."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-175123","number":"175123","sourceNumber":"175123","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Entre as cirurgias para obesidade, assinale a alternativa em que é classificada como\npuramente restritiva:","options":{"A":"Derivação gástrica em Y de Roux.","B":"Derivação Biliopancreática.","C":"Banda Gástrica Ajustável.","D":"Duodenal Switch."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-175124","number":"175124","sourceNumber":"175124","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Com relação à derivação gástrica em Y de Roux, assinale a alternativa INCORRETA:","options":{"A":"As taxas de mortalidade variam entre 0,3 a 1%.","B":"A estenose gastrojejunal é tratada na maior parte das vezes com reoperação.","C":"Encefalopatia de Wernicke pode se desenvolver em pacientes com vômitos pós-operatório\npersistentes.","D":"Embolia pulmonar é a complicação mais temida, e sua incidência pode exceder 1% nas\noperações abertas."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-154468","number":"154468","sourceNumber":"154468","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, sexagenário, tabagista e hipertenso, queixando-se de que há cerca de 1 ano\nvem apresentando dor progressiva em panturrilhas,\nprincipalmente à direita, desencadeada pela\ndeambulação. Relata que curiosamente a dor surge após andar 3 quarteirões de sua casa, em\nlugar plano, impedindo-o de prolongar suas caminhadas. À palpação durante o exame físico, os\npulsos femorais são presentes e os pulsos poplíteos, tibial posterior e pedioso ausentes no membro\nafetado. Ao realizar um ecodoppler arterial dos membros inferiores, nota-se que há em perna direita\noclusão da artéria femoral ao nível do canal dos adutores e redução do fluxo em artérias distais.\n\nQual a conduta médica a ser tomada neste cenário?","options":{"A":"Cessar tabagismo, iniciar antiagregantes plaquetários e estatinas e acompanhar\nambulatorialmente.","B":"Cessar tabagismo, iniciar anticoagulação sistêmica plena e acompanhar ambulatorialmente.","C":"Internação, analgesia potente, anticoagulação sistêmica plena e revascularização cirúrgica do\nmembro na mesma internação.","D":"Encaminhar para o ambulatório de pré-operatório para avaliação cardiovascular e programação\nde revascularização eletiva.","E":"Internação, analgesia com opióides e revascularização urgente do membro em menos de 24h."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159545","number":"159545","sourceNumber":"159545","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A respeito da dissecção aguda da aorta, afecção cardiovascular frequentemente\nassociada à hipertensão arterial sistêmica,\njulgue o item subequente. As complicações clínicas\nassociadas a essa moléstia aórtica incluem infarto do miocárdio, isquemia dos membros inferiores,\nacidente vascular cerebral, paraplegia, insuficiência renal aguda, infarto mesentérico,\ninsuficiência\naórtica, hemotórax e tamponamento cardíaco.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159554","number":"159554","sourceNumber":"159554","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A respeito da dissecção aguda da aorta, afecção cardiovascular frequentemente\nassociada à hipertensão arterial sistêmica,\njulgue o item subequente. No caso de pacientes jovens\ncom dissecção aguda da aorta deve-se iniciar o tratamento clínico com a redução imediata da\npressão arterial sistólica para valores não inferiores a 150 mmHg, por meio de agentes redutores da\npós-carga de trabalho do coração, associada à administração de fármacos de efeito inotrópico\npositivo. Essas ações farmacológicas combinadas reduzem a tensão de cisalhamento aórtico e, por\nconseguinte, ajudam na proteção vascular contra a ruptura aórtica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-168509","number":"168509","sourceNumber":"168509","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma mulher com 40 anos de idade é atendida em uma Unidade Básica de Saúde da\nFamília. A paciente relata constipação crônica e discreto sangramento ao defecar. Ao exame físico\nda região anal, identificou-se lesão não dolorosa à palpação, mostrada na imagem a seguir\n(Conforme imagem no caderno de questões); o toque retal não evidenciou alterações. Nesse caso,\nqual é a conduta adequada?","options":{"A":"Informar à paciente que se trata de uma lesão varicosa hemorroidária e encaminhá-la para o\nserviço secundário.","B":"Encaminhar a paciente para a retirada cirúrgica da lesão, devido ao risco de neoplasia, e marcar\nretorno para retirada de pontos.","C":"Informar à paciente que se trata de uma lesão varicosa hemorroidária e iniciar orientação\nterapêutica clínica e nutricional.","D":"Encaminhar a paciente para a realização da biópsia da lesão, informando-a sobre a\npossibilidade de tratar-se de uma neoplasia."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-159514","number":"159514","sourceNumber":"159514","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em um dia normal de trabalho, médicos de família e comunidade atendem a muitos\ncasos diferentes. Certa manhã, determinado\nmédico atendeu a quinze pacientes, entre os quais se\nencontravam os seguintes: (1) uma criança de cinco anos de idade com suspeita de abuso sexual,\ntrazida pela mãe; (2) um idoso de sessenta e seis anos de idade, tabagista, com diabetes melito\n(DM) e hipertensão arterial sistêmica (HAS); (3) uma mulher de vinte e três anos de idade,\nestudante universitária, que não tomava banho havia uma semana; (4) um bebê de uma semana de\nvida (5) e sua mãe, puérpera, para consulta normal; (6) um adolescente de dezessete anos de\nidade, com rolha de cera; (7) uma idosa de setenta e um anos de idade, com diabetes melito (DM)\ne obesa, com úlcera no membro inferior esquerdo, (8) e sua filha, e cuidadora, de quarenta e nove\nanos de idade, que não dormia regularmente havia um mês. Considerando esses casos clínicos,\njulgue o item a seguir. No exame da paciente 7, o médico deverá realizar o índice tornozelo braquial\n(ITB), que interfere no tratamento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-104761","number":"104761","sourceNumber":"104761","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Entre os acessos preferenciais para obtenção de acesso venoso profundo,\n\ndestacam-se as veias subclávias. A respeito da anatomia arterial e venosa dessa região, assinale a\nalternativa correta.","options":{"A":"A veia subclávia direita é formada pelas veias axilar e jugular interna direitas.","B":"A artéria subclávia direita origina-se diretamente do arco da aorta.","C":"A artéria carótida esquerda é ramo da artéria subclávia direita.","D":"A veia braquiocefálica esquerda é habitualmente mais longa que a direita.","E":"A veia braquiocefálica direita é formada pelas veias subclávia direita e ázigos."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-111348","number":"111348","sourceNumber":"111348","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O sinal da dupla bolha em Raio X simples de abdome de recém nascido com clínica de\noclusão intestinal alta sugere:","options":{"A":"Atresia de duodeno.","B":"Atresia de jejuno.","C":"Estenose hipertrófica de piloro.","D":"Múltiplas atresias de delgado.","E":"Atresia de via biliar."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-104773","number":"104773","sourceNumber":"104773","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Diversos processos infecciosos podem acometer a região anorretal. Acerca dessas\nafecções, assinale a alternativa CORRETA:","options":{"A":"A gangrena de Fournier ocorre quando há disseminação, na forma de microabscessos, para\nórgãos à distância, como o fígado e o pulmão.","B":"A principal causa de abscesso perianal é a doença inflamatória intestinal inespecífica.","C":"As fístulas extraesfincterianas de localização anterior devem ser tratadas por fistulotomia.","D":"Os abscessos geralmente estão relacionados com as doenças sexualmente transmissíveis,\nespecialmente a sífilis.","E":"A principal medida, no abscesso perianal, é a drenagem cirúrgica."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-111347","number":"111347","sourceNumber":"111347","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente submetida à cirurgia bariátrica, moradora de zona rural e sem\nacompanhamento ambulatorial nos últimos 12 meses\ne que nega uso de medicamentos dá entrada\nno pronto-socorro com história de cefaleia, irritabilidade e fadiga. Ao exame físico se observa\nnistagmo, marcha atáxica e oftalmoplegia. O que está ocorrendo com a paciente?","options":{"A":"Tumor cerebral.","B":"AVC isquêmico.","C":"Deficiência de vitamina B1.","D":"Meningoencefalite.","E":"Intoxicação por organofosforado."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-97736","number":"97736","sourceNumber":"97736","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um paciente com 18 anos de idade deu entrada no Pronto-Socorro com quadro de dor\nescrotal aguda, iniciada há quatro horas, de início súbito, não havendo história de trauma local. Ao\nexame físico específico, apresentava edema escrotal, associado à hiperemia e dor à palpação do\ntestículo direito. A dor não foi aliviada com a elevação do testículo. O reflexo cremastérico estava\nausente. Assinale a alternativa que apresenta o diagnóstico e a conduta corretos.","options":{"A":"Torção de cordão espermático; cintilografia escrotal com tecnécio.","B":"Torção de cordão espermático; ultrassonografia com doppler.","C":"Orquiepididimite; sumário de urina com sedimentoscopia.","D":"Orquiepididimite; pesquisa de Clamídia na urina."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-97784","number":"97784","sourceNumber":"97784","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um pré-escolar do sexo masculino, com quatro anos de idade, apresentou massa\npalpável em mesogástrio esquerdo durante exame médico de rotina. A mãe nega história de dor\nabdominal, febre, constipação, porém refere que há quatro meses a criança vem apresentando\ndistensão abdominal e urina escura. O diagnóstico dessa criança é:","options":{"A":"tumor de Wilms.","B":"glomerulonefrite.","C":"infecção urinária.","D":"parasitose intestinal."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-75528","number":"75528","sourceNumber":"75528","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança do sexo masculino, com 7 meses de idade, começou a apresentar crises de\nchoro injustificado intercaladas com períodos de acalmia. Tem leve distensão abdominal,\nprincipalmente em quadrante superior direito, e vômitos de conteúdo alimentar há cerca de dois\ndias. Hoje pela manhã, a mãe notou fezes contendo substância gelatinosa e de cor\n\nróseo-avermelhada, o que a motivou a procurar serviço de Pronto Atendimento. Ao exame, a\ncriança se apresenta inquieta e chorosa, os\nruídos abdominais estão presentes, levemente\naumentados e com timbre metálico. Na palpação abdominal, evidencia-se uma tumoração fusiforme\nem hipocôndrio direito, sem sinais de irritação peritonial. Com base nessas informações, pode-se\nafirmar que, na investigação por imagem:","options":{"A":"a presença de sangue nas fezes contraindica o enema baritado.","B":"a radiografia simples de abdome deve mostrar uma\nimagem de dupla bolha.","C":"a tomografia computadorizada é superior ao enema baritado no acompanhamento da redução\nhidrostática.","D":"a ultrassonografia de abdome deve mostrar imagens em \"alvo\" e \"pseudo-rim\" no quadrante\nsuperior direito.","E":"a ultrassonografia de abdome deve mostrar imagem de espessamento (hipertrofia) da camada\nmuscular do piloro em epigástrio."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-75545","number":"75545","sourceNumber":"75545","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mulher com 64 anos de idade, com antecedentes de hipertensão arterial há cerca de 20\nanos e tabagista (30 maços-ano), em uso\nde enalapril - 20 mg de 12/12h, foi trazida à Emergência\nde um hospital terciário com quadro de dor lombar de forte intensidade e início súbito, sem\nirradiação, que foi acompanhada por síncope, sem pródromos, iniciada há duas horas. Na\nadmissão hospitalar estava consciente, orientada, anictérica, com palidez cutaneomucosa.\n\nTemperatura axilar = 36°C, pressão arterial = 70 x 45 mmHg, frequência cardíaca = 118 bpm,\nfrequência respiratória = 18 irpm. Os exames do\naparelho cardiovascular e pulmonar não\ndemonstraram alterações. O abdome apresentava equimoses em ambos os flancos, e era\nlevemente doloroso à palpação em mesogástrio e hipogástrio, com massa pulsátil em região do\nmesogástrio. Ruídos hidroaéreos presentes. Nos membros inferiores havia redução da temperatura\ndistalmente e bilateralmente e redução da amplitude de todos os pulsos. Os exames laboratoriais\niniciais revelaram: Leucócitos = 12.000/mm³ (segmentados = 74%, Hemoglobina = 12,1 g/dl;\nHematócrito = 36,3%; Plaquetas = 231.000/mm³; Glicemia = 84 mg/dl (VR = 80- /dl); Ureia = 45\nmg/dl (VR = 20-35 mg/dl); Creatinina = 1,2 mg/dl (VR = 0,8-1,4 mg/dl); Amilase = 352 U/L (VR =\n\n4-400 U/L); TGO = 26 U/L (VR < 35 U/L) e TGP = 31 U/L (VR < 35 U/L). Considerando a condição\nclínica atual da paciente, o exame a ser realizado para confirmação diagnóstica é:","options":{"A":"ultrassonografia abdominal.","B":"lavado peritoneal com solução salina.","C":"angiorressonância magnética do abdome.","D":"tomografia computadorizada do abdome.","E":"angiografia aórtica e de membros inferiores."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137576","number":"137576","sourceNumber":"137576","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um pediatra de plantão em uma maternidade de nível secundário é chamado para\nassistir o nascimento de um recém-nascido a\ntermo, com 39 semanas de idade gestacional. O\nobstetra da equipe comunica que a gestante está na admissão em início de trabalho de parto (com\n3 cm de dilatação) e com uma avaliação ultrassonográfica gestacional que evidencia hérnia\ndiafragmática. A bolsa amniótica ainda está íntegra. Qual a conduta recomendada no caso?","options":{"A":"Contatar imediatamente a equipe de cirurgia pediátrica para\n\nque o recém-nascido seja encaminhado ao bloco cirúrgico de outro hospital tão logo ocorra o\nnascimento","B":"Transferir a gestante para um centro terciário por se tratar\n\nde uma unidade secundária sem UTI neonatal, pois pressupõese\na necessidade de ventilação mecânica.","C":"Preparar o material de intubação na sala de parto, por se tratar de uma patologia cirúrgica\ngrave,\ngerando prejuízo da\n\nventilação, não sendo indicada a ventilação com máscara após o\nnascimento.","D":"Preparar o material para a cirurgia imediata do recém-nascido\nna maternidade secundária, pois não haverá tempo\n\nhábil para transferência para um hospital de nível terciário.","E":"Conversar com o obstetra e avisar que não poderá atender\n\no bebê em maternidade de nível secundário e que, por esse motivo, não irá comparecer à sala de\nparto."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137602","number":"137602","sourceNumber":"137602","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente, 45 anos de idade, quatro partos normais, apresenta constipação\nintestinal crônica, com grande esforço\nevacuatório, às vezes com discreto sangramento, visível\napós a higienização com papel. Há três dias apresenta aumento de nodulações perianais,\nsangramento em maior quantidade do que o habitual (suja o vaso com sangue), acompanhado de\ndor anal às evacuações. Ao exame, apresenta exteriorização de mamilos hemorroidários, com\nedema importante em todos, além de extrusão de coágulo e pequena ulceração em um\ndeles. Ao ser preenchida a ficha de referência para um serviço de Proctologia para essa\npaciente, qual dos seguintes CID devem ser registrados?","options":{"A":"I84.1 - Hemorroidas internas com outras complicações.","B":"I84.2 - Hemorroidas internas sem complicações.","C":"I84.6 - Plicomas hemorroidários residuais.","D":"I84.7 - Hemorroidas trombosadas não especificadas.","E":"I 84. 8- Hemorroidas não especificadas com outras complicações."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137698","number":"137698","sourceNumber":"137698","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um lactente de 1 ano de idade é levado ao ambulatório com história de ausência de um\ndos testículos. A mãe refere ausência de\nvômitos, dor abdominal ou febre. Ao exame físico: criança\nem bom estado geral, risonha, ativa. O exame da região inguinoescrotal revela ausência de\nhiperemia e dor locais, com testículo esquerdo tópico e sem alterações, e hemiescroto direito vazio.\nNão foi possível palpar o testículo direito. Diante desse quadro, a conduta mais adequada é","options":{"A":"indicar correção cirúrgica ou terapia com gonadotrofina coriônica humana (HCG) antes do\nsegundo ano de vida","B":"observar até completar 4 anos de idade. Se persistir o quadro, indicar cirurgia.","C":"iniciar terapia com HCG após 5 anos, se persistir o quadro.","D":"indicar cirurgia se, no início da puberdade, ainda não tenha ocorrido sua descida espontânea.","E":"aguardar até a puberdade, quando ocorrerá sua descida espontânea para a bolsa escrotal, pela\nação dos hormônios masculinos."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-138606","number":"138606","sourceNumber":"138606","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, com 59 anos de idade, tabagista há mais de 10 anos,\nhipertenso e dislipidêmico, procura a\nUnidade Básica de Saúde relatando o aparecimento, há um\nmês, de lesão ulcerada em dorso de pé esquerdo, após pequeno trauma abrasivo com sandália\nmal-adaptada. A lesão é seca, dolorosa, com fundo sujo e pálido. Há um discreto halo de eritema\nao seu redor. Evolui há uma semana com piora do aspecto e do tamanho da lesão, com dor de\nrepouso, edema de pé e tornozelo. Os pulsos arteriais não são perceptíveis (palpáveis) abaixo dos\njoelhos, bilateralmente. Qual a hipótese diagnóstica e conduta para esse paciente?","options":{"A":"Doença aterosclerótica obliterante periférica(DAOP) com isquemia crítica; referenciar para\nrevascularização de urgência.","B":"Trombose venosa profunda; referenciar para consulta em ambulatório de especialidades e\nprescrição de anticoagulantes.","C":"Úlcera varicosa infectada; referenciar para internação hospitalar de urgência para\nantibioticoterapia e desbridamento.","D":"Trombose venosa profunda; referenciar para internamento hospitalar de urgência para\ntrombólise.","E":"Microangiopatia diabética; referenciar para ambulatório especializado."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-138742","number":"138742","sourceNumber":"138742","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um lactente, com nove meses de idade, foi levado ao Pronto Atendimento porque, há 5\nhoras vem apresentando choro inconsolável, vômitos, fezes com sangue e distensão abdominal. A\nmãe refere que a criança ficou gripada há uma semana. Durante o exame físico, o pediatra palpou\nmassa abdominal e solicitou radiografia simples de abdome que foi inespecífica e ultrassonografia\nde abdome total que mostrou anéis concêntricos de camadas hipoecóicas e hiperecóicas\nalternantes, com porção central hiperecóica (sinal da ?rosquinha/alvo/olho de boi?). Foi\nencaminhado ao centro cirúrgico para laparotomia. Baseado nos sintomas apresentados, o quadro\ndescrito é compatível com abdome agudo, tendo como causa","options":{"A":"volvo do intestino médio.","B":"hérnia inguinal estrangulada.","C":"divertículo de Meckel.","D":"intussuscepção intestinal.","E":"oclusão intestinal por Ascaris lumbricoides."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-351586","number":"351586","sourceNumber":"351586","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um menino de 6 anos de idade tem história de 6 dias de vômitos, agitação intermitente,\nperíodos em que fica inconsolável e perda\nde peso de 0,3 kg. Ao exame sua fontanela anterior se\nencontra achatada e suas membranas mucosas estão secas. O exame abdominal não demonstra\nnada digno de nota. Os dados laboratoriais são os seguintes: Na = 130; CI = 87; CO = 30. Uma\nultrassonografia do abdome revela piloro de 3,5mm x 12mm. É CORRETO afirmar que a próxima\nprovidência mais apropriada no tratamento dessa criança é:","options":{"A":"Uma piloromiotomia.","B":"O monitoramento do pH esofágico.","C":"Iniciar a terapia por inibidores da bomba de prótons.","D":"Iniciar a reposição líquida intravenosa."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-351593","number":"351593","sourceNumber":"351593","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre os fatores predisponentes relacionados ao desenvolvimento de abscessos anais,\nassinale V para as afirmativas verdadeiras e F para as falsas. ( ) Obesidade. ( ) Síndrome do\nintestino irritável. ( ) Doença de Crohn. ( ) Diabete melito. Assinale a alternativa que apresenta a\nsequência CORRETA.","options":{"A":"V ? V ? F - F","B":"F ? V ? F - V","C":"F ? F ? V - V","D":"V ? F ? V ? V"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-351595","number":"351595","sourceNumber":"351595","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"É CORRETO afirmar que a técnica de bypass gástrico é muito utilizada por:","options":{"A":"Promover intensa má absorção dos nutrientes principais.","B":"Associar restrição mecânica, disabsorção moderada e ação hormonal anorexígena.","C":"Dispensar acompanhamento multiprofissional.","D":"Ter altos índices de recidiva da obesidade em médio e longo prazo."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-373630","number":"373630","sourceNumber":"373630","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual é o tratamento inicial para hemorroida prolapsada?","options":{"A":"Escleroterapia","B":"Bandagem","C":"Cirurgia","D":"Reposição manual"},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-335067","number":"335067","sourceNumber":"335067","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Quanto ao diagnóstico diferencial da oclusão arterial aguda por embolia ou trombose,\nassinale a alternativa correta.","options":{"A":"Na embolia, a claudicação intermitente está presente, enquanto na trombose ela é rara.","B":"A angiografia na trombose mostra aterosclerose difusa e circulação colateral, enquanto na\nembolia há oclusão em ?taça invertida? e aterosclerose mínima.","C":"A ausência de pulso no membro contralateral é frequente na embolia, ao contrário do que ocorre\nna trombose.","D":"A trombose geralmente está relacionada a doença cardíaca de base, enquanto na embolia essa\nrelação é muito rara."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-345719","number":"345719","sourceNumber":"345719","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Nos pacientes com insuficiência cardíaca e disfunção miocárdica, em tratamento\nambulatorial de doença arterial periférica é contraindicado o uso de:","options":{"A":"Estatinas.","B":"Cilostazol.","C":"Betabloqueadores não seletivos.","D":"Antiagregantes plaquetários."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-346861","number":"346861","sourceNumber":"346861","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 34 anos apresenta-se no consultório médico com queixa de constipação\nintestinal crônica e hematoquezia há um mês, sem\noutras queixas ou antecedentes pessoais ou\nfamiliares relevantes. Ao exame proctológico completo, foram diagnosticadas hemorroidas internas\nde grau II. É CORRETO afirmar que a medida a ser implementada imediatamente para esse\npaciente deve ser:","options":{"A":"Colonoscopia virtual.","B":"Hemorroidectomia fechada.","C":"Hemorroidopexia grampeada.","D":"Orientações dietéticas com aumento de ingestão de fibras."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-346864","number":"346864","sourceNumber":"346864","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, IMC = 49kg/m2, portador de hipertensão arterial\ncontrolada com dois medicamentos de uso oral, hiperinsulinemia, hipertrigliceridemia, e apneia do\nsono de grau leve. À endoscopia, apresenta esofagite grau A e hérnia hiatal de 3cm. A partir do\ncaso apresentado, a MELHOR indicação cirúrgica para o paciente é de:","options":{"A":"By-pass gástrico.","B":"Banda gástrica ajustável.","C":"Gastrectomia vertical.","D":"Hiatoplastia com fundoplicatura."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-320446","number":"320446","sourceNumber":"320446","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"No Brasil, e em vários países do mundo, a obesidade já é mais comum do que a\ndesnutrição na população em geral. Entre idosos, a situação não é diferente. Além do próprio\nprocesso de envelhecimento, hábitos do nosso estilo de vida atual contribuem para o aumento da\nobesidade entre os brasileiros. O sedentarismo ou falta de atividade física e dietas inadequadas\nsão os principais fatores associados à epidemia de obesidade nas sociedades modernas. No\nmanejo terapêutico da obesidade no idoso, pode-se afirmar que:","options":{"A":"A cirurgia bariátrica pode ser considerada em indivíduos acima de 65 anos em algumas\nsituações específicas, considerando o risco\ncirúrgico, presença de comorbidades, expectativa de\nvida e benefícios da perda de peso.","B":"Os agonistas dos receptores de GLP-1 não são opções seguras e devem ser evitadas em todas\nas situações.","C":"Dietas de muito baixa calorias ou dietas restritas em proteínas são fortemente encorajadas como\ntratamento nutricional visto baixo risco de exacerbação da sarcopenia.","D":"Diversos ensaios clínicos, como por exemplo o ADAPT (Arthritis, Diet and Activity Promotion\nTrial), não conseguiram mostrar evidência que\na perda intencional de peso poderia diminuir a longo\nprazo o risco de mortalidade em idosos. Dessa forma, mesmo com suporte adequado, a perda\nintencional de peso não apresenta qualquer benefício ao paciente idoso.","E":"Como toda doença crônica, o tratamento farmacológico tem o objetivo de impedir a progressão e\nprevenir complicações e deve ser suspenso assim que o efeito de emagrecimento for obtido, visto\nbaixo risco de recuperação do peso prévio após sua interrupção."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-336287","number":"336287","sourceNumber":"336287","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Você é chamado no Alojamento conjunto para avaliar recém-nascido a termo nascido\nde parto vaginal, Apgar 8/9 de gestante com 2\nconsultas anotadas no cartão de pré-natal, sem\nrelato de intercorrências. Testes rápidos para sífilis, HIV, hepatite B e C negativos. Enfermagem\nrelata sialorreia e regurgitação após tentativa de mamadas ao seio materno associada a tosse e\ncianose. Solicitado RX tórax com imagem abaixo. Qual a terapêutica mais adequada para este\npaciente?","options":{"A":"Manter em alojamento conjunto e realizar anti-emético","B":"Manter em alojamento conjunto e solicitar USG de abdome","C":"Internação na UTIN e iniciar antibioticoterapia","D":"Internação na UTIN e programação cirúrgica"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291917","number":"291917","sourceNumber":"291917","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O exame de imagem MAIS ADEQUADO para o diagnóstico da torção testicular, é a:","options":{"A":"Radiografia simples.","B":"Ultrassonografia com eco-color doppler.","C":"Tomografia computadorizada.","D":"Ressonância magnética."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-304852","number":"304852","sourceNumber":"304852","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia metabólica foi reconhecida pelo Conselho Federal de Medicina (CFM) no ano\nde 2017, através da resolução CFM\nnº2.172/2017. Esta cirurgia está indicada:","options":{"A":"Para pacientes diabéticos tipo 2 com IMC (Índice de Massa Corporal) entre 30 e 34,9 kg/m².","B":"Para paciente com menos de 2 anos de diabetes tipo 2.","C":"Para pacientes diabéticos tipo 2 com IMC normal.","D":"Para pacientes diabéticos tipo 1."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-305008","number":"305008","sourceNumber":"305008","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação ao controle dos fatores de risco no tratamento clínico dos pacientes com\nclaudicação intermitente, é correto afirmar:","options":{"A":"A dislipidemia é o fator de risco mais importante, quando se manifesta com aumento do\ncolesterol acima de 300 mg%, associado ao aumento\nsimultâneo dos triglicerídeos acima de 250\nmg%.","B":"A hiper-homocisteinemia, quando presente, é o fator de pior prognóstico.","C":"O controle da hipertensão é o principal fator para minimizar a evolução da aterosclerose.","D":"O fumo é o mais importante de todos os fatores, quando considerado isoladamente."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-306716","number":"306716","sourceNumber":"306716","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre a doença arterial obstrutiva periférica, assinale a alternativa correta.","options":{"A":"O paciente que decide parar de fumar por conta própria, sem aconselhamento e\nacompanhamento médico tem maior chance de apresentar sucesso em um ano.","B":"O controle da hipertensão arterial é um dos pilares do tratamento clínico. Para o controle\npressórico, podemos fazer uso de inibidores da ECA, que reduzirão a mortalidade em\naproximadamente 25%.","C":"O uso de ácido acetilsalicílico reduz a mortalidade cardiovascular nos pacientes com doença\narterial periférica em aproximadamente 60%, estando indicado, portanto a todos os pacientes.","D":"As estatinas devem fazer parte da prescrição para todos os pacientes que apresentem doença\narterial periférica, com alvo de LDL < 100mg/dL."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-306717","number":"306717","sourceNumber":"306717","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"P.S.T, 48 anos, vem à consulta médica com relato de estar apresentado exteriorização\nde conteúdo anal com redução espontânea há cerca\nde 3 meses. Durante o exame físico foi\nobservada doença hemorroidária interna. Com relação à situação apresentada, assinale a\nalternativa que classifica corretamente a doença apresentada pelo paciente.","options":{"A":"Segundo grau","B":"Primeiro grau","C":"Quarto grau","D":"Terceiro grau"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-291950","number":"291950","sourceNumber":"291950","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 2 anos, gênero masculino, admitido no Pronto Socorro com dor abdominal\nvômitos, agitado e irritado. No exame físico se encontra desidratado e com distensão abdominal.\n\nMãe relata que ficou assim desde a manhã, há cerca de 8 horas e não conseguiu almoçar. Fica\ncerca de 20 minutos calmo e depois se\ncontorce e chora. Os pais atribuíram este quadro a um açaí\ncom morango que a criança comeu no parque perto de sua casa e relatam de evacuação com\nmuco e um aspecto de groselha a que a mãe também atribuiu ao açaí com morango. Rx de\nabdômen mostra distensão de delgado e níveis hidroaéreos. Considerando o caso descrito, é\nCORRETO afirmar que o diagnóstico provável para esse paciente é o de:","options":{"A":"Apendicite aguda.","B":"Doença de Hirschsprung.","C":"Intussuscepção.","D":"Intoxicação alimentar."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-283884","number":"283884","sourceNumber":"283884","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual das alternativas abaixo NÃO é indicada no tratamento de pacientes com doença\narterial periférica sintomática dos vasos ilíacos?","options":{"A":"AAS 81 mg/d.","B":"Repouso devido à claudicação intermitente, a qual reduz muito a qualidade de vida dos\npacientes.","C":"Atorvastatina 80 mg/d.","D":"Teste terapêutico com cilostazol 100 mg 2x/d.","E":"Monitorização frequente das lesões da pele e consulta médica em caso de formação de úlceras."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-287845","number":"287845","sourceNumber":"287845","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação às cirurgias gástricas, assinalar a alternativa CORRETA:","options":{"A":"A técnica Y de Roux raramente é utilizada nas cirurgias bariátricas.","B":"A técnica da banda gástrica ajustável é a que mais promove alterações metabólicas.","C":"A gastrectomia vertical não promove mudança no controle da hipertensão arterial sistêmica e da\ndiabetes.","D":"A técnica duodenal Switch é a associação entre gastrectomia vertical e desvio intestinal.","E":"A técnica mais utilizada no Brasil é da banda gástrica ajustável."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-287331","number":"287331","sourceNumber":"287331","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Ao atender uma paciente feminina, de 63 anos, com astenia, adinamia, fraqueza\nmuscular, parestesia em membros inferiores, com\nmucosas descoradas, foi solicitado exames\nbioquímicos que evidenciam: hemoglobina = 6,5 g/dL; cálcio sérico normal; vitamina B12 = 35\npg/ml. Na história patológica pregressa há a descrição de ter sido submetida à cirurgia bariátrica\nhá\n10 anos e não faz uso de nenhuma medicação. Qual a conduta adequada?","options":{"A":"Prescrição de vitamina B12 parenteral.","B":"Prescrição de ferro + suplemento de cálcio + vitamina B12 por via oral.","C":"Introduzir o polivitamínico padrão para pós-cirurgia bariátrica em uso contínuo e encaminhar\npara a nutricionista.","D":"Transfusão de 02 concentrados de hemácias e introdução do complexo vitamínico oral padrão."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-287861","number":"287861","sourceNumber":"287861","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem de 53 anos, diabético, fumante, relata dor na perna ao caminhar, nos últimos 4\nmeses. Refere cãibra em ambas as panturrilhas quando caminha. Afirma que as dores são piores\nna panturrilha esquerda em comparação com a direita e que elas cessam quando ele para de\nandar. Observou que a distância de início da dor é mais limitada em uma inclinação ou em\nescadas. Ao exame físico, observa-se membros inferiores pálidos, frios, pulso tibial posterior e\nfibular diminuídos à direita e ausentes à esquerda, com pulso poplíteo mais fraco em comparação\ncom o da perna direita; dor à palpação muscular de panturrilhas; teleangectasias bilaterais. Frente\nao caso clínico exposto, assinalar a alternativa que apresenta o provável diagnóstico desse caso:","options":{"A":"Dor osteomuscular.","B":"Insuficiência venosa periférica.","C":"Doença arterial periférica.","D":"Osteoartrite.","E":"Lombociatalgia."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-266403","number":"266403","sourceNumber":"266403","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente GTP, 67 anos, tabagista, iniciou quadro de dor intermitente em perna\nesquerda durante a caminhada matinal. Procurou atendimento médico, sendo submetido à\narteriografia e diagnosticado com doença arterial oclusiva periférica (DAOP). Segundo a\nclassificação de Fontaine, qual o estádio da DAOP deste paciente?","options":{"A":"Estágio I.","B":"Estágio II.","C":"Estágio III.","D":"Estágio IV."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246721","number":"246721","sourceNumber":"246721","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Frente à uma Oclusão Arterial Aguda de um membro do corpo, os tecidos resistem de\nforma diferente à isquemia grave. Considerando essa afirmação, marque, abaixo, a alternativa\ncorreta.","options":{"A":"O nervo periférico pode apresentar lesão irreversível a partir de 6 a 8 horas de isquemia grave","B":"O músculo apresenta lesão irreversível a partir de 8 a 12 horas de isquemia grave","C":"O vaso pode resistir até a 24 horas de isquemia grave","D":"A pele só apresenta lesão necrótica a partir de 24h a 48 horas de isquemia grave","E":"Todas as alternativas anteriores estão corretas"},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246369","number":"246369","sourceNumber":"246369","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre as alternativas relacionadas à torção testicular, assinale a alternativa correta:\nI. A\nalteração congênita chamada \"testículo em badalo de sino\" está relacionada ao principal\nmecanismo de torção testicular. II. Em neonatos, ainda no processo de descida para o escroto,\nquando a fixação testicular não se deu por completo, o cordão pode torcer em conjunto com a\ntúnica vaginal. III. A torção testicular extravaginal é o tipo mais comum. IV. A alternativa I se\nrefere\nà torção testicular intravaginal.","options":{"A":"Somente 1 afirmativa é correta.","B":"Somente 2 afirmativas são corretas.","C":"Somente 3 afirmativas são corretas.","D":"Todas as afirmativas estão corretas."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-232129","number":"232129","sourceNumber":"232129","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Criança, cinco anos de idade, chega ao pronto atendimento com a mãe, que relata ter\nsentido ?massa? na barriga do filho. Exame físico: regular estado geral, hipocorada+/4+, hidratada,\nmassa de consistência endurecida no andar superior do abdome, sem ultrapassar linha média. PA\nno percentil 99 para a idade e estatura. Exame de urina: hematúria microscópica. O diagnóstico\nmais provável e o exame a ser solicitado, respectivamente, são:","options":{"A":"tumor de Wilms; US abdominal total.","B":"linfoma; US abdominal total.","C":"glomerulonefrite difusa aguda; C3 e C4.","D":"púrpura de Henoch Schönlein; US abdominal total.","E":"Leucemia Mieloide Aguda; Hemograma e Mielograma."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-243023","number":"243023","sourceNumber":"243023","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de quatro anos levado ao pronto-socorro com relato da mãe de ter sentido nos\núltimos cinco dias, massa endurecida na barriga de sua filha. Nega febre ou outros sintomas. Ao\nexame físico, regular estado geral, hipocorada+/4+, hidratada, massa de consistência endurecida\nno andar superior do abdome sem ultrapassar linha média. Exame de urina: hematúria\nmicroscópica. O diagnóstico mais provável e o exame a ser solicitado, respectivamente, são:","options":{"A":"púrpura de Henoch Schönlein; US abdominal total.","B":"tumor de Wilms; US abdominal total.","C":"neuroblastoma; tomografia abdominal","D":"linfoma; US abdominal total.","E":"nenhuma das alternativas anteriores."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-232146","number":"232146","sourceNumber":"232146","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 57 anos com queixa de sensação de plenitude epigástrica, náuseas,\nvômitos, cólica abdominal e diarreia,\nassociados à sudorese intensa e palidez que ocorre após a\nalimentação. Relata história de ter realizado cirurgia de Fobi e Capella há seis meses. Diante desse\nquadro, qual a sua principal hipótese diagnóstica?","options":{"A":"Síndrome de ?dumping? precoce.","B":"Síndrome de ?dumping? tardio.","C":"Gastrite de refluxo alcalino.","D":"Síndrome da alça aferente.","E":"Disfagia pós-vagotomia."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-232148","number":"232148","sourceNumber":"232148","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 57 anos, com história de constipação crônica refratária ao tratamento\nclínico, morador de área endêmica para doença de\nChagas, é submetido à investigação\ndiagnóstica, com evidência de tratar-se de quadro de megacólon chagásico, com importante\ndistensão em cólon sigmoide ao clister opaco. Dentre as abaixo, qual a técnica cirúrgica mais\nadequada para esse paciente?","options":{"A":"Cirurgia de Delorme.","B":"Cirurgia de Altemeyer.","C":"Retopromontofixação.","D":"Cirurgia de Ripstein.","E":"Cirurgia de Duhamel-Haddad."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-227293","number":"227293","sourceNumber":"227293","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em um recém nascido de 2 meses de idade, durante consulta pediátrica de rotina, foi\nidentificado apenas um testículo palpável no escroto e massa em região inguinal direita, com\ndescida para o escroto após manobras manuais. Diante do quadro em questão, qual o diagnóstico\ne a conduta?","options":{"A":"Distopia testicular, realizar ultrassonografia abdominal.","B":"Testículo retrátil, acompanhamento cuidadoso da descida espontânea.","C":"Distopia testicular, orquiectomia.","D":"Distopia testicular, orquipexia aos 06 meses de idade."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-243053","number":"243053","sourceNumber":"243053","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A.I.M.O., 60 anos; sexo feminino, índice de massa corporal (IMC) 36kg/m2; em\ntratamento clínico da obesidade atestado pela\nendocrinologista há 10 anos. Hipertensa, Diabética\ntipo 2, portadora de síndrome da apnéia obstrutiva do sono (SAHOS), dislipidemia e doença do\nrefluxo gastro-esofágica (DRGE). Realiza tratamento farmacológico com rosuvastatina, metformina,\nlosartana, hidroclorotiazida, esomeprazol, além do CPAP noturno. Exames de rotina recentes:\nultrassonografia abdominal evidenciando esteatose hepática grau II e colecistopatia litiásica\n(vesícula biliar parede fina repleta de cálculos); endoscopia digestiva alta com relato de esofagite\ngrau C de Los Angeles. Glicose em jejum 160mg/dl, Insulina 42mU/l, hemoglobina glicada 7,9%,\ncolesterol total 244mg/dl e triglicérides 280mg/dl. Será submetida ao tratamento cirúrgico da\nobesidade/síndrome metabólica. Dentre as afirmativas abaixo, assinale a opção CORRETA:","options":{"A":"a gastrectomia vertical/sleeve (GV) é a melhor indicação, uma vez que apresenta melhores\nresultados no tratamento da síndrome\nmetabólica, quando comparada aos resultados do bypass\ngástrico em Y de Roux (BGYR).","B":"a GV é a melhor indicação, uma vez que a ressecção do fundo e a tunelização do corpo gástrico\npermitem o tratamento efetivo da DRGE","C":"deve ser indicado o BGYR por apresentar o tratamento efetivo da obesidade e síndrome\nmetabólica assim como da DRGE.","D":"por se tratar de uma paciente de Risco, procedimento menos invasivo como a Banda Gástrica\nAjustável, feita por videolaparoscopia é a melhor opção","E":"ambas as técnicas (GV e BGYR) seriam bem indicadas, haja vista a equivalência dos resultados\nno tratamento da síndrome metabólica e DRGE nos\npacientes com obesidade grau 2."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246786","number":"246786","sourceNumber":"246786","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação a definições de obesidade de acordo com o National Institute of Healf\n(EUA), considere as seguintes assertativas: I.\nSão considerados obesos mórbidos aqueles com\nÍndice de Massa Corporal (IMC) igual ou superior a 35kg/m2. II. Os pacientes são considerados\nsuper-obesos quando seu IMC é superior a 55 kg/m2. III. Em adultos, o IMC saudável varia de 18,5\na 24,9kg/m2. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e II.","E":"I, II e III."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-243054","number":"243054","sourceNumber":"243054","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A resolução 2.172/2017 do Conselho Federal de Medicina (CFM), ampliou a indicação\nda cirurgia metabólica para o tratamento do\npaciente com Diabetes. Dentre as alternativas abaixo,\nassinale a ERRADA:","options":{"A":"a técnica de escolha é a Gastrectomia Vertical (GV), cabendo a indicação do By Pass Gástrico\nem Y de Roux em casos de exceção, onde a GV\nfor contra indicada, sem que leve prejuízos ao\nquadro clínico do paciente.","B":"a definição de cirurgia metabólica foi definida em 2016 no DSS 2 (DIABETES SURGERY\nSUMMIT): Cirurgia sobre órgãos do aparelho\ndigestivo com o objetivo de tratar o Diabetes Mellitus\ntipo 2 e a Obesidade.","C":"a indicação para a realização da cirurgia metabólica deve comprovar que o paciente apresentou\ninsucesso no tratamento clínico do Diabetes Mellitus tipo 2, mudanças no estilo de vida e que\ncompareceu regularmente ao endocrinologista nos últimos 2 anos.","D":"estão inseridos nessa resolução pacientes com Diabetes Mellitus Tipo 2 com índice de massa\ncorpórea (IMC) entre 30 e 34,9Kg/m2.","E":"os pacientes necessitam ter entre 30 e 70 anos e menos de 10 anos de diagnóstico do Diabetes\nMellitus tipo 2."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246788","number":"246788","sourceNumber":"246788","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação às comorbidades relacionadas à obesidade, considere as seguintes\nassertivas: I. A esteatose hepática é uma\nalteração comum em indivíduos obesos, sendo causada\npela deposição de triglicerídeos nos hepatócitos. II. A asma é o problema respiratório mais\nimportante ligado à obesidade. III. Certas formas de câncer ocorrem com maior frequência em\nobesos, incluindo os de esôfago, cólon e reto, fígado, vesícula biliar, pâncreas, rim, linfoma não\nHodgkin e Mieloma Múltiplo. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas I e III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246798","number":"246798","sourceNumber":"246798","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O recém-nascido com testículos localizados no canal inguinal apresenta descida\nespontânea dos mesmos com localização no saco escrotal geralmente até a idade de:","options":{"A":"3 meses","B":"12 meses","C":"15 meses","D":"18 meses","E":"2 anos"},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-246801","number":"246801","sourceNumber":"246801","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Adolescente de 13 anos iniciou há 3 horas quadro de dor súbita e intensa em escroto.\nAo exame físico, a região escrotal esquerda está\nedemaciada e muito dolorosa à palpação. Qual o\ndiagnóstico mais provável?","options":{"A":"varicocele","B":"torção testicular","C":"torção do apêndice testicular","D":"epididimite","E":"criptorquidia"},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-243072","number":"243072","sourceNumber":"243072","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre o índice tornozelo-braquial, é INCORRETO afirmar que:","options":{"A":"pode ser calculado com rapidez à beira do leito.","B":"índices iguais ou maiores que 1 são considerados anormais.","C":"os registros da pressão arterial na perna de indivíduos com vasos calcificados não são\nconfiáveis para uso.","D":"é a relação entre a pressão arterial sistólica medida no tornozelo com a pressão arterial\nsistólica\nmedida na artéria braquial.","E":"em pacientes com úlceras cutâneas, uma pressão no tornozelo menor que 55mmHg prediz\ncicatrização inadequada da úlcera."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-196773","number":"196773","sourceNumber":"196773","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente Obeso mórbido para se candidatar à Cirurgia Bariátrica deve satisfazer ao\nseguinte critério básico abaixo:","options":{"A":"IMC acima de 25kg/m2 com comorbidades.","B":"IMC abaixo de 30 kg/m2 sem comorbidades.","C":"IMC acima de 40kg/m2 com ou sem comorbidades.","D":"IMC acima de 35 kg/m2."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-196789","number":"196789","sourceNumber":"196789","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Ao defeito em formato de funil que ocorre na parte central da parede abdominal,\natravés do qual há uma protusão visceral na\nbase do cordão umbilical, nos denominamos:","options":{"A":"Gastroquise.","B":"Onfalocele.","C":"Hérnia umbilical.","D":"Hérnia ventral."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-212982","number":"212982","sourceNumber":"212982","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia bariátrica é atualmente reconhecida como tratamento padrão-ouro no\ntratamento da obesidade. Por ser medida invasiva e irreversível as indicações devem ser\nrigorosamente avaliadas pelo médico assistente. Atualmente, temos inúmeras comorbidades\nreconhecidamente associadas/agravadas pela obesidade e podem vir a indicar o tratamento\ncirúrgico em paciente com obesidade grau 2, exceto:","options":{"A":"Síndrome dos ovários policísticos.","B":"Depressão.","C":"Doença hemorroidária.","D":"Esofagite.","E":"Esteatose hepática."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-212958","number":"212958","sourceNumber":"212958","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente masculino, 40 anos, com IMC de 45 Kg/m², apresenta hérnia inguinal bilateral\ne umbilical que causam muito desconforto\ndurante o esforço físico. Procurou atendimento médico\npara buscar melhor qualidade de vida e preocupado com sua história familiar para doenças, pois\npossui na família mãe diabética, pai hipertenso, irmã diabética e iniciando tratamento para\nhipotireoidismo, avô paterno falecido por câncer pulmonar. Durante avaliação médica de rotina,\npaciente apresentou PA 15 0x 90 mmHg em todas as aferições, e exames laboratoriais que\nevidenciaram glicemia de jejum de 130 mg/dl, colesterol total 260 mg/dl e triglicerídeos 170 mg/dl.\nDiante do quadro qual a melhor proposta cirúrgica para esse paciente?","options":{"A":"Hernioplastia inguinal bilateral e umbilical no mesmo tempo. Num segundo tempo realização de\nGastrectomia Vertical.","B":"Hernioplastia inguinal bilateral e umbilical no mesmo tempo. Num segundo tempo Gastroplatia\ncom derivação em Y de Roux (by-pass gástrico)","C":"Gastrectomia vertical e hernioplastia inguinal bilateral e umbilical, todas no mesmo tempo.","D":"Gastrectomia vertical. Num segundo tempo hernioplastia inguinal bilateral e umbilical.","E":"Gastroplastia com derivação em Y de Roux (by-pass gástrico). Num segundo tempo\nhernioplastia inguinal bilateral e umbilical."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215113","number":"215113","sourceNumber":"215113","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"P.A.O., 48 anos; sexo masculino, Índice de Massa Corporal (IMC) 35,9 kg/m2;\ndiagnosticado com síndrome metabólica há 5 anos\ndurante internação devido infecção urinária.\nDesde então faz seguimento clínico com endocrinologista, cardiologista e nutricionista, além de\ntratamento farmacológico com metformina, glibenclamida, losartana, anlodipino, hidroclorotiazida,\nrosuvastatina. Exames de rotina recentes: ultrassonografia abdominal evidenciando esteatose\nhepática grau III; endoscopia digestiva alta com relado de cárdia alargado, junção esofagogástrica\na 3 cm do pinçamento diafragmático e esofagite grau B de Los Angeles. Glicose em jejum 220\nmg/dl, Insulina 42 mU/l, hemoglobina glicada 8,4%, colesterol total 284 mg/dl e trigliceres 320\nmg/dl. Foi encaminhado pela endocrinologista ao cirurgião para avaliação quanto tratamento\ncirúrgico da obesidade/síndrome metabólica. Dentre as afirmativas abaixo, assinale a opção\nCORRETA:","options":{"A":"A cirurgia deve ser contraindicada, uma vez que pacientes portadores de obesidade grau I não\npreenchem os critérios cirúrgicos estipulados pela portaria 424 do Ministério da Saúde, publicada\nem 19/03/2013.","B":"A gastrectomia vertical/sleeve é a melhor indicação, por se tratar de uma técnica disabsortiva\ncom ótimo resultado no tratamento da síndrome\nmetabólica.","C":"Deve ser indicado o by-pass gástrico em Y de Roux, por se tratar de uma técnica mista (restritiva\ne disabsortiva) com ação incretínica,\nproporcionando, além da perda ponderal, o controle da\nsíndrome metabólica.","D":"A gastrectomia vertical/sleeve é a melhor indicação, por se tratar de uma técnica restritiva com\nótimo resultado no tratamento da obesidade e síndrome metabólica.","E":"O by-pass gástrico em Y de Roux, é a melhor opção, por se tratar de uma técnica restritiva e\ncom baixo efeito incretínico."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215118","number":"215118","sourceNumber":"215118","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A Portaria 424 do Ministério da Saúde, publicada em 19 de março de 2013, redefiniu as\ndiretrizes para a organização da prevenção e do tratamento do sobrepeso e obesidade como linha\nde cuidado prioritária da Rede de Atenção à Saúde das Pessoas com Doenças Crônicas. Em\nrelação a cirurgia bariátrica, assinale a alternativa INCORRETA:","options":{"A":"Pacientes com IMC igual ou maior que 50 kg/m2 são elegíveis ao tratamento cirúrgico da\nobesidade.","B":"Pacientes com IMC igual ou maior que 30 kg/m2 e menor que 40 kg/m2, com atestado de\nintratabilidade clínica/multidisciplinar da obesidade por um período superior a 2 anos e associados\na comorbidades (alto risco cardiovascular, diabetes mellitus, hipertensão arterial sistêmica de\ndifícil\ncontrole, apneia do sono e doenças articulares degenerativas), são elegíveis ao tratamento\ncirúrgico da obesidade.","C":"Pacientes com IMC igual ou maior que 40 kg/m2 e menor que 50 kg/m2, com atestado de\nintratabilidade clínica/multidisciplinar da obesidade por um período superior a 2 anos são elegíveis\nao tratamento cirúrgico da obesidade.","D":"A cirurgia deverá ser contraindicada em pacientes portadores de hipertensão portal com varizes\nesofagogástricas; doenças imunológicas ou inflamatórias do trato digestivo superior que venham a\npredispor o indivíduo a sangramento digestivo ou outras condições de risco.","E":"Pacientes com limitação intelectual significativa sem suporte familiar adequado não preenchem\ncritérios de adesão ao tratamento cirúrgico\nda obesidade."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-212943","number":"212943","sourceNumber":"212943","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 3 anos de idade, do sexo masculino, branco, é levado pelos pais para\nconsulta com pediatra. Tem história de que há\ndois meses tem dor abdominal e sudorese noturna.\nAo exame físico está em regular estado geral, tem extremidades mais frias no lado direito do corpo\ne hipertensão arterial, protrusão de globo ocular direito e equimose periorbitária direita, e\nextensa\ntumoração em loja renal direita, de limites imprecisos, atravessando a linha média do abdome.\n\nManifestou choro intenso à palpação de membros inferiores. Pensando que pode ser um tumor\nabdominal maligno, qual seria sua hipótese diagnóstica mais provável?","options":{"A":"Neuroblastoma.","B":"Tumor de Wilms.","C":"Linfoma não Hodgkin.","D":"Rabdomiossarcoma.","E":"Carcinoma de suprarrenal."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215126","number":"215126","sourceNumber":"215126","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma criança nasceu com vísceras expostas, sem cobertura por saco amniótico, que\nsaiam pela parede abdominal a direita do cordão umbilical. O diagnóstico neste caso é:","options":{"A":"Onfalocele.","B":"Hérnia de cordão.","C":"Extrofia de bexiga.","D":"Gastrosquise.","E":"Extrofia de coacla."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-199630","number":"199630","sourceNumber":"199630","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente submetido à cirurgia bariátrica à Fobi-Capella deu entrada no pronto-socorro\ncom taquicardia, sudorese, lipotimia e desconforto\nabdominal que evoluiu com diarreia explosiva\nalguns minutos após de ter feito ingesta de bolo de chocolate em moderada quantidade. Qual o\nprovável diagnóstico?","options":{"A":"Impactação alimentar.","B":"Síndrome de Dumping.","C":"Úlcera de anastomose.","D":"Síndrome da alça aferente."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-215152","number":"215152","sourceNumber":"215152","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente jovem é levado ao pronto socorro pediátrico com história de êmese volumosa,\nnão biliosa e pós alimentar. Mãe nega\ndiminuição da ingesta alimentar ao seio materno, nem tão\npouco alteração da sucção. Relata já estar utilizando medicações devido diagnóstico prévio de\ndoença do refluxo esofagogástrica, porém sem sucesso. Ao exame físico o paciente encontra-se\ndesidratado. Assinale a alternativa que evidencia o a principal hipótese diagnóstica e distúrbio\nmetabólico mais comum dessa patologia.","options":{"A":"Alcalose metabólica hipoclorêmica ? Estenose hipertrófica de piloro.","B":"Acidose metabólica hiperclorêmica ? Má rotação intestinal.","C":"Acidose metabólica hiperclorêmica ? Estenose hipertrófica de piloro.","D":"Alcalose metabólica hipoclorêmica ? Atresia duodenal.","E":"Acidose metabólica hipoclorêmica ? Atresia duodenal."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-199595","number":"199595","sourceNumber":"199595","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre o carcinoma epidermóide de boca, assinale a alternativa CORRETA:","options":{"A":"É um dos tumores mais frequentes da boca, atrás apenas dos adenocarcinomas de glândulas\nsalivares.","B":"O tratamento deve ser cirúrgico sempre que possível, e frequentemente é necessário realizar o\nesvaziamento cervical.","C":"A radioterapia é apenas indicada em tumores recidivados ou irressecáveis.","D":"O carcinoma epidermóide dificilmente metastatiza para linfonodos regionais mas frequentemente\nmetastatiza à distancia."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-187998","number":"187998","sourceNumber":"187998","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, 60 anos, hipertenso de longa data em uso irregular de medicação, chega ao\npronto-socorro com dor retroesternal com irradiação para dorso e cervical, de intensidade 10 em\n10, iniciada há duas horas, associada a sudorese e palidez mucocutânea, sudoreico e hipocorado,\ncom pressão arterial de 220/120mmHg e eletrocardiograma a abaixo: Qual a conduta imediata?","options":{"A":"Prescrever ácido acetilssalicílico e clopidogrel.","B":"Solicitar cineangiocoronariografia de urgência.","C":"Solicitar tomografia computadorizada de aorta de urgência.","D":"Prescrever nitroprussiato de sódio.","E":"Instalar marcapasso transvenoso e controlar pressão arterial."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-4/187998.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-188023","number":"188023","sourceNumber":"188023","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Menina, 7 anos, é trazida por seu pai para atendimento médico por febre, calafrio e dor\nabdominal há 3 dias. Nega fator desencadeante. Afirma melhora fugaz com uso de analgésicos.\n\nNega comorbidades. Submetida a uma derivação biliodigestiva videolaparoscópica para ressecção\nde cisto de colédoco tipo I há 9 meses. Ao\nexame físico, apresenta taquisfigmia, hipersensibilidade\ndolorosa à palpação de hipocôndrio direito, fígado palpável há 2 cm do rebordo costal direito.\n\nTimpanismo à percussão do espaço semilunar do sexto ao décimo primeiro espaços intercostais\nesquerdos e ausência de macicez móvel. Exames\nlaboratoriais mostram leucocitose, anemia e\nelevação de transaminases. A ultrassonografia revela lesão com conteúdo hipoecogênico de 11 x 7\ncm em segmento VI hepático. Qual a conduta adequada?","options":{"A":"Segmentectomia hepática.","B":"Antibioticoterapia oral.","C":"Drenagem percutânea e antibioticoterapia intravenosa.","D":"Laparotomia com drenagem aberta e antibioticoterapia intravenosa.","E":"Drenagem guiada por videolaparoscopia e antibioticoprofilaxia."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172526","number":"172526","sourceNumber":"172526","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Marque a alternativa CORRETA em relação às cirurgias da obesidade (bariátricas):","options":{"A":"Ainda são consideradas experimentais, devido ausência de follow-up de longo prazo. Portanto,\nos pacientes devem receber essa informação por\nescrito antes de realizarem a cirurgia.","B":"Apesar de serem usadas por alguns visando o controle do diabetes e da síndrome metabólica,\nainda não existem estudos clínicos que dêem o\n\nnecessário suporte de evidências.","C":"Podem ser oferecidas como alternativas terapêuticas para obesos com índice de massa corporal\n(IMC) entre 30-34,9 kg/m² e diabetes\nmellitus tipo 2 de dificil controle.","D":"As cirurgias puramente restritivas, tipo a gastroplastia vertical, são as que mais induzem perda\nde peso e conseqüentemente, maior taxa de\ncomplicações metabólicas com desnutrição grave e\ndeficiência de micronutrientes.","E":"A gastrectomia tubular é uma gastrectomia parcial na qual a maior parte da grande curvatura é\nremovida. Porém, por ser tecnicamente mais difícil devido necessidade de várias anastomoses e\nconsiderada muito drástica pelos pacientes, é contra-indicada em super obesos (IMC > 60 kg/m²)."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-187999","number":"187999","sourceNumber":"187999","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, 68 anos, hipertenso, obeso e ex-tabagista, procurou atendimento médico por\nter a sensação de que o ?coração está\npulsando na barriga?. No exame físico, o médico palpou\numa massa pulsátil supra-umbilical na linha mediana. Tomografia computadorizada (TC) evidenciou\numa área com diâmetro aórtico abdominal externo de 5,2 cm. Sobre o adequado manejo no caso\ndescrito, assinale a alternativa correta.","options":{"A":"Não está indicado tratamento cirúrgico até reavaliação nos próximo 12 meses.","B":"Teria indicação cirúrgica se apresenta uma TC prévia de 1 ano atrás com diâmetro aórtico\nexterno de 4,5 cm.","C":"O uso de betabloqueador (propranolol) mostra-se eficaz para diminuir expansão da doença.","D":"Indicada cirurgia se nos próximos 6 meses TC mostrar diâmetro aórtico externo de 5,6 cm.","E":"Indicação cirúrgica o mais breve possível."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-174367","number":"174367","sourceNumber":"174367","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Pré-escolar, sexo feminino, é levada ao pediatra por ter apresentado sangue na urina.\nMãe relata um episódio de infecção urinária corretamente tratado há cinco meses. Relata ainda\nconstipação intestinal. Exame físico: sinais vitais normais. Abdome: levemente distendido, discreta\nflatulência, peristalse normal e presença de pequena tumoração palpável em quadrante superior\ndireito, EAS: positivo para proteínas e sangue. O quadro sugere:","options":{"A":"Nefroma cístico.","B":"Tumor de Willms.","C":"Neuroblastoma.","D":"Nefroma mesoblastico.","E":"Nova infecção urinária."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-174374","number":"174374","sourceNumber":"174374","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual o aneurisma de artéria esplâncnica mais comum?","options":{"A":"Artéria renal.","B":"Artéria mesentérica superior.","C":"Artéria mesentérica inferior.","D":"Artéria esplênica.","E":"Artéria retal superior."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172558","number":"172558","sourceNumber":"172558","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"RN com 20 dias de vida; nascido de parto normal, a termo, sem intercorrências\n(sorologias negativas e ausência de infecção)\npré e pos natal, Tempo de bolsa rota de 4 h, em\nAleitamento Materno Exclusivo; apresenta há três dias vômitos após a amamentação, de evolução\nprogressiva. Ao exame, após o episodio, observa vômitos com aspecto de leite fresco, sem sangue\nou bile, grande volume; RN tranqüilo, sem fáscie de dor ou irritabilidade, ativo, pouco emagrecido,\nFA pouco deprimida, acianótico, anictérico, logo após procura seio materno e suga com muita força\n(demonstrando fome); musculatura abdominal relaxada, abdome flácido, indolor, nódulo palpável\nacima da cicatriz umbilical, no epigástrio médio, abaixo da borda hepática, +- 2,0 cm de\ncomprimento, móvel. Sobre o caso:","options":{"A":"Caso clássico de Refluxo Gastroesofágico com hérnia hiatal, devendo ser confirmado por\nestudos radiográficos;","B":"Típico de insuficiência adrenal, devendo ser confirmado pela acidose metabólica, potássio sérico\ndiminuído e concentrações de sódio na urina diminuídas;","C":"Sugestivo de Erro Inato do Metabolismo, provável evolução com agitação e convulsões,\ndevendo ser confirmado por exames laboratoriais\nque caracteristicamente apresentarão alcalose\nmetabólica.","D":"Caso típico de Estenose Hipertrófica do Piloro, podendo ser confirmado pela ultrassonografia de\nabdome."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-187450","number":"187450","sourceNumber":"187450","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Em relação à Cirurgia Bariátrica e Metabólica, assinale a afirmativa incorreta:","options":{"A":"Paciente portador de IMC igual ou maior a 35kg/m2 associado a apnéia do sono, com\nintratabilidade clínica da obesidade por no mínimo 2 anos, poderá ser candidato ao tratamento\ncirúrgico da obesidade.","B":"O Conselho Federal de Medicina (CFM) juntamente com a Sociedade Brasileira de Cirurgia\nBariátrica e Metabólica (SBCBM) tornaram o\nBrasil o primeiro país a regulamentar as diretrizes para\no tratamento cirúrgico do Diabetes Tipo 2. Na resolução 2.172/2017 publicada pelo CFM,\nportadores de IMC igual ou maior a 30kg/m2, idade mínima de 30 e máxima de 70 anos e Diabetes\nTipo 2 por pelo menos 10 anos, enquadram-se no perfil dos pacientes que poderão ser submetidos\nao tratamento cirúrgico do Diabetes Tipo 2. A técnica de escolha deverá ser a Gastrectomia Vertical\n(Sleeve), por se tratar de uma cirurgia menos agressiva em pacientes menos obesos.","C":"Trombose venosa profunda com embolia pulmonar e fístula anastomótica e/ou na linha de\ngrampeamento são as principais causas de mortalidade no pós operatório imediato.","D":"A Grelina, hormônio orexígeno, produzido principalmente no fundo gástrico, tem seus níveis\nséricos diminuídos no pós operatório da\nGastrectomia Vertical/Sleeve e do By pass Gástrico, mas\nnão alterados na derivação bíleo pancreática tipo Scopinaro","E":"A taquicardia é a principal e primeira alteração clínica/hemodinâmica nos casos de fístula\nanastomótica e/ou da linha de grampeamento."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-187448","number":"187448","sourceNumber":"187448","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Com relação aos aneurismas de aorta, podemos afirmar:","options":{"A":"A maioria é sintomático.","B":"No aneurisma do tipo sacular, toda a circunferência da parede da aorta é acometida e está\ndilatada.","C":"Quando o aneurisma acomete a aorta ascendente, pode ocorrer insuficiência valvar aórtica e\ninsuficiência cardíaca.","D":"Independente da posição do aneurisma de aorta, não há possibilidade de haver Síndrome da\nVeia Cava Superior.","E":"Todas as alternativas acima estão incorretas."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172809","number":"172809","sourceNumber":"172809","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"No trauma vascular existem sinais e sintomas maiores e menores que sugerem lesão\nvascular aguda. Assinale a alternativa que contém apenas sinais/sintomas maiores de lesão\nvascular aguda:","options":{"A":"Sangramento pulsátil; frêmito; déficit neurológico periférico; ferimento proximal com choque\ninexplicável.","B":"Ausência de pulso; frialdade; história de hemorragia moderada; fratura de ossos longos com\ndeslocamento no trajeto vascular.","C":"Parestesia; dor; hematoma em expansão; ausência de pulso.","D":"Sangramento pulsátil; frêmito; hematoma em expansão; pulso diminuído."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172824","number":"172824","sourceNumber":"172824","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dentre os tumores congênitos de segmento lateral do pescoço, qual apresenta outra\npossibilidade de tratamento que não a cirurgia?","options":{"A":"Cisto branquial.","B":"Fístula branquial.","C":"Cisto tireoglosso.","D":"Higroma cístico."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172753","number":"172753","sourceNumber":"172753","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os resultados de perda de peso a longo prazo, o acesso videocirúrgico, a redução do\níndice de complicações e o controle de diversas doenças associadas à obesidade mórbida fez com\nque a Cirurgia Bariátrica se popularizasse, sendo atualmente um dos procedimentos mais\nrealizados na cirurgia digestiva. Dentre as técnica abaixo, assinale a que atualmente é a mais\nrealizada mundialmente:","options":{"A":"Bypass gástrico em Y-de-Roux.","B":"Bypass gástrico à Billroth II (minigastric bypass).","C":"Gastrectomia vertical.","D":"Banda gástrica ajustável."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172761","number":"172761","sourceNumber":"172761","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Na operação de bypass gástrico em Y-de-Roux a complicação operatória tardia mais\npreocupante e ameaçadora à vida do paciente é:","options":{"A":"Fístula gastrogástrica.","B":"Trombose do sistema mesentérico.","C":"Tromboembolismo pulmonar.","D":"Obstrução intestinal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-172762","number":"172762","sourceNumber":"172762","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"G.H.T., 45 anos, obeso grau III com índice de massa corporal de 48.8, diabético há 05\nanos mal controlado com insulina NPH. Possui\noutras doenças associadas como hipertensão\narterial e doença do refluxo gastroesofágico. Qual a opção operatória mais apropriada para o\ndoente em questão?","options":{"A":"Gastrectomia vertical com interposição ileal.","B":"Bypass gástrico em Y-de-Roux.","C":"Gastrectomia vertical.","D":"Banda gástrica ajustável."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-149141","number":"149141","sourceNumber":"149141","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente 75 anos, sexo feminino, hipertensa grave de longa data, obesa, dá entrada no\npronto-socorro HECI com história de intensa dor precordial, com irradiação dorsal e para membro\nsuperior esquerdo, iniciada há cerca de 2 horas. Familiares referem quadro de convulsão e breve\nperda de consciência à caminho do hospital. Ao exame clínico encontra-se acordada, lúcida, sem\nalterações no exame neurológico. Ritmo cardíaco regular, FC 102 bpm, 170 x 80 mmHg, sopro\ndiastólico em focos de base. Ausculta pulmonar limpa. Eletrocardiograma realizado imediatamente\nmostrando ritmo sinusal, com supradesnivelamento do segmento ST 3 mm em D2, D3, AVf. Diante\ndo caso exposto, qual a melhor conduta imediata a ser tomada?:","options":{"A":"Medir a pressão em membro superior esquerdo, examinar pulso em membros inferiores e\nrealizar um RX tórax imediatamente.","B":"Solicitar dosagem de troponina e CKMB.","C":"Administrar AAS, clopidogrel, morfina, nitrato, beta bloqueador, heparina e encaminhar à sala de\nhemodinâmica imediatamente para angioplastia primária (desde que o tempo estimado para o\nprocedimento seja inferior a 90 minutos).","D":"Proceder a trombólise imediatamente caso a angioplastia não seja possível num\nintervalo de tempo inferior a 120 minutos.","E":"Administrar AAS, clopidogrel, morfina, nitrato, betabloqueador, heparina e encaminhar à sala de\nhemodinâmica imediatamente para angioplastia primária (desde que a dosagem de enzimas esteja\nalterada)."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-155453","number":"155453","sourceNumber":"155453","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Recém-nascido a termo pesando 2100 g, com APGAR 4 no primeiro minuto e 6 no\nquinto minuto, apresentou policitemia com sintomas de hiperviscosidade no segundo dia de vida.\nFoi realizada exsanguineotransfusão parcial sem intercorrências. Após o procedimento, ficou 48\nhoras sem evacuar, apresentando hipoatividade e distensão abdominal com alças de delgado\ndesenhadas em relevo sob a parede abdominal. Após suspender a amamentação, indica-se\nnutrição:","options":{"A":"Parenteral e dieta zero.","B":"Gástrica com colostro.","C":"Enteral pós-pilórica com leite materno.","D":"Parenteral e manutenção de dietatrófica.","E":"Enteral pós-pilórica com fórmula hidrolisada."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-149133","number":"149133","sourceNumber":"149133","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A torção do cordão espermático é uma emergência cirúrgica, mais comum em\nadolescentes. Acerca desse assunto marque a alternativa INCORRETA:","options":{"A":"Ocorre dor no abdome inferior de início súbito e edema escrotal.","B":"A orquipexia contralateral é desnecessária.","C":"O testículo se apresenta retraído e hipersensível.","D":"Orquite e epididimite são diagnósticos diferenciais.","E":"Na torção complete pode haver infarto testicular dentro de 4 a 6 horas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-149144","number":"149144","sourceNumber":"149144","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente dá entrada no pronto-socorro apresentando dor anal aguda e febre. O\ndiagnóstico mais provável é?:","options":{"A":"Trombose hemorroidária.","B":"Retocolite ulcerativa.","C":"Fístula anal.","D":"Fissura anal.","E":"Abscesso anal."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-162523","number":"162523","sourceNumber":"162523","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente F.M., 39 anos, chega ao pronto-socorro, com quadro de dor em região\nperianal, principalmente às evacuações, de início\nhá cerca de 01 mês, com episódio de\nsangramento vermelho vivo há 02 horas e sensação de tumoração anal. Ao exame, identificado na\ninspeção dinâmica protrusão de mamilo hemorroidário com redução durante o relaxamento. Qual a\ngraduação da doença hemorroidária e qual o melhor tratamento neste momento?","options":{"A":"Doença hemorroidária de primeiro grau - tratamento clínico.","B":"Doença hemorroidária de terceiro grau - hemorroidectomia de urgência.","C":"Doença hemorroidária de segundo grau - tratamento clínico.","D":"Doença hemorroidária de terceiro grau - hemorroidectomia eletiva.","E":"Doença hemorroidário de segundo grau - hemorroidectomia eletiva."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-149162","number":"149162","sourceNumber":"149162","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente é internado pela equipe de clínica médica do Hospital Evangélico com\ndiagnóstico de abscesso anal. Após corrida de\nleito com preceptor, o residente é orientado a\ntransferir o caso para a equipe da cirurgia geral. Ao avaliar o paciente, o residente da cirurgia\ngeral\ndeve:","options":{"A":"Assumir o caso para a equipe da cirurgia, iniciar clavulin e compressas quentes.","B":"Orientar a equipe de clínica médica a iniciar o tratamento com cipro e metronidazol e\ncalor local.","C":"Entrar em contato com seu preceptor e encaminhar paciente ao centro cirúrgico para realização\nde drenagem do abscesso assim que possível.","D":"Orientar a equipe de clínica médica a iniciar o tratamento com cipro e metronidazol e\ncalor local. Caso ausência de melhora clínica em 72 horas, realizar drenagem cirúrgica.","E":"Assumir o caso para a equipe da cirurgia, iniciar tratamento com cipro e metronidazol e\ncalor local, realizar drenagem cirúrgica após 48h se falha do tratamento antibiótico."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-155478","number":"155478","sourceNumber":"155478","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O sintoma mais comum presente em pacientes lúcidos e portadores de isquemia aguda\ndos membros inferiores é:","options":{"A":"Palidez.","B":"Ausência de pulso.","C":"Paralisia.","D":"Parestesias.","E":"Dor."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-148563","number":"148563","sourceNumber":"148563","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Os distúrbios da defecação na infância estão entre as condições clínicas que mais\nproduzem estresse para a família, considerando que para os pais é muito importante a habilidade\nde seus filhos evacuarem adequadamente. Observe as afirmativas abaixo e marque a sentença\ncorreta.","options":{"A":"Toda criança que evacua a cada dois ou três dias, independente da consistência das fezes e da\ndificuldade de evacuação é considerado portador de constipação intestinal.","B":"Os anticolinérgicos e narcóticos podem causar constipação intestinal.","C":"A constipação pode ser devido à hiperpotassemia ou à hipocalcemia.","D":"A constipação pode ser devido ao hipertireoidismo, otite e infecção urinária.","E":"A presença de constipação intestinal é um importante sintoma para descartarmos a doença\ncelíaca."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-148605","number":"148605","sourceNumber":"148605","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A estenose hipertrófica do piloro é caracterizada por uma hipertrofia da musculatura\npilórica, causando estreitamento e alongamento\npersistentes do canal pilórico. Observe as\nalternativas abaixo sobre a estenose hipertrófica do piloro e marque a alternativa correta.","options":{"A":"O vômito bilioso é o sintoma inicial da estenose do piloro.","B":"Os vômitos em geral começam imediatamente após o nascimento.","C":"À medida que o vômito persiste, ocorre acidose metabólica e aumento do cloro.","D":"A presença de icterícia ocorre em 80% dos pacientes.","E":"Os vômitos geralmente ocorrem após três semanas de vida."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-148603","number":"148603","sourceNumber":"148603","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de nove meses de idade, sexo masculino, começou a apresentar subitamente\nirritabilidade, vômito e eliminação de fezes com muco com sangue do tipo \"geleia de morango\".\n\nQual a principal hipótese diagnóstica?","options":{"A":"Estenose hipertrófica do piloro.","B":"Invaginação intestinal.","C":"Apendicite aguda.","D":"Obstrução intestinal por Ascaris lumbricoides.","E":"Diarreia por Giardia lamblia."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-148589","number":"148589","sourceNumber":"148589","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente jovem, mulher, com o relato de constipação crônica procura ambulatório com\nqueixa de dor importante ao evacuar há algumas semanas associado a pequeno sagramento após\no ato evacuatório. Ao exame proctologico, a anuscopia mostrou presença de úlcera linear na\nmetade inferior do canal na linha média posterior, associado a discreta hipertonia anal e dor\nassociada ao toque retal. O provável diagnóstico é:","options":{"A":"Doença hemorroidária.","B":"Abcesso perianal.","C":"Fístula anal.","D":"Fissura anal.","E":"Prolapso retal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-148602","number":"148602","sourceNumber":"148602","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 20 anos, masculino, procurou o Pronto Socorro relatando intensa dor na\nregião anal com três dias de evolução e piora progressiva. Ao exame da região perianal apresenta\npresença de hiperemia intensa, com área de flutuação em região perianal. O paciente não permitiu\no toque retal devido à intensa dor. O exame laboratorial apresentou leucocitose com desvio à\nesquerda. De acordo com o provável diagnóstico, a conduta mais adequada é:","options":{"A":"Banho de assento e analgesia venosa.","B":"Analgésico, antibioticoterapia oral e acompanhamento ambulatorial.","C":"Internação hospitalar e antibioticoterapia venosa.","D":"Drenagem cirúrgica de área acometida e antibioticoterapia venosa com internação hospitalar.","E":"Internação hospitalar e colonoscopia diagnostica com paciente sedado."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-155432","number":"155432","sourceNumber":"155432","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A combinação CORRETA entre a idade preconizada para intervenção corretiva\ncirúrgica e condição relacionada é:","options":{"A":"Hérnia umbilical; intervenção com 6 meses de vida.","B":"Hérnia inguinal; intervenção quando do diagnóstico.","C":"Orelha de abano; intervenção aos 2 anos de vida.","D":"Hérnia epigástrica; intervenção com 1 ano de vida.","E":"Criptorquidia; intervenção com 2 anos de vida."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-155434","number":"155434","sourceNumber":"155434","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Mãe percebe massa abdominal ao dar banho em sua filha de 3 anos. A criança está em\nbom estado geral e assintomática. A\nultrassonografia revela um tumor de topografia intrarrenal.\n\nDiante desse quadro, qual o diagnóstico mais provável?","options":{"A":"Hidronefrose.","B":"Tumor de Wilms.","C":"Cisto renal.","D":"Linfoma.","E":"Neuroblastoma."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137851","number":"137851","sourceNumber":"137851","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente de 74 anos apresenta dor retroesternal excruciante, localizada, irradiada para\nregião dorsal, com inicio há 1 hora. É hipertenso, em uso irregular de hidroclorotiazida e\nenalapril.\nAo exame, constata-se palidez cutâneo-mucosa, sudorese fria profusa, pressão arterial sistêmica =\n200 x 140 mmHg, FC: 150 bpm, presença de sopro diastólico +++/4+ em borda paraesternal\nesquerda. O ECG revela sobrecarga de átrio e de ventrículo esquerdo, enquanto que o RX de tórax\nmostra alargamento de mediastino. Considerando o diagnóstico mais provável, a melhor conduta\ninicial seria:","options":{"A":"Analgesia com opioides, oxigênio, ácido acetilsalicílico, nitratos e coronariografia.","B":"Analgesia com opioides, controle de FC com betabloqueador, controle de PA com nitratos e\ncirurgia endovascular após estabilização.","C":"Analgesia com opioides, controle de FC com betabloqueador, controle de PA com nitratos e\ncirurgia aberta após estabilização.","D":"Tipagem sanguínea e cirurgia em caráter de emergência.","E":"Analgesia com opioides, betabloqueador, controle pressórico com nitratos e tomografia\ncomputadorizada."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137853","number":"137853","sourceNumber":"137853","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre as dissecções da aorta podemos afirmar que:","options":{"A":"As dissecções tipo A de Stanford não complicadas devem ser tratadas clinicamente.","B":"O RX de tórax pode se apresentar normal em até 40% dos pacientes.","C":"A dislipidemia e o tabagismo apresentam-se como os principais fatores de risco.","D":"As dissecções de aorta tipo B de Stanford geralmente envolvem a aorta ascendente.","E":"A localização interescapular sugere acometimento de aorta descendente em cerca de 90% dos\ncasos."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137852","number":"137852","sourceNumber":"137852","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma paciente de 23 anos de idade foi vitima de ferimento por arma branca no terço\nmédio da coxa ha 2 horas. Ao exame físico,\napresenta pulso de 122 bpm, Pressão Arterial (PA) de\n110 x 60 mmHg, palidez, hipotermia e cianose não fixa do membro acometido pelo trauma, com\npulso femoral palpável e ausência de pulsos poplíteo e distais. Qual seria a melhor conduta para\nesse caso?","options":{"A":"Solicitação de ultrassonografia doppler para confirmação da lesão vascular.","B":"Antiagregação plaquetária e vasodilatadores sistêmicos.","C":"Tratamento cirúrgico definitivo imediato aberto.","D":"Solicitação de arteriografia para confirmação da lesão vascular.","E":"Anticoagulacão sistêmica e aquecimento passivo do membro."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137814","number":"137814","sourceNumber":"137814","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente tabagista a longa data, diabética, com história de claudicação do membro\ninferior direito para cerca de 50 metros,\nevoluiu com necrose do hálux após pequeno trauma local.\nAo exame, observa-se lesão úmida em hálux necrótica com hiperemia e edema do dorso pé e\nregião plantar. Podemos definir como conduta apropriada:","options":{"A":"Solicitar ecodoppler arterial e antibioticoterapia, com retorno agendado em 7 dias.","B":"Arteriografia diagnóstica de urgência, seguido de angioplastia.","C":"Internação, antibioticoterapia de largo espectro e desbridamento cirúrgico de urgência.","D":"Revascularização do membro de urgência.","E":"Arteriografia diagnóstica de urgência, seguido de revascularização do membro."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-137820","number":"137820","sourceNumber":"137820","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Escolha, dentre as opções abaixo, a artéria com maior tendência de comprometimento\npela doença aterosclerótica no paciente tabagista:","options":{"A":"Artéria femoral superficial.","B":"Artéria tibial posterior.","C":"Artéria fibular.","D":"Artéria poplítea.","E":"Artéria tibial anterior."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-127174","number":"127174","sourceNumber":"127174","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Para um paciente que chega ao pronto socorro com varicorragia ativa, o que não\nrepresenta uma conduta apropriada?","options":{"A":"Elevar a extremidade do paciente.","B":"Colocar torniquete na raiz da coxa para impedir o refluxo da veia safena.","C":"Fazer curativo constensivo com volume de gaze sobre a lesão para maior compressão pontual.","D":"Fazer escleroterapia química na veia que rompeu.","E":"Aplicar ponto em X no orifício da veia acometida."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-106406","number":"106406","sourceNumber":"106406","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Todas as vezes em que é necessário monitorizarmos a pressão arterial média na UTI, e\noptamos pelo acesso radial, qual o teste que devemos realizar antes da punção do vaso?","options":{"A":"Teste de Allen.","B":"Teste de Adson.","C":"Teste de Raynaud.","D":"Arteriografia de membro superior.","E":"Eco-doppler de artéria radial."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-106469","number":"106469","sourceNumber":"106469","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Um adolescente com 16 anos de idade entrou na emergência de um hospital\nreclamando de dor súbita no testículo\ndireito. A dor o despertou do sono e persistiu nas últimas três\nhoras. A mãe informou que ele vomitou uma vez. Relatou, também, que há aproximadamente um\nano apresentou dor semelhante que cedeu espontaneamente. Ao exame, o testículo esquerdo\nestava normal, mas o direito estava muito edemaciado, elevado e sensível. O reflexo cremastérico\nestava ausente. Nessa situação, o possível diagnóstico é:","options":{"A":"orquiepididimite.","B":"hidrocele infectada.","C":"hérnia inguinal estrangulada.","D":"torção testicular.","E":"tumor de testículo."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-106470","number":"106470","sourceNumber":"106470","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual a conduta inicial diante de um quadro de parafimose?","options":{"A":"Realização de incisão do anel de constricção do prepúcio.","B":"Utilização de gelo para regredir o edema.","C":"Redução manual da parafimose.","D":"Postectomia.","E":"Nenhuma das medidas acima."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-101000","number":"101000","sourceNumber":"101000","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A principal causa de complicação fatal no período pós-operatório precoce de cirurgia\nbariátrica, atualmente, é:","options":{"A":"Tromboembolismo pulmonar.","B":"Fístula da anastomose gástrica.","C":"Fístula da anastomose entérica.","D":"Obstrução intestinal.","E":"Infarto agudo do miocárdio."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-100963","number":"100963","sourceNumber":"100963","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A prova de Allen NÃO oferece subsídio para:","options":{"A":"Diagnóstico de microembolia periférica.","B":"Orientação de punção arterial.","C":"Definir permissão de cateterismo de artéria radial.","D":"Diagnosticar tromboangeíte obliterante.","E":"Diagnosticar oclusão de artéria ulnar."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-100980","number":"100980","sourceNumber":"100980","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Qual condição abaixo não está associada à úlcera venosa?","options":{"A":"Sequela de trombose venosa femoro-ilíaca.","B":"Varizes primárias dos membros inferiores.","C":"Fístula arteriovenosa traumática.","D":"Dislipidemia venosa.","E":"Insuficiência de veias perfurantes do grupo Cockett com mais de 3,4mm de diâmetro."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-88855","number":"88855","sourceNumber":"88855","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"O controle cirúrgico do diabetes mellitus tipo II é fundamentado:","options":{"A":"na restrição alimentar.","B":"na perda ponderal.","C":"no efeito incretínico.","D":"na disabsorção.","E":"no aumento da massa magra."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-88857","number":"88857","sourceNumber":"88857","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A gastroplastia com by-pass jejunal é formalmente indicada para diabéticos:","options":{"A":"tipo I com IMC > 35.","B":"tipo II com IMC > 40.","C":"tipo I com IMC > 40.","D":"tipo II com IMC > 35.","E":"tipo II com IMC > 30."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-88858","number":"88858","sourceNumber":"88858","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia de Scopinaro é indicada para:","options":{"A":"diabéticos tipo I.","B":"diabéticos tipo II.","C":"pacientes com IMC > 35.","D":"pacientes com IMC > 50.","E":"obesos mórbidos."},"answer":"E","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-88860","number":"88860","sourceNumber":"88860","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A principal causa de vômitos após cirurgia de gastroplastia com by-pass jejunal por\nvideolaparoscopia sem anel seria:","options":{"A":"Estenose da anastomose.","B":"Torção da alça eferente.","C":"Hérnia interna.","D":"Hábitos alimentares inadequados.","E":"Aderências peritoniais."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-77360","number":"77360","sourceNumber":"77360","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A cirurgia bariátrica para o tratamento da obesidade:","options":{"A":"É considerada um procedimento médico experimental não validado para o tratamento de\nportadores de obesidade mórbida.","B":"A gastrectomia vertical é a técnica mais antiga e a mais usada no Brasil e no Mundo.","C":"Obteve melhor resultado no controle glicêmico de pacientes severamente obesos com diabetes\ntipo 2 do que a terapia médica convencional,\nconforme estudo publicado recentemente pela New\nEngland Journal of Medicine.","D":"Todas as técnicas e tipos de cirurgia levam ao emagrecimento apenas por um mecanismo\nrestritivo, ou seja, por diminuição da\ncapacidade de alimentos que o estômago é capaz de suportar.","E":"Os pacientes que mais se beneficiam da cirurgia são os portadores de distúrbios psiquiátricos,\npois estes não conseguem compreender e realizar\nas dietas e exercícios convencionais\nnecessários à perda de peso natural."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-59091","number":"59091","sourceNumber":"59091","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dentre as operações listadas abaixo, assinale a intervenção sobre o trato digestivo para\nperda de peso considerada proscrita pelo Conselho Federal de Medicina:","options":{"A":"Gastroplastia com derivação intestinal.","B":"Gastrectomia vertical.","C":"Gastroplastia vertical de Mason.","D":"By-pass jejunoileal.","E":"Interposição ileal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-59095","number":"59095","sourceNumber":"59095","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 54 anos, portadora de hemorroidas grau III, com\nacometimento de dois mamilos hemorroidarios.\nHábito intestinal normal. Colonoscopia sem outras\nalterações dignas de nota. O tratamento mais adequado, entre os Iistados abaixo, é:","options":{"A":"Cauterização com plasma de argônio.","B":"Hemorroidectomia à Milligan-Morgan.","C":"Ligadura elástica.","D":"Hemorroidectomia com grampeador circular.","E":"Escleroterapia endoscópica."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-59096","number":"59096","sourceNumber":"59096","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A artéria que constitui o acesso mais frequente para procedimento angiográfico\ndiagnóstico e/ou terapêutico endovascular é:","options":{"A":"Subclávia.","B":"Axilar.","C":"Braquial.","D":"Femoral comum.","E":"Radial."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-43986","number":"43986","sourceNumber":"43986","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, portadora de hemorroidas grau II. O tratamento\nmais indicado é:","options":{"A":"Escleroterapia.","B":"Cauterização.","C":"Ligadura elástica.","D":"Hemorroidectomia à Milligan-Morgan.","E":"Hemorroidectomia com grampeador circular."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-32432","number":"32432","sourceNumber":"32432","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"JCP, sexo masculino, 85 anos, diabético e hipertenso é submetido a cirurgia de\nemergência para tratamento de ruptura de aneurisma de aorta abdominal. Vinha tratando no\n\npré-operatório de uma pneumonia sem melhora com antibiótico utilizado. Após internação, houve\nsubstituição desse antibiótico. No quarto dia de pós-operatório, relata dor abdominal em flanco\nesquerdo de forte intensidade associado à diarreia mucosanguinolenta. Qual o diagnóstico mais\nprovável?","options":{"A":"Diverticulite aguda.","B":"Colite isquêmica do cólon esquerdo.","C":"Infarto ênteromesentérico.","D":"Enterocolite pseudomembranosa.","E":"Invaginação intestinal."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-32443","number":"32443","sourceNumber":"32443","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Marque a alternativa correta.","options":{"A":"Cerca de 80% dos casos de hérnia inguinal ocorre em crianças com menos de 06 meses de\nvida.","B":"A indicação operatória de hérnia inguinal deve ser feita logo após o diagnóstico da mesma.","C":"No caso de hérnia inguinal encarcerada deve-se observar o tempo de ocorrência do\nencarceramento e tentar a redução manual do\nmesmo caso tenha ocorrido há menos de 12 horas,\nseguida de cirurgia definitiva em 24 horas.","D":"A fimose, do ponto de vista médico, só pode ser diagnosticada de certeza após 1 ano de vida. O\nmomento ideal de cirurgia é entre 12 e 18 meses.","E":"Todas estão corretas."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-23094","number":"23094","sourceNumber":"23094","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Dos fios cirúrgicos absorvíveis relacionados abaixo, qual apresenta reabsorção e perda\nda força tensil mais lenta?","options":{"A":"Categute.","B":"Polipropileno.","C":"Ácido poliglicólico.","D":"Mersilene.","E":"Categute cromado."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-8158","number":"8158","sourceNumber":"8158","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente de 45 dias de vida é atendido no pronto-socorro com história de ter evacuado\nfezes com sangue vivo há cerca de 3 horas.\nEstava irritado, chorando muito há 48 horas. Não\nrelata febre. Ao exame, a criança está chorando, irritada, o abdome está distendido e tenso à\npalpação. O exame da genitália revela aumento de volume em região inguinal direita. Baseado no\nmais provável diagnóstico, qual deve ser a conduta para este caso?","options":{"A":"Internar, parecer imediato do cirurgião pediátrico; provável quadro de invaginação intestinal.","B":"Administrar analgésicos e retorno ao pediatra; provável caso de alergia a leite de vaca e\npresença de hérnia inguinal à direita.","C":"Internar, parecer imediato do cirurgião pediátrico; provável quadro de hérnia inguinal\nencarcerada.","D":"Administrar analgésicos, retorno ao pediatra; provável caso de alergia a leite de vaca e presença\nde hidrocele.","E":"Internar, parecer imediato do cirurgião pediátrico; provável caso de torsão de testículo."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-355635","number":"355635","sourceNumber":"355635","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre as hérnias mesocólicas (HM), está correto afirmar que:","options":{"A":"Pacientes com HM raramente apresentam sintomas de obstrução aguda ou crônica do intestino\ndelgado.","B":"A parede anterior de uma HM direita é o mesocolon ascendente.","C":"Cerca de 75% das HM ocorrem no lado direito.","D":"Nas HM esquerdas, a artéria e a veia mesentéricas inferiores não são componentes integrantes\ndo saco herniário.","E":"As HM resultam de uma rotação anormal do intestino anterior e são classificadas em direita e\nesquerda."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-363943","number":"363943","sourceNumber":"363943","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Para o tratamento cirúrgico de fístula anorretal, o fator fundamental associado ao\nsucesso do tratamento da doença é:","options":{"A":"a localização anterior do trajeto fistuloso.","B":"a fistulectomia.","C":"a identificação do orifício interno do trajeto fistuloso.","D":"a passagem de sedenho em um primeiro tempo."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-353871","number":"353871","sourceNumber":"353871","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Lactente de 5 semanas de idade que ainda não excretou mecônio e apresenta sinais de\nconstipação que se manifestaram após o 1° mês de vida. Com base nesses sintomas, dadas as\nseguintes possíveis condições, é possível considerar:","options":{"A":"Evacuações infrequentes sempre indicam constipação intestinal.","B":"Obstrução intestinal devido à não eliminação de mecônio nas primeiras 24 horas.","C":"Constipação intestinal como sintoma benigno que não necessita de intervenção.","D":"Megacólon aganglionar congênito com segmento curto."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-353860","number":"353860","sourceNumber":"353860","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Uma fístula anal ou anorretal é uma conexão anormal entre o canal anal ou reto e a\npele ao redor do ânus. Sobre suas classificações, é CORRETO afirmar:","options":{"A":"Simples: é um tipo mais complicado de fístula que pode ter múltiplos canais ou tratos, ou pode\nenvolver outros órgãos ou estruturas na região pélvica, como a vagina ou a bexiga.","B":"Complexa: é um túnel ou canal direto que conecta o canal anal ou reto à pele ao redor do ânus.","C":"Alta: é um tipo de fístula complexa que se origina no reto e se estende até o canal anal,\ngeralmente acima do nível dos músculos do esfíncter.","D":"Cega: é um tipo de fístula complexa que se estende por toda a circunferência do ânus,\nconectando o canal anal a ambos os lados da pele ao redor do ânus."},"answer":"C","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-353859","number":"353859","sourceNumber":"353859","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Considerando a classificação dos graus de hemorroida de acordo com o prolapso do\ncanal anal, dadas as alternativas a seguir, a que descreve CORRETAMENTE o Grau I é:","options":{"A":"São irredutíveis e podem apresentar hemorroidas estranguladas.","B":"Apresentam um prolapso para fora do canal anal com defecação ou esforço, mas são eliminados\nespontaneamente.","C":"Apresentam um prolapso para fora do canal anal com defecação ou esforço e requerem redução\nmanual.","D":"São visualizados na anuscopia e podem inchar no lúmen, mas não geram um prolapso abaixo\nda linha pectínea."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-353797","number":"353797","sourceNumber":"353797","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Sobre Fissura Anal, julgue as seguintes afirmações como verdadeiras (V) ou falsas (F).\n\n1. A causa mais comum é o trauma na área anal, que pode ocorrer devido à constipação, esforço\ndurante as evacuações ou evacuações grandes.\n2. Doença de Crohn é uma causa primária de\nfissural anal. 3. Para pacientes com fissura secundária e/ou crônica, o tratamento pode ser\ncirúrgico. Sendo (V) para verdadeiro e (F) para falso, é CORRETO afirmar:","options":{"A":"1V ? 2F ? 3V.","B":"1V ? 2V ? 3F.","C":"1F ? 2F ? 3V.","D":"1F ? 2V ? 3F."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-354760","number":"354760","sourceNumber":"354760","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 30 anos de idade, sexo masculino,\nprocura atendimento médico para tratamento de\nquadro clínico de edema em membros inferiores\nde início há 2 anos. Nega traumas, comorbidades ou tratamento para doenças prévias. Ao exame\nfísico apresenta edema em pernas bilateralmente, sem alterações da pele, além de ausência de\nulcerações ou lesões cicatriciais. Ecodoppler venoso demonstrou dilatação do calibre venoso e\nincompetência valvular com consequente refluxo em veias poplíteas direita e esquerda, sem outras\nalterações no sistema venoso. Considerando o caso relatado e o sistema de classificação CEAP do\nAmerican Venous Forum, como se classifica este paciente?","options":{"A":"C3 Ep Ap Pr","B":"C4 Ep Ap Po","C":"C4 Ep Ad Po","D":"C3 Ep Ad Pr"},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-354772","number":"354772","sourceNumber":"354772","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Homem, 42 anos de idade, sem comorbidades, apresenta abscesso volumoso medindo\n4,0 X 5,0 cm de diâmetro em região supra\nelevadora esquerda. A conduta, neste momento, é","options":{"A":"excluir diverticulite ou apendicite com supuração para pelve.","B":"drenagem ampla em ponto mais próximo da margem anal.","C":"drenagem de abscesso e criação de um estoma.","D":"administrar antibioticoterapia considerando que ainda não apresenta sinais externos de massa\nou inflamação; reservar drenagem cirúrgica para\nos casos que não respondem ao tratamento\nclínico."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-353807","number":"353807","sourceNumber":"353807","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"De acordo com os graus de obesidade: I. Obesidade grau I: IMC 30 ? 35,9. II.\nObesidade grau III: IMC > 40. III. Sobrepeso: IMC 25 ? 29,9. Das proposições acima:","options":{"A":"Apenas II está correta.","B":"Apenas II e III estão corretas.","C":"Apenas I e II estão corretas.","D":"Apenas III está correta."},"answer":"B","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-321538","number":"321538","sourceNumber":"321538","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Leia o caso clínico. Paciente do sexo feminino, 30 anos, é encaminhada ao\npronto-socorro com quadro de dor e inchaço na perna esquerda há 3 dias. Paciente nega\n\ncomorbidades associadas e uso de quaisquer tipos de medicamentos de uso contínuo. Ao exame\nfísico na admissão, o médico nota um edema\nimportante de todo membro inferior esquerdo, desde\na raiz da coxa e com empastamento da panturrilha. Diante do quadro apresentado um ecoddopler\nvenoso mostrou sinais de trombose venosa profunda aguda ilíaco-femoral esquerda. Considerando\ntodo o quadro clínico podemos considerar como hipótese diagnóstica","options":{"A":"a síndrome de May-Turner.","B":"a trombose de aorta.","C":"a doença de Buerger.","D":"a doença de Takayasu."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-321548","number":"321548","sourceNumber":"321548","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"A identificação e o conhecimento sobre as válvulas de Houston são importantes, pois","options":{"A":"elas delimitam a transição do reto para o sigmoide.","B":"a terceira válvula de Houston é o local de biópsia para auxiliar no diagnóstico da\nesquistossomose.","C":"essas válvulas são a origem dos abscessos anorretais.","D":"a segunda válvula de Houston sugere a delimitação entre reto intra e extraperitoneal."},"answer":"D","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-4-331974","number":"331974","sourceNumber":"331974","collectionBlock":"medcurso:medcurso-cirurgia-cir-4","collectionLabel":"Medcurso · CIR 4","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 4","subtopic":"","stem":"Paciente constipado crônico, apresentando prolapso hemorroidário às evacuações, de\nredução espontânea, sem outros sintomas associados. O tratamento, neste caso, deve ser:","options":{"A":"Ligadura elástica do mamilo hemorroidário + orientação dietética.","B":"Orientação dietética.","C":"Hemorroidectomia + orientação dietética.","D":"Eletrocoagulação + orientação dietética.","E":"Venotônicos + orientação dietética."},"answer":"A","source":"Cirurgia/CIR 4/CIR 4.txt","sourceLabel":"Medcurso · CIR 4","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 4","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
